(window.GIM_TS=window.GIM_TS||{})["Sukkah.0"]={"from":0,"a":[["\u0003סוכה שהיא,\u0004 כלומר: שהסכך שלה, שהוא עיקר מצוותה, \u0003גבוהה למעלה מעשרים אמה\u0004 — \u0003פסולה. ור' יהודה מכשיר.\u0004","וכן סוכה \u0003שאינה גבוהה עשרה טפחים,\u0004 או \u0003שאין לה שלש דפנות,\u0004 או \u0003שחמתה,\u0004 כלומר: אור החמה הנכנס לתוכה דרך הסכך \u0003מרובה מצלתה\u0004 (צילה) — \u0003פסולה.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת עירובין הלכה דומה: \u0003מבוי שהוא,\u0004 כלומר: הקורה שעושים בראשו הפונה לרשות הרבים כדי להתיר את הטלטול בו \u0003גבוה מעשרים אמה\u0004 — \u0003ימעט\u0004 מגובה הקורה כדי להכשיר את מבוי בטלטול. \u0003ר' יהודה אומר: אינו צריך,\u0004 שאף אם מקום הנחת הקורה גבוה מעשרים אמה — כשר.","ומתוך שעיקר תוכנן של הלכות אלה בסוכה ובמבוי דומה לכאורה, שואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003גבי סוכה דתני\u0004 \u0005[ששנה]\u0006 במשנתנו בנוסח פסקני שסוכה זו \u0003פסולה, ומאי שנא\u0004 \u0005[במה שונה]\u0006 ל\u0003גבי מבוי דתני תקנתא\u0004 \u0005[ששנה תקנה]\u0006 שיש למעט מן הגובה כדי להכשיר, ולא אמר כן בסוכה?","ומשיבים: \u0003סוכה\u0004 כיוון שהיא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003פסולה,\u0004 כי בהלכה זו אפשר לומר קביעה מוחלטת וגמורה. ואולם \u0003מבוי\u0004 שכל עניינו (הן לאיסור והן להיתר) הוא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ואיסור הטלטול במבוי כזה נשנה לראשונה במשנה האמורה, לכך אין מקום לומר לשון \"פסול\" בהחלטיות, ולכן \u0003תני תקנתא\u0004 \u0005[שנה תקנה].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003בדאורייתא נמי תני תקנתא\u0004 \u0005[בדברי תורה גם כן שונה\u0006 התנא לעיתים בנוסח של \u0005תקנה],\u0006 \u0003מיהו\u0004 \u0005[ואולם]\u0006 \u0003סוכה דנפישי מילתא\u0004 \u0005[שמרובים דבריה,\u0006 ענייניה\u0005]\u0006 האמורים במשנה זו (גבוהה, נמוכה, שאין לה שלוש דפנות ושחמתה מרובה) — לכך \u0003פסיק ותני\u0004 \u0005[פסק ושנה]\u0006 לשון \u0003פסולה,\u0004 שלא רצה להאריך ולשנות מה תקנתו של כל אחד מהפסולים האמורים, ואילו \u0003מבוי\u0004 ש\u0003לא נפיש מיליה\u0004 \u0005[מרובים דבריו,\u0006 ענייניו\u0005]\u0006 האמורים באותה משנה, ואין מדובר אלא אודות פסול קורה גבוהה, לכך \u0003תני תקנתא\u0004 \u0005[שנה תקנה],\u0006 שהרי די במלה האחת: ימעט.","לאחר בירור לשוני זה באים לגופה של ההלכה, ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה],\u0006 מה מקור ההלכה שאין לעשות סוכה למעלה מעשרים אמה?","\u0003אמר רבה:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 כסיבה לחובת הישיבה בסוכה: \u0003\"למען ידעו דרתיכם כי בסכות הושבתי את בני ישראל\u0004 בהוציאי אותם מארץ מצרים\u0003\"\u0004 (ויקרא כג, מג). וכך יש להבין: סוכה שגובהה \u0003עד עשרים אמה, אדם יודע שהוא דר בסוכה,\u0004 משום שאף בלא משים, נתקלת עינו בסכך של הסוכה ובכך הריהו נעשה מודע לסוכה ולמצוותה, ואילו \u0003למעלה מעשרים אמה אין אדם יודע שדר בסוכה משום דלא שלטא בה עינא\u0004 \u0005[שאין העין שולטת בה],\u0006 שכן בגובה רב זה אין אדם שם לב.","\u0003ר' זירא אמר\u0004 טעם אחר \u0003מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005];\u0006 נאמר: \u0003\"וסכה תהיה לצל יומם מחרב\u0004 ולמחסה ולמסתור מזרם וממטר\u0003\"\u0004 (ישעיה ד, ו). \u0003עד עשרים אמה אדם יושב בצל סוכה,\u0004 כלומר: בצל הסכך, \u0003למעלה מעשרים אמה אין אדם יושב\u0004 עוד \u0003בצל\u0004 ה\u0003סוכה אלא בצל\u0004 ה\u0003דפנות,\u0004 שמפני גובהן הן יוצרות צל תמידי, ואין צל הסכך מעלה או מוריד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 בתמיהה: \u0003אלא מעתה\u0004 לשיטתך שצריך לשבת ממש בצל הסכך, אם כן, \u0003העושה סוכתו בעשתרות קרנים\u0004 מקום המצוי בין שני הרים המצילים עליו מכל צד, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דלא הוי\u0004 \u0005[שאין זו]\u0006 \u0003סוכה\u0004 כשרה, כיון שאינו יושב בצל הסכך?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: אין הדברים דומים, \u0003התם\u0004 \u0005[שם]\u0006 \u0003דל\u0004 \u0005[הוצא]\u0006 את \u0003עשתרות קרנים\u0004 שהן מסתירות מבחוץ הרי \u0003איכא\u0004 \u0005[יש]\u0006 על כל פנים \u0003צל\u0004 סכך ה\u0003סוכה,\u0004 לפי שהסוכה בנויה כדין, אלא שגורם חיצוני משפיע כאן, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בסוכה הגבוהה מעשרים אמה, \u0003דל\u0004 \u0005[הסר]\u0006 את ה\u0003דפנות\u0004 ושוב \u0003ליכא\u0004 \u0005[אין\u0006 עוד\u0005]\u0006 \u0003צל סוכה,\u0004 שהרי אין הסכך מצל על קרקע הסוכה, אלא במקום דפנותיה.","\u0003ורבא אמר\u0004 טעם אחר, \u0003מהכא\u0004 \u0005[מכאן\u0006 מכתוב זה\u0005],\u0006 שנאמר: \u0003\"בסכת תשבו שבעת ימים\"\u0004 (ויקרא כג, מב). \u0003אמרה תורה: כל שבעת הימים צא מדירת קבע\u0004 שאתה יושב בה כל השנה \u0003ושב בדירת ארעי\u0004 שהיא היא הסוכה. \u0003עד עשרים אמה אדם עושה דירתו דירת ארעי\u0004 שעד גובה זה אפשר לבנות סוכה רופפת כדירת ארעי, אולם לצורך בנין סוכה הגבוהה \u0003למעלה מעשרים אמה אין אדם עושה דירתו דירת ארעי אלא דירת קבע\u0004 ואין זו סוכה כראוי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 לשיטתך, אם \u0003עשה מחיצות של ברזל וסיכך על גבן, הכי נמי דלא הוי\u0004 \u0005[כך גם כן שלא תהא\u0006 זו\u0005]\u0006 \u0003סוכה?\u0004 שהרי לדעתך סוכה העשוייה כדירת קבע פסולה, ודבר זה לא מצאנו כלל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הכי קאמינא לך\u0004 \u0005[כך אומר אני לך],\u0006 זוהי שיטתי: \u0003עד עשרים אמה\u0004 ש\u0003אדם עושה דירתו\u0004 כרגיל \u0003דירת ארעי,\u0004 גם \u0003כי עביד ליה\u0004 \u0005[כאשר עושה אותה]\u0006 כ\u0003דירת קבע, נמי נפיק\u0004 \u0005[גם כן יוצא]\u0006 ידי חובה, שהרי סוג זה של מבנה הוא כמבנה ארעי, אולם \u0003למעלה מעשרים אמה\u0004 ש\u0003אדם עושה דירתו דירת קבע\u0004 גם \u0003כי עביד ליה\u0004 \u0005[כאשר הוא עושה אותה]\u0006 כ\u0003דירת ארעי נמי לא נפיק\u0004 \u0005[גם כן אינו יוצא]\u0006 ידי חובה, שבדרך כלל מבנה מעין זה עשוי כדירת קבע."],["\u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003כ\u0004דברי \u0003רבה לא אמרי\u0004 \u0005[אמרו]\u0006 ולא סמכו על הכתוב \"למען ידעו דורותיכם\" (ויקרא כג, מג), כי לדעתם משמעות הכתוב \u0003ההוא\u0004 שיש לשבת בסוכה, כדי שתהיה \u0003ידיעה לדורות היא,\u0004 כלומר: כדי שידעו הדורות הבאים על יציאת מצרים, ואין זו ידיעה בדבר הסוכה עצמה.","וכן, כולם \u0003כ\u0004דברי \u0003ר' זירא,\u0004 הלומד זאת מן הפסוק \"וסוכה תהיה לצל יומם מחורב\", \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרי\u0004 \u0005[אמרו],\u0006 כי לדעתם הכתוב \u0003ההוא, לימות המשיח הוא דכתיב\u0004 \u0005[שנאמר],\u0006 ופירושו: שיהא הקדוש ברוך הוא מגן ומחסה לישראל, ואינו עוסק במהותה של הסוכה.","ושואלים: \u0003ו\u0004מה משיב \u0003ר' זירא\u0004 לטענה פשוטה זו? ומשיבים: אם הפסוק מדבר רק בדרך משל ודימוי, \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 כעניינו: \u0003\"וחפה תהיה לצל יומם, ומאי\u0004 \u0005[ומה]\u0006 למדנו מן הביטוי \u0003\"וסכה תהיה לצל יומם\"\u0004 (ישעיה ד, ו), \u0003שמעת מינה תרתי\u0004 \u0005[שומע אתה מכאן שני\u0006 דברים\u0005],\u0006 הן לגוף הדברים, שיהא הקדוש ברוך הוא כסוכת כבוד לישראל, ואולם בדרך אגב אפשר ללמוד מכאן גם על מבנה הסוכה.","וכן, \u0003כ\u0004דברי \u0003רבא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרי\u0004 \u0005[אמרו]\u0006 החכמים האחרים, \u0003משום קושיא\u0004 \u0005[הקושיה]\u0006 שהקשה עליו \u0003אביי\u0004 והראה שיש קושי בשיטתו. וכיון שבכל שיטה קיים קושי מסויים, מובן איפוא מפני מה לא רצו החכמים האחרים להחזיק בה.","ומבררים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר ר' יאשיה אמר רב: מחלוקת\u0004 זו בין ר' יהודה לחכמים בכשרות סוכה גבוהה, הריהי דווקא \u0003בשאין דפנות\u0004 הסוכה \u0003מגיעות\u0004 עד \u0003לסכך,\u0004 אלא הסכך גבוה הרבה מעל הדפנות, \u0003אבל\u0004 אם היו \u0003הדפנות מגיעות לסכך אפילו\u0004 היתה \u0003למעלה מעשרים אמה — כשירה. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי],\u0006","\u0003כ\u0004שיטת \u0003רבה,\u0004 ש\u0003אמר\u0004 שפסול סוכה גבוהה הוא \u0003משום\u0004 ש\u0003לא שלטא\u0004 \u0005[שולטת]\u0006 \u0003בה עינא\u0004 \u0005[העין],\u0006 \u0003וכיון\u0004 שה\u0003דפנות מגיעות לסכך,\u0004 בדרך הטבע \u0003משלט שלטא\u0004 \u0005[שולטת]\u0006 \u0003בה עינא\u0004 \u0005[העין],\u0006 שעינו של אדם מבחינה גם בדפנות וגם בסכך אף כשהם בגובה רב, אולם אם הסכך גבוה מעל הדפנות, אין אדם מבחין בסכך כלל.","וכן, \u0003כמאן אזלא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת]\u0006 אותה הלכה ש\u0003אמר רב הונא אמר רב: מחלוקת\u0004 זו בגובהה של הסוכה היא דווקא \u0003בשאין בה\u0004 בשטחה \u0003אלא ארבע אמות על ארבע אמות\u0004 במדוייק, \u0003אבל\u0004 אם \u0003יש בה יותר מארבע אמות על ארבע אמות, אפילו למעלה מעשרים אמה\u0004 — \u0003כשרה. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 —","\u0003כ\u0004שיטת \u0003ר' זירא,\u0004 ש\u0003אמר: משום צל הוא, וכיון דרויחא\u0004 \u0005[\u0006שהסוכה \u0005מרווחת],\u0006 ששטחה גדול — \u0003איכא\u0004 \u0005[יש]\u0006 \u0003צל סוכה\u0004 שם, שבחלק מן השטח יש צל שמקורו בסכך.","וכן, \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו]\u0006 ההלכה ש\u0003אמר רב חנן בר רבה אמר רב: מחלוקת\u0004 זו, הריהי דווקא \u0003בשאינה מחזקת אלא כדי ראשו\u0004 של אדם \u0003ורובו\u0004 (רוב גופו) \u0003ושולחנו,\u0004 שבפחות מזה אין הכשר סוכה, \u0003אבל מחזקת יותר מכדי ראשו ורובו ושולחנו, אפילו למעלה מעשרים אמה\u0004 — \u0003כשרה. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 יש לפרש הלכה זו — ש\u0003לא כחד\u0004 \u0005[כ\u0006שיטת \u0005אחד\u0006 מהם\u0005],\u0006 שאין להסביר הלכה זו לפי אף אחד מן הטעמים שנתנו החכמים השונים בפסול סוכה גבוהה.","לגופן של הלכות אלה מעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שדבר זה ברור שהלכה זו של \u0003ר' יאשיה פליגא\u0004 \u0005[חולקת]\u0006 על אלו של \u0003רב הונא ורב חנן בר רבה, דאינהו קא יהבי שעורא במשכא\u0004 \u0005[ש\u0006הרי \u0005הם נותנים שיעור בשטחה\u0006 של הסוכה\u0005]\u0006 \u0003ואיהו לא קא יהיב שעורא במשכא\u0004 \u0005[והוא אינו נותן שיעור בשטחה]\u0006 אלא קובע הלכה לפי מבנה הדפנות.","\u0003אלא רב הונא ורב חנן בר רבה\u0004 עצמם, האם \u0003נימא\u0004 \u0005[נאמר]\u0006 כי \u0003בהכשר סוכה קא מיפלגי\u0004 \u0005[נחלקו],\u0006 שמחלוקתם תלוייה בשאלה מהו גודלה של סוכה כשירה, \u0003דמר\u0004 \u0005[שחכם זה],\u0006 רב הונא \u0003סבר\u0004 כי \u0003הכשר סוכה בארבע אמות\u0004 על ארבע אמות לפחות, \u0003ומר\u0004 \u0005[וחכם זה],\u0006 רב חנן בר רבה \u0003סבר\u0004 כי \u0003הכשר סוכה\u0004 הוא אף כשאינה \u0003מחזקת\u0004 אלא כדי \u0003ראשו ורובו ושולחנו?\u0004","את ההצעה הזו דוחים: \u0003לא,\u0004 אין צורך לפרש כך, שאפשר לומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003הכשר סוכה\u0004 דיו במחזקת \u0003ראשו ורובו ושולחנו. והכא בהא קא מיפלגי\u0004 \u0005[וכאן ב\u0006דבר \u0005זה נחלקו]:\u0006 \u0003דמר\u0004 \u0005[שחכם זה],\u0006 רב חנן בר רבה \u0003סבר במחזקת ראשו ורובו ושולחנו פליגי\u0004 \u0005[נחלקו]\u0006 חכמים ור' יהודה בכשרות סוכה הגבוהה מעשרים אמה, \u0003אבל\u0004 אם היה שיעורה \u0003יותר מ\u0004כדי \u0003ראשו ורובו ושולחנו — דברי הכל כשרה,\u0004","\u0003ומר\u0004 \u0005[וחכם זה],\u0006 רב הונא \u0003סבר\u0004 כי \u0003מראשו ורובו ושולחנו עד ארבע אמות פליגי\u0004 \u0005[נחלקו],\u0006 \u0003אבל\u0004 אם היה בשטחה \u0003יותר מארבע אמות — דברי הכל כשרה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעות חכמים אלה מן הברייתא. שנינו: \u0003סוכה שהיא גבוהה למעלה מעשרים אמה — פסולה, ור' יהודה מכשיר\u0004 אפילו היתה גבוהה \u0003עד ארבעים וחמשים אמה.\u0004","\u0003אמר ר' יהודה: מעשה בהילני המלכה \u0004שהיתה \u0003בלוד שהיתה סוכתה גבוהה מעשרים אמה, והיו זקנים נכנסין ויוצאין לשם ולא אמרו לה דבר\u0004 על שאין הסוכה כשרה. \u0003אמרו לו:\u0004 וכי \u0003משם\u0004 מביא אתה \u0003ראיה?\u0004 הלא הילני \u0003אשה היתה ופטורה מן הסוכה,\u0004 ולכן לא היתה הסוכה חייבת מלכתחילה להיות כשירה כדינה, ולא היתה איפוא כל סיבה להעיר לה על כך. \u0003אמר להן: והלא שבעה בנים הוו\u0004 \u0005[היו]\u0006 \u0003לה\u0004 והם הלא היו זקוקים לסוכה כשרה, \u0003ועוד:\u0004 והרי \u0003כל מעשיה לא עשתה אלא על פי חכמים.\u0004","בטרם ניגש לבירור הדברים לענייננו, שואלים לגוף הברייתא: \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 את התוספת \u0003\"ועוד כל מעשיה לא עשתה אלא על פי חכמים\",\u0004 מה עניינה של הוספה זו לדברי ר' יהודה?","ומשיבים: \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 ר' יהודה: \u0003כי\u0004 אם \u0003תאמרו; בנים קטנים היו\u0004 להילני \u0003וקטנים פטורין מן הסוכה\u0004 ולכן לא אמרו לה חכמים דבר, אולם \u0003כיון\u0004 ש\u0003שבעה הוו\u0004 \u0005[היו],\u0006 \u0003אי אפשר\u0004 ש\u0003לא הוי בהו חד\u0004 \u0005[היה בהם אחד]\u0006 \u0003שאינו צריך לאמו.\u0004 כי גם אם נולדו לה שבעת הבנים בזה אחר זה שנה אחר שנה, הלא הגדול שבהם היה לפחות בן שבע, ובגיל זה הלא אינו צריך לאמו תמיד, והלכה היא שקטן שאינו צריך לאמו, יש לחנכו במצות סוכה מדברי סופרים.","\u0003וכי תימרו\u0004 \u0005[ואם תאמרו];\u0006 הלא \u0003קטן שאינו צריך לאמו,\u0004 רק \u0003מדרבנן הוא דמיחייב\u0004 \u0005[מדברי סופרים הוא שמתחייב]\u0006 \u0003ואיהי בדרבנן לא משגחה\u0004 \u0005[והיא\u0006 הילני \u0005ב\u0006דברי \u0005חכמים אינה משגיחה],\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שהרי אמר \u0003ועוד, כל מעשיה לא עשתה אלא על פי חכמים,\u0004 ולענין השיטות ההלכתיות שבררנו;","\u0003בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאומר]\u0006 כי \u0003בשאין\u0004 ה\u0003דפנות מגיעות לסכך מחלוקת,\u0004 הרי אפשר להסביר שכך היתה סוכתה של הילני המלכה, כי \u0003דרכה של מלכה לישב בסוכה שאין דפנות מגיעות לסכך,\u0004"],["\u0003משום אוירא\u0004 \u0005[אויר]\u0006 שתהא הסוכה מאווררת על יד משב הרוח הנכנס בין הכתלים לסכך. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003בסוכה קטנה מחלוקת,\u0004 ולפי זה, סוכתה של הילני המלכה קטנה היתה, \u0003וכי דרכה של מלכה לישב בסוכה קטנה\u0004 ששטחה פחות מארבע אמות? \u0003אמר רבה בר רב אדא: לא נצרכה אלא לסוכה העשויה קיטוניות קיטוניות\u0004 שהסוכה כולה היתה גדולה, אולם היתה מחולקת למדורים קטנים, ששטח כל אחד מהם פחות מארבע על ארבע אמות.","ושוב תוהים: \u0003וכי דרכה של מלכה לישב בסוכה העשויה קיטוניות קיטוניות\u0004 בלא להשאיר לעצמה אולם רחב שבו תוכל להסב עם בני ביתה ומשרתיה? \u0003אמר רב אשי: לא נצרכה אלא לקיטוניות שבה.\u0004 שהיתה זו סוכה גדולה והיו בה גם חדרים קטנים צמודים לה.","ובמין סוכה זו נחלקו; \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003בניה בסוכה מעליא הוו יתבי\u0004 \u0005[מעולה,\u0006 כשירה, \u0005היו יושבים],\u0006 שהיה רחבה גדול והיתה כשירה לפי שיטות אלה, \u0003ואיהי יתבה\u0004 \u0005[והיא\u0006 עצמה \u0005ישבה]\u0006 \u0003בקיטוניות משום צניעותא\u0004 \u0005[צניעות],\u0006 שלא היתה מצויה תמיד בחוץ אלא בחדר קטן, \u0003ומשום הכי\u0004 \u0005[כך]\u0006 \u0003לא אמרי\u0004 \u0005[אמרו]\u0006 \u0003לה דבר.\u0004 שאף אם אמנם היו הקיטוניות קטנות משיעור הרוחב הראוי לגבי גובה הסוכה, מכל מקום, מכיוון שלא ישבו בהם הבנים — הרי הכל כשר. \u0003ור' יהודה סבר\u0004 כי \u0003בניה\u0004 לעיתים \u0003גבה הוו יתבי\u0004 \u0005[עמה\u0006 בקיטוניות \u0005היו יושבים]\u0006 \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא אמרי\u0004 \u0005[אמרו]\u0006 \u0003לה דבר\u0004 והרי זו הוכחה שסוכה הגבוהה מעשרים אמה כשרה. ואם כן, אין להוכיח מתוספתא זו בדבר טעמי מחלוקת ר' יהודה וחכמים בסוכה קטנה.","\u0003אמר רב שמואל בר יצחק: הלכה\u0004 היא, ש\u0003צריכה\u0004 הסוכה \u0003שתהא מחזקת\u0004 בשטחה \u0003ראשו\u0004 של אדם \u0003ורובו\u0004 (רוב גופו) \u0003ושולחנו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא\u0004 בתמיהה: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אומר אתה דבר זה, האם \u0003כ\u0004שיטת \u0003בית שמאי?\u0004 שנחלקו בית הלל ובית שמאי בנושא זה ולשיטת בית הלל די שיהיה בשטח הסוכה כדי ראשו ורובו ואין צריך שיהיה בה גם מקום לשולחנו, ואתה פוסק הלכה כדעת בית שמאי, שכרגיל נדחתה מן ההלכה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אלא כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?!\u0006 אכן, כשיטת בית שמאי היא, אלא שכאן הלכה כמותם.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שחילופי דברים אלה היו בנוסח אחר קצת; \u0003אמר ר' אבא:\u0004 זה ש\u0003אמר לך\u0004 שיטה זו \u0003מני\u0004 \u0005[מי הוא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שמואל בר יצחק: \u0003בית שמאי היא,\u0004 ובכל זאת \u0003לא תזוז מינה\u0004 \u0005[ממנה],\u0006 כי הלכה קבועה היא. מכל מקום, לפי כל נוסח שהוא, מובן כי הלכה זו שנויה במחלוקת בית הלל ובית שמאי.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על השערה זו \u0003רב נחמן בר יצחק: ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה כי אכן \u0003בית שמאי ובית הלל בסוכה קטנה פליגי\u0004 \u0005[נחלקו]\u0006 ובשאלה מהו שיעורה הקטן ביותר של סוכה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בסוכה גדולה\u0004 שיש בה כשלעצמה שיעור מספיק \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003ו\u0004מחלוקתם \u0003כגון דיתיב אפומא דמטולתא\u0004 \u0005[שיושב על פי,\u0006 פתח, \u0005הסוכה]\u0006 \u0003ושולחנו בתוך הבית.\u0004 ובכך נחלקו: ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003שמא ימשך אחר שלחנו\u0004 תוך כדי אכילה, וימצא לבסוף ראשו ורובו חוץ לסוכה, \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","\u0003ודיקא נמי\u0004 \u0005[ומדוייק גם כן]\u0006 הסבר זה לפי סגנון המשנה, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בה\u0005]:\u0006 \u0003מי שהיה ראשו ורובו ב\u0004תוך \u0003הסוכה ושולחנו בתוך הבית, בית שמאי פוסלין ובית הלל מכשירין. ואם איתא\u0004 \u0005[ואם יש\u0006 מקום\u0005]\u0006 להניח שהמחלוקת כאן היתה לגבי שיעורה של הסוכה, אם כן אין סגנון הדברים מתאים, שהרי לפי הנחה זו, סוכה \u0003המחזקת\u0004 ראשו ורובו \u0003ו\u0004ש\u0003אינה מחזקת מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 ואם כן מסתבר שמחלוקת זו לא היתה כלל בדבר שיעורה של סוכה.","על מסקנה זו מקשים: \u0003ובסוכה קטנה\u0004 האם \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 בית שמאי ובית הלל? \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא אחרת: סוכה ה\u0003מחזקת ראשו ורובו ושולחנו — כשרה. רבי אומר: עד שיהא בה ארבע אמות על ארבע אמות.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנינו\u0006 בברייתא \u0005אחרת];\u0006 \u0003רבי אומר: כל סוכה שאין בה ארבע אמות על ארבע אמות\u0004 — \u0003פסולה. וחכמים אומרים: אפילו אינה מחזקת אלא ראשו ורובו\u0004 — \u0003כשרה. ואילו שולחנו לא קתני\u0004 \u0005[שנה]\u0006 בברייתא זאת. ואם כן \u0003קשיין אהדדי\u0004 \u0005[קשות הן\u0006 הברייתות \u0005זו על זו],\u0006 שהרי לחכמים שני שיעורים שונים. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המונה את שולחנו כשיטת \u0003בית שמאי\u0004 היא, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שאינה מונה את שולחנו, כשיטת \u0003בית הלל\u0004 היא. הרי שנחלקו בית שמאי ובית הלל גם בשיעור סוכה.","\u0003אמר מר זוטרא: מתניתין נמי דיקא\u0004 \u0005[משנתנו\u0006 עצמה \u0005מדוייקת]\u0006 שאכן נחלקו בית שמאי ובית הלל גם בשיעור סוכה, \u0003מדקתני\u0004 \u0005[ממה ששנינו]\u0006 כי \u0003בית שמאי פוסלין ובית הלל מכשירין, ואם איתא\u0004 \u0005[יש]\u0006 לומר שנחלקו במקרה המסויים של אדם היושב לפי שעה בפתח הסוכה, אם כן, לשון \u0003בית שמאי אומרים: לא יצא, ובית הלל אומרים: יצא, מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005].\u0006 ולשון \"פוסלין\" ו\"מכשירין\" אינה יכולה להתייחס אלא לדין הסוכה עצמה.","ומקשים: \u0003ואלא קשיא\u0004 \u0005[קשה]\u0006 הלשון \u0003\"מי שהיה\u0004 ראשו ורובו\u0003\"\u0004, שממנו מובן כי נושא המחלוקת הוא במקום הישיבה בסוכה, שכן לא נאמר לשון \"מחזקת ראשו ורובו\", שממנו משמע כי המחלוקת נסובה על גודל הסוכה!","ומשיבים: \u0003לעולם\u0004 יש לומר כי \u0003בתרתי פליגי\u0004 \u0005[בשני\u0006 הדברים הם \u0005חלוקים];\u0006 \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 גם \u0003בסוכה קטנה\u0004 ביחס לשיעור הכשר הסוכה, \u0003ופליגי\u0004 \u0005[וחלוקים\u0006 הם\u0005]\u0006 גם \u0003בסוכה גדולה\u0004 ביחס למקום הישיבה בסוכה. \u0003וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003מי שהיה ראשו ורובו בסוכה ושולחנו בתוך הבית — בית שמאי אומרים: לא יצא, ובית הלל אומרים: יצא, ו\u0004סוכה \u0003שאינה מחזקת\u0004 בשטחה \u0003אלא כדי ראשו ורובו בלבד — בית שמאי פוסלין, ובית הלל מכשירין.\u0004 ובדרך זו מובנת המשנה לפי כל השיטות.","אגב הדיון בנושא זה שואלים \u0003מאן תנא להא\u0004 \u0005[מי שנה את\u0006 הברייתא \u0005הזו]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003בית שאין בו ארבע אמות על ארבע אמות\u0004 אינו נכנס כלל להגדרת \"בית\", וכל מקום שנאמר בתורה או במשנה \"בית\" — אינו חל עליו, ולכן \u0003פטור מן המזוזה,\u0004 ופטור \u0003מן\u0004 החובה לעשות \u0003מעקה\u0004 לגגו \u0003ואינו מטמא בנגעים\u0004 (נגעי בתים), \u0003ואינו נחלט בבתי ערי חומה,\u0004 כדין המוכר בית בעיר חומה שאם לא פדאו בתוך שנה — נעשה הבית קנין חלוט (גמור) של הקונה (ויקרא כה, כט-לא).","\u0003ואין חוזרין עליו מעורכי המלחמה,\u0004 כמו שנאמר שהבונה בית ולא חנכו יכול לשוב לביתו (דברים כ, ה). \u0003ואין מערבין בו,\u0004 כלומר: אין צורך לעשות עירוב עבור בית זה. שכדי להתיר לטלטל מבית של אחד לבית של אחר באותה חצר, צריכים לערב יחד ולהניח את העירוב בתוך אחד הבתים, וזה אינו קרוי בית. \u0003ואין משתתפין בו\u0004 שחצרות ובתים הפתוחים למבוי (סימטה) אחת צריכים לשתף עצמם על ידי מאכל אחד כדי להתיר את הטלטול במבוי בשבת, ובית זה אינו בכלל הצריך שיתוף \u0003ו\u0004אף \u0003אין מניחין בו\u0004 את ה\u0003עירוב\u0004 שגבו מבני החצרות לצורך הכשר המבוי בטלטול, מפני שאינו בית."],["\u0003ואין עושין אותו עיבור בין שתי עיירות.\u0004 שכל שתי עיירות הרחוקות זו מזו יותר ממאה ארבעים ואחת אמות ושליש, אין הדר באחת מהן יכול להחשיבן כעיירה אחת ואינו יכול למדוד את תחום שבת שלו מגבול העיירה השניה ואילך. אבל אם יש ביניהם בית העומד בתוך שבעים אמה ושיריים לשתיהן, הריהו מצרפן להיות כעיירה אחת לענין מדידת תחום שבת, ובית שאין בו ארבע אמות אינו חשוב לענין זה. \u0003ואין האחין והשותפין חולקין בו\u0004 שהוא קטן מכדי שיוכלו לחלקו.","\u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי הברייתא הזו כשיטת \u0003רבי היא ולא רבנן\u0004 \u0005[חכמים],\u0006 שהרי רבי הוא הסבור שסוכה צריכה להיות לפחות ארבע אמות, ובפחות מכן אינו נחשב. את ההצעה הזו דוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהברייתא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 שאף בית הפחות מארבע אמות ראוי \u0003אלא לענין סוכה,\u0004 ש\u0003דירת ארעי היא\u0004 ובדירת ארעי אפשר להצטמצם גם במקום קטן \u0003אבל לגבי בית\u0004 ש\u0003דירת קבע הוא — אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 \u0003דאי אית ביה\u0004 \u0005[שאם יש בו]\u0006 \u0003ארבע אמות על ארבע אמות — דיירי ביה אינשי\u0004 \u0005[דרים בו אנשים]\u0006 ודינו כבית גמור, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא דיירי ביה אינשי\u0004 \u0005[דרים בו אנשים]\u0006 ואינו נחשב כלל.","כיון שהוזכרה ברייתא מרובת עניינים זו, מבארים אותה מעט לגופה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בית שאין בו ארבע אמות \u0003פטור מן המזוזה, ומן המעקה, ואין מטמא בנגעים, ואינו נחלט בבתי ערי חומה, ואין חוזרין עליו מעורכי המלחמה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — משום שלשון \u0003\"בית\" כתיב בהו בכולהו\u0004 \u0005[כתוב בהן בכולן],\u0006 בכל המקראות המדברים בדינים אלה בתורה, — ובפחות מארבע אמות אינו קרוי בית.","\u0003ו\u0004מדברי סופרים \u0003אין מערבין בו ואין משתתפין בו ואין מניחין בו עירוב. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — משום שהוא \u0003לא חזי\u0004 \u0005[ראוי]\u0006 \u0003לדירה,\u0004 וכל דין העירוב הריהו לצורך עשיית החצר כדירה אחת גדולה המשותפת לבני כל הבתים שבה, ודבר זה אינו יכול להיעשות אלא באמצעות נתינת העירוב בתוך מקום הנחשב כ\"בית\". ועוד בבירור לשון הברייתא: ממה שאמר שאין מניחים בה עירוב משמע כי רק \u0003עירובי חצרות\u0004 (שהם הקרויים עירוב סתם) — \u0003אין מניחים בו, אבל שיתוף\u0004 שמשתתפין כל בני החצרות במבוי \u0003מניחין בו.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — משום שהוא \u0003לא גרע\u0004 \u0005[גרוע]\u0006 בדינו \u0003מחצר שבמבוי\u0004 שאף שאינה מקורה ואינה ראויה לדירה, מכל מקום הריהי כשרה לכך. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת עירובין: \u0003עירובי חצרות\u0004 מניחים \u0003בחצר, שיתופי מבוי במבוי.\u0004","\u0003והוינן\u0004 \u0005[ועסקנו,\u0006 והתקשינו\u0005]\u0006 \u0003בה\u0004 בשאלה זו במקומה, כיצד אפשר לומר שמניחים \u0003עירובי חצרות בחצר? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנותן עירובו\u0004 אפילו \u0003בבית שער\u0004 (בית קטן העשוי לשמור את שער החצר) או \u0003אכסדרה\u0004 (מבנה שיש לו גג ומחיצות בלתי שלימות) או \u0003מרפסת\u0004 שבקומה שניה — \u0003אינו עירוב,\u0004 לפי שאין אלה נחשבים לבית, \u0003והדר שם\u0004 באחד מאלה \u0003אינו אוסר\u0004 על האחרים אם לא עירב לפי שאינו נחשב כדייר.","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את לשון המשנה כך: \u0003עירובי חצרות\u0004 מניחן \u0003בבית\u0004 גמור \u0003שבחצר, ושיתופי מבואות\u0004 מניח אפילו \u0003בחצר שבמבוי. והאי\u0004 \u0005[וזה]\u0006 הבית הפחות מארבע אמות \u0003לא גרע\u0004 \u0005[גרוע]\u0006 לענין זה \u0003מחצר שבמבוי.\u0004","עוד שנינו בברייתא: \u0003אין עושין אותו עיבור בין שתי עיירות.\u0004 ומסבירים: לומר ש\u0003אפילו כבורגנין\u0004 שהם צריפים המיועדים לשמירת התבואה שבשדות ומצרפים אותם לשיעורה של העיר, \u0003לא משוינן ליה\u0004 \u0005[אין אנו עושים אותו]\u0006 את הבית הזה שאין בו ארבע אמות, ואינו נחשב אפילו כמותם. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003בורגנין חזו למילתייהו\u0004 \u0005[ראויים לדבר שלהם],\u0006 שאף שאינם בניינים הבנויים היטב — מכל מקום ראויים הם לשמש לצורך שנבנו עבורו, \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003לא חזי למילתיה\u0004 \u0005[ראוי לדברו,\u0006 לענינו\u0005],\u0006 שהרי אינו ראוי לדור בו כלל.","עוד שנינו בברייתא כי בית שאין בו ארבע על ארבע אמות \u0003אין האחים והשותפין חולקין בו.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003ארבע אמות, הא אית ביה\u0004 \u0005[הרי\u0006 אם \u0005יש בו]\u0006 \u0003ארבע אמות\u0004 בדיוק — \u0003חולקין,\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין חולקין את החצר\u0004 לפי דרישתו של אחד היורשים או השותפים \u0003עד שיהא בה ארבע אמות לזה וארבע אמות לזה,\u0004 הרי שבפחות משמונה אמות אין חולקים!","\u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003אין בו דין חלוקה כחצר.\u0004 כיצד, ש\u0003אמר רב הונא: חצר לפי פתחיה מתחלקת.\u0004 כלומר: כאשר מחלקים חצר בין בעלי הבתים שבה, אינה מתחלקת לפי מספר בעלי הבתים שבחצר או לפי גודל הבתים, אלא לפי מספר הפתחים שבכל בית, ומי שלביתו פתחים רבים יותר — חלקו בחצר גדול יותר. \u0003ורב חסדא אמר: נותן לכל פתח ופתח ארבע אמות\u0004 לשימושו, \u0003והשאר חולקין אותו בשוה\u0004 לפי מספר השותפים.","ולשתי השיטות, \u0003דהני מילי\u0004 \u0005[שדברים אלה]\u0006 שיש לבעל הבית חלק בחצר, אמורים דווקא ב\u0003בית דלמהוי קאי\u0004 \u0005[שלהשאר הוא עומד]\u0006 ולכן יש לו צורך בחצר כדי להקל עליו את השימוש בבית ולכן \u0003יהבינא ליה\u0004 \u0005[נותנים אנו לו]\u0006 \u0003חצר\u0004 ארבע אמות, או חלק בחצר, כפי השיטות השונות. אולם \u0003האי דלמיסתר קאי\u0004 \u0005[זה\u0006 הבית הקטן \u0005שלסתירה הוא עומד]\u0006 ומכיון שכן אף אין לבעליו צורך בחצר ולכן \u0003לא יהבינן ליה\u0004 \u0005[נותנים לו]\u0006 \u0003חצר\u0004 כלל ונחשב כאילו לא היה.","לאחר בירור יסודות ההלכה, מגיעים אנו לדון בגוף דין המשנה שסוכה הגבוהה מעשרים אמה ממעט, וקובעים: \u0003היתה\u0004 הסוכה \u0003גבוהה מעשרים אמה ובא למעטה\u0004 מגובה זה על ידי \u0003כרים וכסתות\u0004 שפורס על הרצפה כדי לצמצם את החלל — \u0003לא הוי\u0004 \u0005[אין זה נחשב]\u0006 \u0003מיעוט\u0004 ואין הסוכה מתכשרת בכך, משום שחושש שיתקלקלו בכך ואינו מתכוין להשהותם כך זמן רב."],["\u0003ואף על גב דבטלינהו לכולהו\u0004 \u0005[ואף על פי שביטל את כולם]\u0006 וכוונתו שייחשבו בשבעת ימי החג כקרקע בלבד, אין זה נחשב כביטול, \u0003משום\u0004 ש\u0003בטלה דעתו\u0004 של האומר כן \u0003אצל\u0004 דעת \u0003כל אדם.\u0004 שאין דרך בני אדם לעשות כן, ואדם יוצא דופן כגון זה — אין מעשיו נחשבים.","ואם הניח על רצפת הסוכה \u0003תבן\u0004 לצורך צמצום החלל \u0003ובטלו\u0004 בפיו ואמר שלא ישתמש בו לצורך אחר \u0003הוי\u0004 \u0005[הרי זה\u0006 נחשב\u0005]\u0006 \u0003מיעוט,\u0004 שהתבן בטל לגבי קרקע הסוכה, והרי זה כאילו הוסיף שם אדמה, ונתמעט חלל הסוכה בה, \u0003וכל שכן\u0004 אם הניח שם \u0003עפר ובטלו.\u0004","הניח שם \u0003תבן ואין עתיד לפנותו\u0004 מן המקום אלא שלא ביטלו בפירוש, וכן \u0003עפר סתם\u0004 שלא ביטלו, הרי זו \u0003מחלוקת ר' יוסי ורבנן\u0004 \u0005[וחכמים]\u0006 אם יש במעשהו לבד משום ביטול. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בית\u0004 שיש בתוכו מת או כזית מן המת, שמן הדין אם הבית סתום לגמרי ואין חלל טפח בין הגג לבין הטומאה — אין גג הבית חוצץ והטומאה בוקעת ועולה, ואם יש חלל טפח בין הטומאה לגג — הגג חוצץ ואין הטומאה בוקעת ועולה. ובית כזה אם \u0003מילאהו תבן או צרורות\u0004 (אבנים ורגבי עפר) \u0003וביטלו — מבוטל\u0004 ונחשב הבית כסתום לגמרי והטומאה שבו בוקעת ועולה,","ומדיוק הלשון נלמד כי אם \u0003ביטלו — אין\u0004 \u0005[כן],\u0006 אבל אם \u0003לא ביטלו — לא. ותני עלה\u0004 \u0005[ושנינו עליה,\u0006 על משנה זו\u0005]\u0006 בתוספתא: \u0003ר' יוסי אומר:\u0004 היה בבית \u0003תבן ואין עתיד לפנותו — הרי הוא כעפר סתם, ובטל,\u0004 הניח \u0003עפר\u0004 ש\u0003עתיד לפנותו — הרי הוא כסתם תבן, ולא בטיל,\u0004 ואם כן נחלקו כבר חכמי המשנה בשאלה זו.","\u0003היתה\u0004 הסוכה \u0003גבוהה מעשרים אמה והוצין\u0004 (קצות הענפים) \u0003יורדין בתוך עשרים אמה, אם צלתם מרובה מחמתם,\u0004 שאותו חלק מן הסכך שהוא למטה מעשרים, הוא כשלעצמו מרובה וצפוף כדין סכך כשר — הרי הסוכה \u0003כשרה. ואם לאו\u0004 — הריהי \u0003פסולה.\u0004","מכאן ניסו לדון גם למקרה הפוך; \u0003היתה\u0004 הסוכה \u0003גבוהה\u0004 רק \u0003עשרה טפחים\u0004 (שהוא הגובה המינימלי להכשר סוכה), אולם היו \u0003הוצין יורדין לתוך עשרה, סבר אביי למימר\u0004 \u0005[לומר]\u0006 שגם בכגון זה תהיה אותה הלכה; \u0003אם חמתם מרובה מצלתם\u0004 ואינם ראויים לסכך — \u0003כשרה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 במקרה כזה אי אפשר לומר כן, כי אם היו הענפים יורדים לתוך עשרה טפחים \u0003הא\u0004 \u0005[זו]\u0006 \u0003דירה סרוחה\u0004 (שאינה ראויה למגורים) \u0003היא, ואין אדם דר\u0004 כלל \u0003בדירה סרוחה\u0004 והריהי פסולה אפילו כדירת ארעי.","\u0003היתה\u0004 הסוכה \u0003גבוהה מעשרים אמה ובנה בה איצטבא\u0004 מוגבהת \u0003כנגד\u0004 ה\u0003דופן האמצעי\u0004 (כלומר: הדופן המקבילה לאיצטבה. שכן, בדרך כלל היו בסוכה שלוש דפנות והצד הרביעי היה פרוץ ושימש כפתח), \u0003על פני כולה,\u0004 שהאיצטבא מגיעה מדופן לדופן ממש \u0003ויש בה\u0004 באיצטבא זו שטח של שבעה טפחים כ\u0003הכשר סוכה\u0004 — הרי זו סוכה \u0003כשרה.\u0004 שכיוון שחלק האיצטבא יש בו גם שלוש דפנות וגם גובה ראוי, הריהו נחשב כסוכה כשרה בפני עצמו, ואגב האיצטבא מוכשר גם החלק האחר.","\u0003ו\u0004אם בנה איצטבא זו \u0003מן הצד\u0004 ליד אחת הדפנות, \u0003אם יש משפת\u0004 ה\u0003איצטבא ולכותל\u0004 (לדופן המקבילה של הסוכה) \u0003ארבע אמות — פסולה,\u0004 שהרי לאיצטבא זו יש רק שתי דפנות בלבד. אולם אם יש \u0003פחות מארבע אמות\u0004 עד לדופן המקבילה — \u0003כשרה,\u0004 כי אנו מחשיבים את חלק הסכך עם הדופן הרחוקה כאילו היו שניהם יחד דופן אחת של סוכה שהתעקמה.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 מה לימד אותנו בהלכה זו, \u0003דאמרינן\u0004 \u0005[שאנו אומרים\u0006 שאנו מקבלים את ההלכה\u0005]\u0006 של \u0003דופן עקומה\u0004 בסוכה. אולם הרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 הלכה זו: \u0003בית שנפחת\u0004 (שנעשה חור בגגו) \u0003וסיכך על גביו, אם\u0004 קיים עדיין חלק הגג הסמוך לכתלים ו\u0003יש מן הכותל לסיכוך ארבע אמות\u0004 — הרי זו \u0003פסולה.\u0004 ונדייק \u0003הא\u0004 \u0005[הרי]\u0006 אם היה המרחק \u0003פחות מכאן — כשרה,\u0004 והטעם — שאנו אומרים: דופן עקומה, שחלק הגג והקיר יחד נחשבים כדופן. הרי שכבר שנינו הלכה זו ומה איפוא נתחדש כאן?","ומסבירים שבכל זאת יש חידוש בדברי הגמרא; \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 כי דווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 ששייך לומר כן, משום שקיר בית זה \u0003חזי\u0004 \u0005[ראוי]\u0006 \u0003לדופן,\u0004 שהרי גובהו הוא כראוי, פחות מעשרים אמה. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 באיצטבא שהיא \u0003לא חזיא\u0004 \u0005[ראויה]\u0006 \u0003לדופן,\u0004 שהרי היא גבוהה מהשיעור, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת מצרפים אותה להיות כדופן אחת עקומה.","\u0003היתה\u0004 הסוכה \u0003גבוהה מעשרים אמה ובנה איצטבא באמצעיתה, אם יש משפת\u0004 ה\u0003אצטבא ולדופן ארבע אמות לכל רוח ורוח — פסולה,\u0004 שהרי אין לאיצטבא זו כל דפנות. \u0003פחות מארבע אמות — כשרה.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך, \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 וקובעים הלכה זו של \u0003דופן עקומה, היינו הך\u0004 \u0005[הרי זה אותו דבר],\u0006 שהרי כבר השתמשנו בכלל זה!","ומשיבים: בכל זאת יש בכך חידוש, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003דופן עקומה מרוח אחת אמרינן\u0004 \u0005[מצד\u0006 מכיוון \u0005אחד אומרים אנו],\u0006 \u0003אבל\u0004 לומר דין זה לענין \u0003כל רוח ורוח\u0004 ולחשוב את כל הדפנות כתיקונן — \u0003לא, קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 שבכל זאת נחשבות כל הדפנות כמחיצות גמורות.","ועוד בדיני גובה סוכה. \u0003היתה\u0004 הסוכה \u0003פחותה\u0004 בגובהה \u0003מעשרה טפחים, וחקק\u0004 (חפר) \u0003בה\u0004 בקרקעיתה בור שיש בשטחו כדי הכשר סוכה, \u0003כדי להשלימה\u0004 לגובה \u0003עשרה, אם יש משפת חקק\u0004 (החפירה) \u0003ולכותל שלשה טפחים\u0004 — הרי זו \u0003פסולה,\u0004 שאין דופן החפירה מצטרף עם כותל הסוכה. ואף שקיים חלל בגובה עשרה טפחים, הרי אין לו דפנות בגובה הראוי כדי להיחשב כסוכה כשרה."],["\u0003פחות משלשה טפחים\u0004 — \u0003כשרה,\u0004 שבכך הם מצטרפים להיחשב ככותל אחד, מדין לבוד.","ושואלים: \u0003מאי שנא התם\u0004 \u0005[במה שונה שם]\u0006 בסוכה גבוהה ואיצטבא באמצעיתה, \u0003דאמרת\u0004 \u0005[שאמרת]\u0006 שהיא כשרה אם הכותל סמוך לאיצטבא \u0003פחות מארבע אמות, ומאי שנא הכא\u0004 \u0005[במה שונה כאן]\u0006 שאתה אומר \u0003פחות משלשה טפחים?\u0004","ומשיבים: \u0003התם דאיתיה\u0004 \u0005[שם שיש]\u0006 כבר \u0003לדופן,\u0004 שהרי יש לסוכה זו דופן של ממש אלא שהיא מרוחקת, על כן \u0003בפחו‍ת מארבע אמות סגיא\u0004 \u0005[די],\u0006 אולם \u0003הכא\u0004 \u0005[כאן]\u0006 בסוכה שגובהה פחות מעשרה טפחים אין דופנה נחשב כדופן כלל, וצריך קודם \u0003לשוויי לדופן\u0004 \u0005[לעשותו שייחשב דופן]\u0006 על ידי תוספת החקיקה, ולכן אם היה המרחק \u0003פחות משלשה טפחים,\u0004 שמרחק זה נחשב כצמוד לכל ענין — \u0003אין\u0004 \u0005[כן]\u0006 נחשב הדבר לדופן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא,\u0004 אינו נחשב לדופן.","הלכה נוספת בסוכה: \u0003היתה\u0004 הסוכה \u0003גבוהה מעשרים אמה, ובנה בה\u0004 באמצעה במרחק רב מן הדפנות \u0003עמוד שהוא גבוה עשרה טפחים,\u0004 ומעל לעמוד אין עוד עשרים אמה עד לסכך \u0003ויש בו\u0004 באורכו וברחבו שבעה טפחים ומשהו כדי \u0003הכשר סוכה\u0004 — \u0003סבר אביי למימר\u0004 \u0005[לומר]\u0006 שזו היא סוכה כשרה, כי \u0003גוד אסיק מחיצתא\u0004 \u0005[משוך והעלה את המחיצות]\u0006 של העמוד שהרי גובהו יוצר סביבו מעין מחיצות ואם \"מושכים\" אותן עשרה טפחים כלפי מעלה, אף על פי שהסכך גבוה בהרבה מראש העמוד, מאחר ואינו גבוה בעשרים אמה, הרי זו סוכה כשרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לאביי: אינו כן, כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 להכשר סוכה שיהיו \u0003מחיצות הניכרות, וליכא\u0004 \u0005[ו\u0006הרי \u0005אין כאן],\u0006 שהרי מחיצות העמוד אינן נראות בעצמן כמחיצות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נעץ ארבעה קונדיסין\u0004 (כלונסאות, קורות) \u0003וסיכך על גבן\u0004 ולא עשה כל דפנות, \u0003ר' יעקב מכשיר וחכמים פוסלין.\u0004","\u0003אמר רב הונא: מחלוקת\u0004 זו בין חכמים ור' יעקב היא כשהיו ארבעה כלונסאות אלה מכוונים \u0003על שפת הגג\u0004 בדיוק מעל לקירות הבית, ש\u0003ר' יעקב סבר, אמרינן\u0004 \u0005[אומרים אנו]\u0006 כלל זה של \u0003גוד אסיק מחיצתא\u0004 \u0005[משוך והעלה את המחיצות],\u0006 שהרי קירות הבית מחיצות הן, ונחשוב כאילו היו המחיצות נמשכות ועולות עד למעלה, ונעשות כדפנות לסוכה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 כלל זה של \u0003גוד אסיק מחיצתא\u0004 \u0005[משוך והעלה את המחיצות],\u0006 \u0003אבל\u0004 אם היתה סוכה זו \u0003באמצע הגג\u0004 שאין מחיצות הבית מועילות לכך — \u0003דברי הכל פסולה. ורב נחמן אמר: באמצע הגג מחלוקת,\u0004 שלדברי ר' יעקב, הקונדיסין עצמם, אם יש ברוחבם טפח, הריהם משמשים כמחיצות להכשיר סוכה זו. ואילו לשיטת חכמים אין הסוכה כשירה אלא אם כן יש לה שני דפנות גמורים ודופן שלישי אפילו חלקי.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה זו: האם יש להבין את דברי רב נחמן כי \u0003באמצע הגג\u0004 בלבד \u0003מחלוקת אבל על שפת הגג, דברי הכל כשרה, או דלמא\u0004 \u0005[שמא]\u0006 התכוון לומר כי \u0003בין בזו ובין בזו מחלוקת?\u0004 לשאלה זו לא נמצאה תשובה, והיא נשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא אחרת: \u0003נעץ ארבעה קונדסין בארץ וסיכך על גבן, ר' יעקב מכשיר וחכמים פוסלין.\u0004","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003ארץ\u0004 ש\u0003כאמצע הגג דמי\u0004 \u0005[היא נחשבת],\u0006 שהרי אין בה מחיצות נמשכות, ובכל זאת \u0003קא מכשיר\u0004 \u0005[מכשיר]\u0006 \u0003ר' יעקב!\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דעת \u0003רב הונא\u0004 האומר כי באמצע הגג לדעת הכל פסולה. ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ונדחו דבריו.","\u0003ועוד\u0004 יש להקשות על דעתו: הרי מברייתא זו רואים לכאורה כי \u0003באמצע\u0004 הגג \u0003הוא דפליגי\u0004 \u0005[שנחלקו],\u0006 \u0003אבל על שפת הגג\u0004 לכאורה \u0003לדברי הכל כשרה!\u0004 אם כן \u0003לימא תיהוי תיובתיה\u0004 \u0005[נאמר שתהא זו קושיה חמורה]\u0006 על שיטת \u0003רב הונא בתרתי\u0004 \u0005[בשתים],\u0006 גם במה שאמר כי באמצע הגג לדברי הכל פסולה ואילו בברייתא נאמר כי בכך נחלקו, וכן במה שאמר כי נחלקו בשפת הגג ואילו בברייתא נאמר כי בכך לדברי הכל כשרה.","ודוחים, \u0003אמר לך רב הונא\u0004 \u0005[יכול היה רב הונא לומר לך];\u0006 משם אין ראייה, כי אפשר לומר: \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003באמצע הגג והוא הדין\u0004 שנחלקו גם כן אם היתה הסוכה \u0003על שפת הגג. והאי דקמיפלגי\u0004 \u0005[וזה שנחלקו]\u0006 במפורש \u0003באמצע הגג,\u0004 היה זה \u0003להודיעך כחו\u0004 של \u0003ר' יעקב\u0004 עד כמה הוא מחזיק בשיטתו ש\u0003אפילו באמצע הגג נמי\u0004 \u0005[גם כן]\u0006 הוא \u0003מכשיר.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003נעץ ארבעה קונדסין בארץ וסיכך על גבן, ר' יעקב אומר: רואין כל שאילו יחקקו,\u0004 כלומר: יעשו חריץ באותם קונדיסין \u0003ויחלקו\u0004 לשני חלקים, \u0003ויש בהן טפח לכאן וטפח לכאן\u0004 — הרי הם \u0003נדונין משום דיומד\u0004 \u0005[עמוד כפול]\u0006 ובהלכות מסויימות מחשיבים עמוד כפול המצוי בפינה כאילו היה שתי מחיצות שלמות (ראה עירובין יז, ב), \u0003ואם לאו\u0004 \u0005[לא]\u0006 שלאחר חלוקת הקונדיסין הם צרים מדי — \u0003אין נידונין משום דיומד. שהיה ר' יעקב אומר: דיומדי סוכה\u0004 שיעורם כדי שייחשבו כמחיצות, הריהו \u0003טפח, וחכמים אומרים:\u0004 אין הסוכה כשירה אלא \u0003עד שיהו שתים\u0004 ממחיצותיה שלימות \u0003כהלכתן\u0004 וסותמות את כל אותו צד בסוכה, ודופן \u0003שלישית\u0004 הלכה למשה מסיני היא ש\u0003אפילו\u0004 היה רוחבה \u0003טפח\u0004 אחד — דיו.","שנינו במשנה: סוכה \u0003שאינה גבוהה עשרה טפחים\u0004 פסולה. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה?","\u0003אתמר\u0004 \u0005[נאמר]\u0006 כי \u0003רב ור' חנינא ור' יוחנן ורב חביבא מתנו\u0004 \u0005[היו שונים]\u0006 כפי שיפורט להלן.","ובדרך אגב מעירים בענין זה: \u0003בכולה\u0004 \u0005[בכל]\u0006 \u0003סדר מועד,\u0004 כאשר מוצאים אנו \u0003כל כי האי זוגא\u0004 \u0005[זוג זה\u0006 של חכמים\u0005]\u0006 היו שיטות אמוראים, לפיהן \u0003חלופי\u0004 \u0005[מחליפים\u0006 ומוציאים\u0005]\u0006 את \u0003ר' יוחנן ומעיילי\u0004 \u0005[ומכניסים]\u0006 את \u0003ר' יונתן,\u0004 שהוא שהיה הרביעי בחבורה זו.","וכך למדו: \u0003ארון\u0004 הברית עצמו, היה גובהו \u0003תשעה\u0004 טפחים, שכן מפורש בתורה שהיה אמה וחצי, ובאמה שבה נמדדים כלי המקדש יש שישה טפחים, הרי תשעה טפחים. \u0003ו\u0004ה\u0003כפורת\u0004 המכסה את הארון \u0003טפח\u0004 עוביה, \u0003הרי כאן עשרה\u0004 טפחים, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ונועדתי לך שם ודברתי אתך מעל הכפרת\"\u0004 (שמות כה, כב),"],["\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005];\u0006 \u0003ר' יוסי אומר: מעולם לא ירדה שכינה למטה\u0004 ממש, \u0003ולא עלו משה ואליהו למרום\u0004 ממש, \u0003שנאמר: \"השמים שמים לה' והארץ נתן לבני אדם\"\u0004 (תהלים קטו, טז), ששני אלה הם שני תחומים מוגדרים ומובדלים. הרי שהחל מגובה עשרה טפחים הרי זו רשות לעצמה, ולכן אף בסוכה, כל שאינה גבוהה עשרה טפחים, אינה נחשבת כרשות לעצמה ואינה כשרה.","ושואלים: \u0003ו\u0004כי \u0003לא ירדה שכינה למטה\u0004 מעשרה טפחים? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וירד ה' על הר סיני\"\u0004 (שמות יט, כ)! ומשיבים: אמנם ה' ירד ממרומיו, אבל היה זה \u0003למעלה מעשרה טפחים\u0004 מעל לארץ, ומגובה עשרה טפחים ומעלה הרי זו רשות בפני עצמה, ואכן למטה ממש לא ירדה שכינה מעולם. ועוד מקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ועמדו רגליו ביום ההוא על הר הזיתים\"\u0004 (זכריה יד, ד)! ומשיבים: אף כאן היה זה \u0003למעלה מעשרה טפחים.\u0004","ושואלים: \u0003ו\u0004כי \u0003לא עלו משה ואליהו למרום? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ומשה עלה אל האלהים\"\u0004 (שמות יט, ג)! ומשיבים: בכל זאת היה זה \u0003למטה מעשרה\u0004 טפחים סמוך לארץ. ומקשים: \u0003והכתיב:\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויעל אליהו בסערה השמים\"\u0004 (מלכים ב' ב, יא)! ומשיבים: אף כאן \u0003למטה מעשרה.\u0004 ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"מאחז פני כסא פרשז עליו עננו\"\u0004 (איוב כו, ט) \u0003ואמר ר' תנחום: מלמד שפירש שדי מזיו שכינתו ועננו עליו,\u0004 על משה, הרי שהיה משה בענן עם הקדוש ברוך הוא! ומשיבים: אף כאן \u0003למטה מעשרה.\u0004","ומקשים: \u0003מכל מקום \"מאחז פני כסא\" כתיב\u0004 \u0005[נאמר],\u0006 לומר שמשה אחז בכסא הכבוד! ודוחים: \u0003אישתרבובי אישתרבב ליה\u0004 \u0005[השתרבב לו]\u0006 ה\u0003כסא\u0004 וירד \u0003עד עשרה\u0004 טפחים. \u0003ונקט ביה\u0004 \u0005[והחזיק בו]\u0006 משה מלמטה, והוא עצמו לא עלה למעלה מעשרה. וכיון שהשכינה מדברת עם משה מעל הכפורת הרי מכאן מובן כי הכפורת היא למעלה מעשרה טפחים. ומכאן אנו למדים שעשרה טפחים הם רשות מובדלת לעצמה.","על ראיה זו תוהים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ארון תשעה\u0004 טפחים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשו ארון עצי שטים אמתים וחצי ארכו ואמה וחצי רחבו ואמה וחצי קמתו\"\u0004 (שמות כה, י), ומספר הטפחים באמה וחצי הוא תשעה. \u0003אלא\u0004 שעוביה של \u0003כפורת טפח, מנלן\u0004 \u0005[מנין לנו]?\u0006 והלא לא נתפרש הדבר בכתוב! \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חנינא: כל הכלים שעשה משה\u0004 במשכן \u0003נתנה בהן\u0004 ה\u0003תורה מדת ארכן ומדת רחבן ומדת קומתן,\u0004 ואילו \u0003בכפורת, מדת ארכה ומדת רחבה — נתנה\u0004 התורה, ואילו \u0003מדת קומתה לא נתנה.\u0004","ומשיבים: \u0003צא ולמד מפחות שבכלים,\u0004 מן השיעור הקטן ביותר שנאמר באחד מכלי המשכן, \u0003שנאמר\u0004 בשולחן הפנים: \u0003\"ועשית לו מסגרת טפח סביב\"\u0004 (שמות כה, כה), \u0003מה להלן\u0004 במסגרת השלחן, שיעורה \u0003טפח — אף כאן\u0004 שיעור עובי הכפורת \u0003טפח.\u0004 ומקשים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 מן ה\u0003כלים גופייהו\u0004 \u0005[עצמם],\u0006 שהקטן בשיעוריהם הוא אמה! ומשיבים: \u0003תפשת מרובה — לא תפשת, תפשת מועט — תפשת.\u0004 כלומר, אם רוצים אנו ללמוד מידת דבר מה, מוטב ללמוד מן המועט שבשיעורים, שהרי בכלל השיעורים הגדולים נכלל אף שיעור קטן זה, ובעוד האחרים ספק — הרי זה ודאי.","ומקשים: אם כן \u0003ונילף\u0004 \u0005[ונלמד]\u0006 מן ה\u0003ציץ\u0004 ששיעורו קטן עוד מזה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 : \u0003ציץ\u0004 היה \u0003דומה כמין טס\u0004 (חתיכה שטוחה) \u0003של זהב, ורחב שתי אצבעות ו\u0004היה \u0003מוקף\u0004 (מגיע) \u0003מאזן לאזן, וכתוב עליו שתי שיטין\u0004 (שתי שורות) \"\u0003יו\"ד ה\"א\"\u0004 (שם ה') \u0003מלמעלה ו\"קדש למ\"ד\" מלמטה,\u0004 שהיה כתוב בו \"קודש לה'\" אלא שהשם היה גבוה יותר, והמילים האחרות נמוכות יותר. \u0003ואמר ר' אליעזר בר' יוסי: אני ראיתיו\u0004 את הציץ באוצר המלך \u0003ברומי,\u0004 שנלקח לשם יחד עם שאר כלי המקדש, \u0003וכתוב עליו \"קדש לה'\" בשיטה\u0004 \u0005[בשורה]\u0006 \u0003אחת,\u0004 ומדוע לא נלמד מכלי זה, שהיה רחב שתי אצבעות בלבד!","ומשיבים: \u0003דנין\u0004 \u0005[למדים]\u0006 \u0003כלי מכלי ואין דנין כלי מתכשיט,\u0004 שהרי הציץ אינו מכלי המשכן אלא מתכשיטי הכהן הגדול.","ומקשים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003מזר\u0004 שהיה על גבי כמה מכלי המשכן. ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003זר\u0004 זה שלא נתפרש שיעורו בתורה גובהו \u0003משהו!\u0004 ומשיבים: \u0003דנין כלי מכלי, ואין דנין כלי מהכשר כלי\u0004 מדבר שאינו אלא בבחינת קישוט לכלי. ומקשים \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאין אתה לומד מדבר שהוא הכשר כלי, \u0003מסגרת\u0004 השולחן \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003הכשר כלי הוא,\u0004 ולא חלק מן הכלי! ומשיבים \u0003מסגרתו\u0004 של השולחן \u0003למטה היתה\u0004 בין רגלי השולחן, וטבלת השולחן היתה מונחת עליה ואם כן היתה המסגרת חלק ממבנה השולחן, ולא שימשה כקישוט בלבד.","ומקשים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003מסגרתו\u0004 של השולחן \u0003למטה\u0004 בין רגליו \u0003היתה, אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003מסגרתו למעלה היתה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלא \u0003האי\u0004 \u0005[זה]\u0006 \u0003הכשר כלי\u0004 הוא!","\u0003אלא\u0004 עלינו לחזור בנו מטעמים אלה ולהביא ראיה אחרת לעובי הכפורת: \u0003דנין דבר שנתנה בו\u0004 ה\u0003תורה מדה\u0004 ככפורת, שנתנה התורה מידת ארכה ורחבה במפורש, \u0003מדבר שנתנה בו תורה מדה\u0004 המסגרת שאף לה נתנה התורה מידה מפורשת, \u0003ואל יוכיחו ציץ וזר שלא נתנה בהן תורה מדה כלל\u0004 ורק החכמים פירשו את שיעורם, וראוי ללמוד דווקא מדבר שנתפרש בתורה עצמה.","\u0003רב הונא אמר\u0004 ראיה אחרת לעוביה של הכפורת, \u0003מהכא\u0004 \u0005[מכאן],\u0006 נאמר: \u0003\"על פני הכפרת קדמה\"\u0004 (ויקרא טז, יד) \u0003ואין פנים\u0004 של אדם \u0003פחות מטפח,\u0004 שהרי מן הכתוב משמע שעובי (\"קומת\") הכפורת יכול להקרא \"פנים\", ושיעור פנים של אדם הוא לפחות טפח.","ומקשים: מדוע נאמר שפנים הם דווקא כפני אדם, \u0003ואימא\u0004 \u0005[ונאמר]\u0006 שהוא \u0003כאפי\u0004 \u0005[כפני]\u0006"],["העוף הענקי \u0003דבר יוכני\u0004 הגדולים הרבה מטפח! ודוחים: \u0003תפשת מרובה לא תפשת,\u0004 אם תופש אתה שיעור מרובה אין באפשרותך להוכיח שאכן כך הוא, \u0003תפשת מועט תפשת.\u0004 ומקשים: אם כן, \u0003ואימא כאפי דציפרתא דזוטר טובא\u0004 \u0005[אמור\u0006 שהוא \u0005כפני ציפור\u0006 שהם \u0005קטנים ביותר]!\u0006 \u0003אמר רב אחא בר יעקב: רב הונא\u0004 יודע את הדבר לא מתוך השוואה לפניהם של יצורים שונים, אלא מגזירה שווה של המילים \u0003\"פני\" \"פני\" גמר\u0004 \u0005[למד].\u0006 \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"אל פני הכפרת\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"מאת פני יצחק אביו\"\u0004 (בראשית כז, ל), ולמד שפני הכפורת הם כפני אדם, טפח.","ומקשים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 גזירה שוה \u0003מפנים של מעלה, דכתיב\u0004 \u0005[שנאמר]\u0006: כי על כן ראיתי פניך \u0003כראת פני אלהים ותרצני\"\u0004 \u0005(בראשית לג, י)\u0006, הרי שאף לגבי שכינה נאמר לשון \"פני\"! ומשיבים: אף כאן, \u0003תפשת מרובה לא תפשת, תפשת מועט תפשת.\u0004","מקשים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 מפני ה\u0003כרוב\u0004 שהיה במקדש, \u0003דכתיב\u0004 \u0005[\u0006שהרי גם שם \u0005נאמר]:\u0006 \u0003\"אל הכפרת יהיו פני הכרבים\"\u0004 (שמות כה, כ) ופנים אלה קטנים מטפח!","\u0003אמר רב אחא בר יעקב: גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]\u0006 כי \u0003אין פני\u0004 ה\u0003כרובים פחותין מטפח,\u0004 ואכן \u0003ורב הונא נמי מהכא גמיר\u0004 \u0005[גם כן מכאן למד],\u0006 שנאמר: \"פני הכפורת\" ונאמר: \"פני הכרובים\" ושיעור זה כזה.","דרך אגב שואלים \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003כרוב,\u0004 מהי צורת פניו? \u0003אמר ר' אבהו: כרביא\u0004 \u0005[כתינוק],\u0006 \u0003שכן בבבל קורין לינוקא\u0004 \u0005[לתינוק]\u0006 \u0003רביא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 לפי הסבר זה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במקרא על החיות במרכבה העליונה: \u0003\"פני האחד פני הכרוב ופני השני פני אדם\"\u0004 (יחזקאל י, יד), \u0003היינו\u0004 \u0005[הוא]\u0006 \u0003כרוב היינו\u0004 \u0005[הוא]\u0006 \u0003אדם,\u0004 שהרי פני כרוב אף הם פני אדם! ומשיבים: \u0003אפי רברבי ואפי זוטרא\u0004 \u0005[פנים גדולות ופנים קטנות],\u0006 כלומר: אכן לשניהם אותה דמות, אלא פני אדם הם של אדם גדול, ופני כרוב, דמות ילדים להם. הסברנו איפוא את מקור הקביעה שהארון והכפורת יחד שיעורם עשרה טפחים.","אבל לענין ההשוואה לדין סוכה שואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 למד אתה ש\u0003חללה\u0004 של הסוכה הוא \u0003עשרה בר\u0004 \u0005[חוץ]\u0006 \u0003מסככה? אימא\u0004 \u0005[אמור]\u0006 ששיעור זה הוא \u0003בהדי\u0004 \u0005[עם]\u0006 \u0003סככה,\u0004 כשם שהארון נמדד מקצהו התחתון עד קצה הכפורת, אף בסוכה יהא שיעורה זה מהקרקע עד קצה העליון של הסכך!","\u0003אלא\u0004 עלינו לחזור בנו מהוכחה זו ולומר כי \u0003מבית עולמים\u0004 (בית המקדש) \u0003גמר\u0004 \u0005[למד],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"והבית אשר בנה המלך שלמה לה' ששים אמה ארכו ועשרים רחבו ושלשים אמה קומתו\"\u0004 (מלכים א' ו, ב). \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"קומת הכרוב האחד עשר באמה וכן הכרוב השני\"\u0004 (מלכים א' ו, כו) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003מה מצינו בבית עולמים\u0004 ש\u0003כרובים בשליש הבית הן עומדין,\u0004 שגובה הכרוב (עשר אמות) הוא שליש מגובה קודש הקדשים (שלושים אמה). אף \u0003במשכן נמי\u0004 \u0005[גם כן]\u0006 \u0003כרובים בשליש\u0004 גבהו של \u0003הבית הן עומדין.\u0004","ומעתה נחשב: \u0003משכן כמה הוי\u0004 \u0005[היה]\u0006 גבהו — \u0003עשר אמות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עשר אמות ארך הקרש\"\u0004 (שמות כו, טז), ועשר אמות אלו \u0003כמה הוי להו\u0004 \u0005[היה להם]\u0006 במידת טפחים — \u0003שיתין פושכי\u0004 \u0005[שישים טפחים],\u0006 \u0003תלתיה\u0004 \u0005[שלישו]\u0006 \u0003כמה הוי\u0004 \u0005[הוא]\u0006 — \u0003עשרים פושכי\u0004 \u0005[טפחים],\u0006 \u0003דל\u0004 \u0005[הוצא]\u0006 מכאן \u0003עשרה\u0004 טפחים של גובה \u0003ארון וכפורת,\u0004 שהכרובים עומדים מעליהם, \u0003פשו להו\u0004 \u0005[נשארו להם]\u0006 אם כן \u0003עשרה\u0004 טפחים לגובה הכרובים עצמם, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והיו הכרבים פרשי כנפים למעלה סככים בכנפיהם על הכפרת\"\u0004 (שמות כה, כ) \u0003קרייה רחמנא\u0004 \u0005[קראה התורה]\u0006 לדבר \u0003\"סככה\"\u0004 דווקא כשהוא \u0003למעלה מעשרה\u0004 טפחים, ואם כן, יפה למדנו מכאן שסכך הוא למעלה מעשרה טפחים.","ומקשים: \u0003ממאי דגדפינהו עילוי רישייהו קיימי\u0004 \u0005[וממה,\u0006 מהיכן למד אתה \u0005שכנפיהם מעל ראשיהם היו],\u0006 שמכאן נלמד שלשון סכך הוא למעלה מעשרה, \u0003דלמא להדי רישייהו קיימי\u0004 \u0005[שמא בשוה עם ראשיהן\u0006 היו הכנפיים \u0005עומדות]\u0006 ונמצא סכך בפחות מחלל עשרה! \u0003אמר רב אחא בר יעקב: \"למעלה\" כתיב\u0004 \u0005[נאמר],\u0006 ו\"פורשי כנפיים למעלה\" פירושו: למעלה מראשיהם. ומקשים מצד אחר: אם כן, \u0003ואימא דמידלי טובא\u0004 \u0005[ואמור\u0006 שהיו הכנפיים \u0005מורמות הרבה]\u0006 ומי יודע עד לאיזה גובה הגיעו? ומשיבים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"למעלה למעלה\"?\u0004 הלא נאמר רק \"למעלה\" שמשמעו גבוה במקצת מראשיהם. יש בידינו איפוא הוכחה מלשון הכתובים לענין גובה הסכך.","אבל שואלים מצד אחר: \u0003הניחא\u0004 \u0005[\u0006כל \u0005זה נוח]\u0006 לפי שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 כי \u0003כל\u0004 מידות \u0003האמות\u0004 הנזכרות במקדש והמשכן \u0003היו בינוניות,\u0004 כלומר: בכל אחת מהן שישה טפחים, \u0003אלא לר' יהודה\u0004 ש\u0003אמר\u0004 כי \u0003אמה של בנין,\u0004 כלומר: זו שבה נמדד הבנין עצמו, אמה בינונית היתה, של \u0003ששה טפחים,\u0004 אבל אמה \u0003של כלים,\u0004 כלומר: זו שמדדו בה את הכלים, בת \u0003חמישה\u0004 טפחים בלבד היתה, אם כן לשיטתו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","כי לחישוב זה \u0003ארון וכפורת כמה הוי להו\u0004 \u0005[כמה הם]\u0006 \u0003תמניא ופלגא\u0004 \u0005[שמונה וחצי]\u0006 טפחים, שהרי אמה ומחצה הכתובה בתורה, לפי חשבון חמישה טפחים לאמה, הריהו שבעה טפחים ומחצה, ועוד טפח כפורת הרי שמונה ומחצה, ואם היו הכרובים מגיעים עד לשליש הבית, שהוא עשרים טפחים אם כן \u0003פשו להו חד סרי ופלגא\u0004 \u0005[נשארו להם\u0006 איפוא \u0005אחד עשר וחצי\u0006 טפחים\u0005]\u0006 שהיו כנפי הכרובים מוגבהים מעל לכפורת, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003סוכה עד דהויא חד סרי ופלגא\u0004 \u0005[שתהיה אחד עשר וחצי\u0006 טפחים\u0005]\u0006 לא תהיה כשרה, ושיטה כגון זו לא שמענו כלל!","\u0003אלא, ל\u0004שיטת \u0003ר' יהודה הלכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני \u0005למדים אנו אותה],\u0006 מה הוא שיעורה של סוכה. וכיוצא בזה \u0003אמר ר' חייא בר אשי אמר רב: שיעורין\u0004 של מידות שונות בהלכה (כגון: כזית, כביצה וככותבת), דיני \u0003חציצין,\u0004 שהם דברים המהווים חציצה לגבי טבילה, \u0003ומחיצין,\u0004 מידתן וטיבן של מחיצות בהלכה, כל אלה \u0003הלכה למשה מסיני\u0004 הם. שלא נתפרשו הדברים בתורה, אלא לפי מסורת בתורה שבעל פה יודעים אנו אותם.","על עיקרה של שמועה זו מקשים: \u0003שיעורין\u0004 הלא \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הם]!\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ארץ חטה ושערה וגפן ותאנה ורמון ארץ זית שמן ודבש\"\u0004 (דברים ח, ח) \u0003ואמר רב חנין: כל הפסוק הזה\u0004 לענין \u0003שיעורין\u0004 של תורה \u0003נאמר,\u0004 כיצד?","\u0003חטה\u0004 היא בסיס לשיעור הלכה לענין \u0003בית המנוגע\u0004 בנגע צרעת, \u0003דתנן\u0004 \u0005[\u0006שכן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנכנס לבית המנוגע\u0004 בצרעת \u0003ו\u0004היו \u0003כליו\u0004 (בגדיו) מונחים ומקופלים \u0003על כתפיו\u0004 שלא בדרך לבוש, \u0003וסנדליו וטבעותיו\u0004 מונחים בתוך \u0003ידו\u0004 ולא כדרך מלבוש — \u0003הוא והן טמאין מיד.\u0004"],["\u0003היה לבוש כליו\u0004 (בגדיו) \u0003וסנדליו ברגליו וטבעותיו באצבעותיו, הוא\u0004 עצמו \u0003טמא מיד, והן\u0004, הבגדים שעליו, \u0003טהורים עד שישהה\u0004 בבית \u0003בכדי\u0004 שיעור הזמן של \u0003אכילת פרס\u0004 (חצי ככר לחם). וחצי ככר זה של \u0003פת חטין\u0004 הוא \u0003ולא\u0004 של \u0003פת שעורין,\u0004 שזמן אכילת פת חיטים מועטה מזו של פת שעורים. וזמן אכילתה משערים כשאוכל דווקא כשהוא \u0003מיסב\u0004 ועסוק באכילה בלבד ולא בדבר אחר, \u0003ואוכל בליפתן.\u0004 הרי שחיטה (אכילת פת חטים) היא שיעור בהלכה.","\u0003שעורה\u0004 היא עצמה שיעור בהלכה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עצם\u0004 של מת שגודלה \u0003כשעורה\u0004 — \u0003מטמא במגע ובמשא\u0004 (אם נושאים אותה, אף בלא לנגוע בה), אולם \u0003אינו מטמא באהל\u0004 שאם היתה עצם בשיעור שעורה בלבד בבית, הנכנס לבית איננו נטמא.","\u0003גפן\u0004 אף היא שיעור בהלכה — \u0003כדי רביעית יין לנזיר,\u0004 שנאסר עליו לשתות יין ולאכול ענבים, ושיעור האיסור הוא דווקא בכדי רביעית של יין.","\u0003תאנה\u0004 אף היא שיעור בהלכה, שהרי \u0003כגרוגרת\u0004 (תאנה מיובשת) הוא השיעור לגבי רוב מיני המאכל \u0003להוצאת שבת\u0004 שאם הוציא מרשות היחיד לרשות הרבים בשבת ולהיפך אוכל שגודלו כגרוגרת — חייב.","\u0003רמון\u0004 הוא שיעור, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל כלי בעלי הבתים\u0004 שנטמאו ולאחר מכן ניקבו — בטלו מתורת כלי, ואינם טמאים עוד, ו\u0003שיעורן\u0004 כדי להיטהר — אם היה הנקב בגודל של \u0003רמונים,\u0004 שכן כלי הנקוב בשיעור כזה שוב איננו משמש למלאכה כלשהי ובטל, ומאחר שבטל — הריהו טהור.","והזית אף הוא משמש כשיעור בהלכה, שכן נאמר: \u0003\"ארץ זית שמן\",\u0004 ודרשו חכמים: \u0003ארץ שכל שיעוריה כזיתים.\u0004 על לשון זו תוהים: \u0003\"כל שיעוריה\" סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?!\u0006 \u0003הא איכא הני דאמרינן\u0004 \u0005[הרי יש\u0006 את \u0005אלה שאמרנו\u0006 לפני כן\u0005]\u0006 שאינם כזית! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003שרוב שיעוריה כזיתים,\u0004 כי השיעור לרוב איסורי אכילה שבתורה (כגון: נבילה, חלב, דם, פיגול, נותר, טמא וגיד הנשה) הוא כזית.","\u0003\"דבש\"\u0004 שהוא דבש תמרים, אף הוא משמש כשיעור. שיודעים אנו כי \u0003ככותבת הגסה\u0004 (תמרה גדולה) הוא השיעור שחייבים בו על אכילה \u0003ביום הכפורים.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 ששיעורי ההלכה \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הם]\u0006 ואינם הלכה למשה מסיני! ומשיבים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור כן]?\u0006 \u0003שיעורין מי כתיבי\u0004 \u0005[האם כתובים\u0006 הם\u0005]\u0006 בפסוק זה? שאמנם נזכרים הפירות הללו בכתוב, אך לא כשיעורים, ולא נאמר בהם במפורש לאיזו הלכה הם משמשים כשיעורים. \u0003אלא\u0004 ודאי יש לומר כי \u0003הלכתא נינהו\u0004 \u0005[הלכות הם\u0006 למשה מסיני\u0005]\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והפסוק אסמכתא בלבד]\u0006 \u0003הוא,\u0004 לרמז ולזכרון.","ומוסיפים להקשות על אותה שמועה: והלא \u0003חציצין\u0004 (חציצות לטבילה) \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הם]!\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הלא \u0005נאמר]:\u0006 \u0003\"ורחץ את בשרו במים\u0004 וטהר\u0003\"\u0004 (ויקרא יד, ט), ומלשון זו הבינו חכמים שהכוונה \u0003שלא יהא דבר חוצץ בינו לבין המים\u0004 ואם היתה חציצה, אין הטבילה עולה לו. הרי שדיני חציצה מן התורה הם נלמדים!","ומשיבים: \u0003כי אתאי הלכתא\u0004 \u0005[כאשר באה ההלכה]\u0006 לא היה זה לענין חציצה שעל בשרו, אלא ללמד שלא תהא חציצה גם ב\u0003שערו\u0004, וכדברי \u0003רבה בר בר חנה, שאמר רבה בר בר חנא: נימא\u0004 \u0005[שערה]\u0006 \u0003אחת,\u0004 אם היתה \u0003קשורה\u0004 בעצמה — \u0003חוצצת,\u0004 שהקשר מהודק ואין המים נכנסים שם, \u0003שלש\u0004 שערות קשורות — \u0003אינן חוצצות\u0004 כי כמה שערות יחד אינן יכולות ליצור קשר מהודק עד כדי שלא יכנסו בו מים, \u0003שתים\u0004 קשורות — \u0003איני יודע\u0004 אם חוצצות. והוצרכה הלכה זו ללמדנו, שיש חציצה בשיער.","ומקשים: \u0003שערו נמי דאורייתא נינהו\u0004 \u0005[מן התורה הם]\u0006 החציצות הללו, \u0003דכתיב\u0004 \u0005[ש\u0006הלא \u0005נאמר]:\u0006 \u0003\"ורחץ את בשרו במים\"\u0004 ולמדים מן המלה \"את\" שכוונתה תמיד להוסיף ולהרבות, ולענין זה הריהי מרבה \u0003את הטפל לבשרו, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003שערו,\u0004 שגם זה צריך להיות כבשרו, כלומר: בלא חציצה!","ומשיבים: \u0003כי אתאי הלכתא\u0004 \u0005[כאשר באה ההלכה\u0006 למשה מסיני\u0005],\u0006 הריהי באה ללמדנו את הדינים שקבע \u0003ר' יצחק.\u0004 ש\u0003אמר ר' יצחק:\u0004"],["\u0003דבר תורה,\u0004 מעיקר הדין שקיבלנוהו מהלכה למשה מסיני, אם היה \u0003רובו\u0004 של השיער מלוכלך, וזה באופן שהאיש \u0003מקפיד עליו\u0004 להסירו — הרי זה \u0003חוצץ.\u0004 אבל אם \u0003אינו מקפיד עליו\u0004 כגון שרגיל לסוג זה של לכלוך, ואינו נוהג להסירו — \u0003אינו חוצץ. וגזרו\u0004 חכמים שתחשב חציצה \u0003על רובו\u0004 של השיער המלוכלך אפילו כ\u0003שאינו מקפיד\u0004 עליו, גזירה \u0003משום רובו המקפיד,\u0004 וכן גזרו אם היה \u0003מיעוטו\u0004 של השיער מלוכלך באופן שהוא \u0003מקפיד\u0004 להסיר ממנו את הלכלוך, \u0003משום רובו\u0004 המלוכלך \u0003המקפיד\u0004 עליו.","ושואלים: אם כן, \u0003וליגזר נמי\u0004 \u0005[שיגזרו גם כן]\u0006 \u0003על מיעוטו שאינו מקפיד משום מיעוטו המקפיד, אי נמי\u0004 \u0005[או גם כן]\u0006 נגזור עליו \u0003משום רובו שאינו מקפיד!\u0004","ומשיבים: דבר זה לא ייתכן, \u0003היא גופא\u0004 \u0005[עצמה]\u0006 ההלכה בשאינו מקפיד, הלא \u0003גזירה\u0004 בלבד היא, \u0003ואנן ניקום ונגזר\u0004 \u0005[ואנחנו נעמוד ונגזור]\u0006 \u0003גזירה לגזירה?!\u0004 על כל פנים למדנו שיש הלכה למשה מסיני מהו הקרוי חציצה.","הלכה למשה מסיני ששיעורן המינימלי של \u0003מחיצין\u0004 בכל מקום הוא עשרה טפחים — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 וכפי שכבר נתבאר. ושואלים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 לשיטת \u0003ר' יהודה,\u0004 שלדעתו אין ללמוד דבר זה מן המקרא, ולכן לדעתו דבר זה נתקבל כהלכה למשה מסיני, \u0003אלא ל\u0004שיטת \u0003ר' מאיר\u0004 שלדבריו כל האמות האמורות הן בנות שישה טפחים וניתן איפוא ללמוד שיעור עשרה טפחים מן הפסוקים, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלא לשיטתו דין זה אינו צריך להלכה שבעל פה!","ומשיבים: לשיטה זו \u0003כי אתאי הלכתא\u0004 \u0005[כאשר באה ההלכה]\u0006 לענין מחיצות, לשאר הלכות שיש בדיני מחיצות היא באה. כגון: \u0003גוד\u0004 \u0005[משוך],\u0006 כשחסירה חלק מן המחיצה ומחשיבים כאילו נמשך חלקה הקיים של המחיצה כלפי מעלה או כלפי מטה, ונחשב המקום כסגור במחיצה גם כשאין בו מחיצה של ממש. וכן לדין \u0003לבוד\u0004 \u0005[צמוד],\u0006 שכל שני דברים הסמוכים זה לזה בפחות משלושה טפחים נחשבים כמחוברים יחד, ודין \u0003דופן עקומה,\u0004 שדופן סוכה הנמצאת במרחק של פחות מארבע אמות מן הסכך נחשבת כמתעקמת ונוגעת בסכך — אלו נלמדים מהלכה.","עוד למדנו במשנה לענין פסול בסוכה, שכל \u0003שאין לה שלש דפנות\u0004 — הריהי פסולה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003שתים\u0004 מן הדפנות צריכות להיות בכל אורך ורוחב הסוכה \u0003כהלכתן, ושלישית\u0004 די שיהיה בה \u0003אפילו טפח. ר' שמעון אומר: שלש\u0004 דפנות צריך שיהיו שלימות \u0003כהלכתן, ורביעית אפילו טפח.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]\u0006 ובשל כך הגיעו לשיטות אלה? \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003יש אם למסורת.\u0004 כלומר: שיש ללמוד להלכה ממסורת הכתיב שבתורה, וכפי הכתיב כך קוראים עניינם אף לענין הלכה. \u0003ור' שמעון סבר: יש אם למקרא.\u0004 כלומר: עיקר ההלכה היא לפי הקריאה המקובלת, גם אם אין הכתיב זהה עמה בכל. כיצד?","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003יש אם למסורת,\u0004 נאמר שתי פעמים \"בסכת\", חסר (\"\u0003בסכת\u0004 תשבו שבעת ימים כל האזרח בישראל ישבו \u0003בסכת\u0004\". \u0005ויקרא כג, מב\u0006), שיש להבינו כסוכה אחת בלבד, ופעם אחת נאמר \"בסכות\", מלא (\"למען ידעו דורותיכם כי \u0003בסכות\u0004 הושבתי את בני ישראל\". ויקרא כג, מג), בלשון רבים, ומיעוט רבים שתים, \u0003הרי\u0004 שנרמזו \u0003כאן\u0004 בלשון הכתוב \u0003ארבע\u0004 פעמים.","\u0003דל חד לגופיה\u0004 \u0005[הורד\u0006 מקרא \u0005אחד לגופו]\u0006 לעצם הענין של מצות סוכה, \u0003פשו להו תלתא\u0004 \u0005[נשארו להם שלוש],\u0006 ושלוש פעמים אלה באו ללמד לענין דפנות שתהיינה שלוש, \u0003שתים\u0004 מהן \u0003כהלכתן,\u0004 דפנות גמורות, \u0003ואתאי הלכתא\u0004 \u0005[ובאה ההלכה\u0006 למשה מסיני\u0005]\u0006 \u0003וגרעתה ל\u0004דופן ה\u0003שלישית ואוקמה\u0004 \u0005[והעמידה אותה]\u0006 על \u0003טפח\u0004 בלבד, שלמדנו ממנה כי דופן אחת אינה חייבת להיות שלימה, ודי לה בשיעור טפח.","ואילו \u0003ר' שמעון סבר: יש אם למקרא,\u0004 ולכן אף שנכתבו בכתיב חסר, מאחר שקוראים אותם כבכתיב מלא \u0003\"בסכות\" \"בסכות\" \"בסכות\", הרי\u0004 לפי זה נרמזו \u0003כאן שש\u0004 סוכות, \u0003דל חד קרא לגופיה\u0004 \u0005[הסר כתוב אחד לגופו]\u0006 לענין מצוות סוכה, ונשאר פעמיים \"בסכות\", \u0003פשו להו\u0004 \u0005[נשארו להן]\u0006 \u0003ארבעה, שלש\u0004 מהן \u0003כהלכתן,\u0004 ו\u0003אתאי הלכתא\u0004 \u0005[באה הלכה\u0006 למשה מסיני\u0005]\u0006 \u0003וגרעתה ל\u0004דופן ה\u0003רביעית, ואוקמה\u0004 \u0005[והעמידה אותה]\u0006 על \u0003טפח,\u0004 שדבר זה קיבלו כהלכה, שאין כל דפנות הסוכה חייבות להיות שלימות ואחת מהן יכולה להיות קצרה מן השאר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור];\u0006 שיכול אתה להסביר את המחלוקת כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יש אם למקרא, והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006עקרון \u0005זה נחלקו]\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים \u0005סברו]\u0006 כי \u0003סככה\u0004 — עצם הענין שהסוכה צריכה כיסוי של סכך — \u0003בעיא קרא\u0004 \u0005[צריכה כתוב]\u0006 מיוחד, שנלמד שיש צורך בכיסוי זה ולא בדפנות בלבד ולכן נצרך אחד מלשונות \"סוכה\" שנאמרו בכתוב לגופו, כדי ללמד על דבר זה ונותר איפוא רמז רק לשלוש. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר\u0004 כי \u0003סככה לא בעיא קרא\u0004 \u0005[צריכה כתוב],\u0006 כיון שעצם משמעות המלה \"סוכה\" מלמדת על ענין הסכך. ומתוך שאינו צריך ללשון מיוחדת כדי להורות על כך, נותר איפוא בעינו רמז לארבעה דפנות ומן ההלכה למד אתה כי הדופן הרביעית אינה צריכה להיות שלימה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יש אם למסורת,\u0004 שממסורת הכתיב אנו למדים, \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006דבר \u0005זה נחלקו];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים \u0005סברו]:\u0006 \u0003כי אתאי הלכתא\u0004 \u0005[כאשר באה ההלכה\u0006 למשה מסיני\u0005],\u0006 לומר שאחת מדפנות הסוכה דיה שתהיה טפח — \u0003לגרע\u0004 היא באה, וללמד שאחת משלוש הדפנות הרמוזות אינה צריכה להיות שלימה. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר: כי אתאי הלכתא\u0004 \u0005[כאשר באה ההלכה],\u0006 הריהי באה \u0003להוסיף\u0004 ולומר כי נוסף לשלוש הדפנות צריכה להיות דופן אחת נוספת, ודופן זו, דיה שתהיה בת טפח.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא כי אתאי הלכתא\u0004 \u0005[לדעת הכל כאשר באה ההלכה],\u0006 כדי \u0003לגרע\u0004 מן השיעור היא באה ולדעת הכל \u0003יש אם למסורת.\u0004 ולפי זה נרמז ארבע פעמים סוכה, \u0003והכא\u0004 \u0005[וכאן]\u0006 בשאלה האם \u0003דורשין תחילות קמיפלגי\u0004 \u0005[נחלקו].\u0006 כלומר: כאשר אנו סופרים לענין הלכה כמה פעמים מוזכרת מלה מסויימת בכתוב, בכך נחלקו האם יש לדרוש לצורך ענין זה גם את הפעם הראשונה שנזכרה מלה זו, או שיש לומר כי הפעם ראשונה לעניינה נזכרה, ולא ללמד ממנה למנין. ש\u0003מר\u0004 \u0005[חכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר\u0004 כי \u0003דורשין תחילות,\u0004 והרי כאן רמז איפוא לארבע פעמים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים \u0005סברו]\u0006 כי \u0003אין דורשין תחילות.\u0004","\u0003רב מתנה אמר: טעמיה\u0004 \u0005[טעמו]\u0006 של \u0003ר' שמעון מהכא\u0004 \u0005[מכאן]\u0006 ממקרא זה שנאמר: \u0003\"וסכה תהיה לצל יומם מחרב ולמחסה ולמסתור מזרם וממטר\"\u0004 (ישעיה ד, ו), וסוכה שאין בה שלוש דפנות גמורות אינה יכולה לשמש כמחסה ומסתור.","ושואלים: לפי ההלכה שסוכה צריכה שתהיינה בה שתי דפנות שלימות ודופן נוספת בת טפח, \u0003אותו טפח\u0004 של דופן שלישית \u0003היכן מעמידו? אמר רב: מעמידו כנגד היוצא.\u0004 כלומר: מניח את הדופן השלישית בסוף דופן אחת מול הדופן האחרת.","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003רב כהנא ורב אסי לרב:\u0004"],["\u0003ויעמידנו\u0004 את הטפח העודף \u0003כנגד ראש תור?!\u0004 כלומר: מדוע לא יניחנו באלכסון ובכך יצור כעין משולש, כך שתראה הסוכה דומה יותר לבית גמור! \u0003שתיק\u0004 \u0005[שתק]\u0006 \u0003רב\u0004 ולא ענה דבר.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן];\u0006 \u0003אמר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003לוי: מעמידו\u0004 לדופן השלישית \u0003כנגד היוצא. וכן מורין בי מדרשא\u0004 \u0005[\u0006היו \u0005מורים בבית המדרש]:\u0006 \u0003מעמידו כנגד היוצא.\u0004","\u0003ר' סימון ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' יהושע בן לוי אמר,\u0004 שיש להשלים את המחיצה באופן אחר; \u0003עושה לו\u0004 את הטפח של דופן שלישית \u0003טפח שוחק,\u0004 כלומר: טפח שמידתו שלימה ועודפת במקצת, \u0003ומעמידו בפחות משלשה טפחים סמוך לדופן וכל פחות משלשה סמוך לדופן כלבוד דמי\u0004 \u0005[הוא נחשב],\u0006 שנידון כאילו הוא מחובר, ומצטרף החלל עם הדופן לעשות מחיצה בת ארבעה טפחים, שהיא רוב דופן סוכה קטנה.","\u0003אמר רב יהודה: סוכה העשויה כמבוי,\u0004 כלומר: שיש בה שתי דפנות שלימות זו כנגד זו — \u0003כשרה, ואותו טפח\u0004 של דופן שלישית \u0003מעמידו\u0004 בצמוד \u0003לכל רוח\u0004 (צד) \u0003שירצה,\u0004 שאין צורך אלא להיכר בלבד, ודיו בכך.","\u0003ר' סימון ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יהושע בן לוי אמר:\u0004 בסוכה העשויה כמבוי מפולש לא די בדופן בת טפח, אלא \u0003עושה לו פס\u0004 רחב \u0003ארבעה\u0004 טפחים \u0003ומשהו, ומעמידו בפחות משלשה\u0004 טפחים \u0003סמוך לדופן\u0004 לסתום אחד מפתחי סוכה זו וכיון ש\u0003כל פחות משלשה\u0004 טפחים \u0003סמוך לדופן, כלבוד דמי\u0004 \u0005[הוא נחשב],\u0006 הרי כאן שלוש מחיצות גמורות.","ושואלים: \u0003ומאי שנא התם\u0004 \u0005[ומה שונה שם]\u0006 כשיש שתי מחיצות צמודות \u0003דקאמרת סגיא\u0004 \u0005[שאומר אתה כי די\u0006 לו\u0005]\u0006 ב\u0003טפח שוחק\u0004 כדי להכשירו כדופן שלישית, \u0003ומאי שנא הכא דקאמרת בעיא\u0004 \u0005[ומה שונה כאן שאתה אומר\u0006 ש\u0005צריך]\u0006 \u0003פס ארבעה?\u0004 ומשיבים: יש הבדל; \u0003התם דאיכא\u0004 \u0005[שם שיש]\u0006 \u0003שתי דפנות כהלכתן\u0004 והן צמודות זו לזו ויוצרות כעין מבנה — \u0003סגי ליה\u0004 \u0005[די לו]\u0006 \u0003בטפח שוחק\u0004 כדי להשלים לדופן שלישית ובכך להכשיר את הסוכה, אבל \u0003הכא דליכא\u0004 \u0005[כאן שאין],\u0006 \u0003שתי דפנות\u0004 כהלכתן, כיון שאין הדפנות צמודות זו לזו ואין קשר ביניהן, \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003פס ארבעה\u0004 כדי להתיר — \u0003אין\u0004 \u0005[כן],\u0006 ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003לא — לא.\u0004","\u0003אמר רבא: ואינה נתרת\u0004 אותה סוכה העשויה כמבוי בדופן שלישית בת טפח \u0003אלא בצורת הפתח,\u0004 כלומר: שיחלק את אותו דופן בת טפח לשתים ויצמיד את אחד מחלקיה לצידו האחד של אחד הצדדים הפתוחים ואת חלקו האחר בצידו השני של צד זה ויניח קנה על גביהם ובכך תיעשה צורת הפתח שהיא כעין שער פתוח, ונחשבת בהלכה כעין מחיצה.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בנוסח שונה במקצת, ש\u0003אמר רבא: ונתרת\u0004 סוכה זו העשויה כמבוי \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003בצורת הפתח,\u0004 שלא דחה את הפתרון של ר' יהושע בן לוי, אלא אמר שאפשר להכשירה גם בצורת הפתח.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 גירסה שלישית ש\u0003אמר רבא: וצריכה\u0004 סוכה זו כדי להכשירה \u0003נמי\u0004 \u0005[גם כן]\u0006 ל\u0003צורת הפתח,\u0004 שנוסף לתיקון הדופן כשיטת ר' יהושע בן לוי, יש צורך גם בצורת הפתח כדי להכשירה.","מסופר: \u0003רב אשי אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רב כהנא דקא עביד\u0004 \u0005[שהוא עושה]\u0006 תיקון בסוכה העשויה כמבוי, על ידי \u0003טפח שוחק, וקא עביד\u0004 \u0005[ועושה]\u0006 גם \u0003צורת הפתח. אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרב כהנא: וכי \u0003לא סבר מר להא דרבא\u0004 \u0005[סבור אדוני לזו,\u0006 לשיטתו \u0005של רבא]?\u0006 ש\u0003אמר רבא: ונתרת נמי\u0004 \u0005[גם כן]\u0006 \u0003בצורת הפתח,\u0004 ולשם מה לך תיקון נוסף בטפח? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003אנא כאידך לישנא\u0004 \u0005[אני כלשון האחרת]\u0006 שמסרו בשם \u0003רבא סבירא לי\u0004 \u0005[סבור אני].\u0006 ש\u0003אמר רבא: וצריכה נמי\u0004 \u0005[גם כן]\u0006 \u0003צורת הפתח,\u0004 שיש צורך בשני תיקונים יחד.","שנינו בתוספתא כי אם היו דפנות הסוכה \u0003שתים כהלכתן\u0004 והשלישית אפילו טפח — הרי זו סוכה כשרה. \u0003אמר רבא: וכן ל\u0004ענין \u0003שבת\u0004 החלה בתוך חג הסוכות, שאם עשה סוכה מעין זו ברשות הרבים סמוך לפתח ביתו, הריהי נחשבת בשבת זו אף כרשות היחיד לענין היתר הטלטול ממנה לביתו ולהיפך, אף שבכל שבת אחרת, אין בכך כדי להחשיב את המקום כרשות היחיד. וטעמו: \u0003מגו דהויא\u0004 \u0005[מתוך שהיא\u0006 נחשבת\u0005]\u0006 כ\u0003דופן לענין סוכה\u0004 — \u0003הויא\u0004 \u0005[הרי היא\u0006 נחשבת\u0005]\u0006 כ\u0003דופן\u0004 גם \u0003לענין שבת.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי: ומי אמרינן מגו\u0004 \u0005[והאם אומרים אנו \"מתוך\"]\u0006 בהלכות אלה, לומר שאם לענין תחום אחד נחשב דבר כדופן, יחשב כן אף לענין תחומים אחרים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 דיניה והגדרותיה של \u0003דופן\u0004 לענין \u0003סוכה\u0004 הריהם \u0003כדופן\u0004 לענין \u0003שבת,\u0004 שכשם שלענין שבת אפשר ליצור מחיצה על ידי העמדת קנים סמוכים זה לזה — כן גם לענין סוכה. \u0003ובלבד שלא יהא בין קנה לחברו\u0004 מרחק \u0003שלשה טפחים,\u0004 שביותר משלושה טפחים שוב אינם נחשבים כצמודים זה לזה.","\u0003ויתירה\u0004 כלומר, חמורה דין מחיצה לענין \u0003שבת על\u0004 זו המיועדת להכשר \u0003סוכה, ש\u0004מחיצה לענין \u0003השבת אינה נתרת אלא ב\u0004כשחלק המחיצה ה\u0003עומד מרובה על הפרוץ,\u0004 שכדי שגדר תיחשב כמחיצה נחוץ שהחלק העומד (כלומר: הקיים בפועל במחיצה זו), יהיה מרובה על הפרוץ, \u0003מה שאין כן בסוכה,\u0004 שאף אם מרובה בה החלק הפרוץ על העומד (וכגון סוכה שאין לה אלא שתי דפנות ואף הן אינן שלימות, אלא בהן קיימים פתחים, והשלישית אינה אלא בת טפח) — כשרה.","ונדייק: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה בברייתא זו: \u0003יתירה\u0004 חומרת \u0003שבת דסוכה\u0004 (שבת שבחג הסוכות) על זו של \u0003סוכה, ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 \u0003\"מגו\"\u0004 \u0005[מתוך]\u0006 שנחשבת מחיצה זו כדופן לענין סוכה, תיחשב כמחיצה אף לענין דיני שבת, וקשה איפוא לדברי רבא, שהסתמך על טענה זו!","ודחה רבא: \u0003לא,\u0004 כך יש להבין את הברייתא: \u0003יתירה שבת דעלמא\u0004 \u0005[שבכלל,\u0006 של כל ימות השנה\u0005]\u0006 \u0003על שבת דסוכה\u0004 (זו שחלה בחג הסוכות), כי בשבת שבחג הסוכות מחיצה שהפרוץ מרובה בה, כיון שנחשבת כדופן לענין סוכה, יש איפוא להחשיבה כדופן אף לענין שבת, מה שאין כן בשבת אחרת, שאז אין מחיצה זו נחשבת.","הקשה לו אביי: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שההשוואה היא לא בין דיני שבת ודיני סוכה בכלל, אלא במקרה מיוחד של שבת שבחג הסוכות, אם כן \u0003ליתני נמי\u0004 \u0005[שישנה גם כן]\u0006 חידוש אחר הנובע מצירוף זה, ויאמר ש\u0003יתירה\u0004 וחמורה הכשרה של \u0003סוכה דעלמא\u0004 \u0005[בכלל]\u0006 על \u0003סוכה\u0004 זו של \u0003שבת,\u0004 ש\u0003אילו סוכה דעלמא\u0004 \u0005[בכלל]\u0006 בשאר ימות החול, אם היתה זו סוכה מפולשת \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003טפח שוחק\u0004 כדי להיות דופן שלישית לסוכה, \u0003ואילו סוכה\u0004 העומדת ב\u0003שבת, לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003טפח שוחק\u0004 לצורך זה, \u0003וסגי\u0004 \u0005[ודי\u0006 לה\u0005]\u0006 \u0003בלחי,\u0004 שהוא פס גבוה עשרה טפחים ורחב כל שהוא, שדי בו כדי לסמל שזו תחילתה של מחיצה שלישית, שכיון שלחי כזה מועיל לענין שבת, יהא אף כשר למצוות סוכה ביום השבת אף שאין ברוחבו טפח ואינו גבוה דיו,","\u0003דהא את\u0004 \u0005[שהרי אתה]\u0006 עצמך \u0003הוא דאמרת\u0004 \u0005[שאמרת]:\u0006 \u0003סיכך על גבי מבוי שיש לו לחי\u0004 העשוי כדי להכשירו לענין טלטול בשבת — \u0003כשר\u0004 הוא גם לענין סוכה באותה שבת, אף על פי שאינו כשר לימות החול. וזאת מתוך שכשר לענין שבת, כשר אף לענין סוכה!","והשיב לו רבא: אכן כך סבור אני, אבל העובדה שאין הדבר נזכר בברייתא אינה מהוה כל קושי, כי \u0003ההוא לא אצטריכא ליה\u0004 \u0005[דבר זה לא הוצרך לו]\u0006 להיאמר שיש מקרה שיתירה וחמורה הדרישה בדין סוכה בכלל על דין סוכה של שבת, שאין חידוש בכך שדבר הכשר להלכות שבת מועיל גם להלכות סוכה, \u0003השתא מקילתא לחמירתא אמרינן\u0004 \u0005[עכשיו מ\u0006דבר \u0005קל ל\u0006דבר \u0005חמור אומרים אנו],\u0006 שהרי כיון שאמרנו שדבר הכשר לדין סוכה, שאינה אלא מצות עשה, יש לו תוקף גם לדין שבת החמורה שאיסורה איסור כרת, \u0003מחמירתא לקילתא\u0004 \u0005[מחמורה לקלה]\u0006 \u0003לא כל שכן,\u0004 שוודאי שדבר שיש לו תוקף לדין שבת החמור, כל שכן שיש לו תוקף לדין סוכה שאינו חמור עד כדי כך. ולכן לא היה צורך להזכיר את הדבר בברייתא.","\u0003גופא,\u0004 כיון שהוזכרה ההלכה בענין סיכוך על גבי מבוי, מעירים לגופה של אותה ההלכה. \u0003אמר רבא:\u0004"],["\u0003סיכך על גבי מבוי שיש לו לחי\u0004 — \u0003כשרה,\u0004","\u0003ו\u0004כיוצא בזה \u0003אמר רבא: סיכך על גבי פסי ביראות\u0004 (בורות) — \u0003כשרה.\u0004 שכאשר קיים בור מים ציבורי ברשות הרבים, וכדי שיוכלו לשאוב ממנו בשבת יש לעשות שהמקום שסביב בור המים יהיה רשות היחיד. ואם אי אפשר לעשות מסביבו מחיצה גמורה, עושים \"פסי ביראות\" — זויות כפולות בארבע פינות מסביב, וזויות אלה מחשיבות את כל השטח שבתוכן כרשות היחיד. וכיון שלענין שבת נחשבים הפסים כמחיצות — אף לענין סוכה כן.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך\u0006 היה\u0005]\u0006 רבא להשמיע לנו את שיטתו בשני המקרים, למרות דמיונם זה לזה. \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 הכשר סוכה ב\u0003מבוי\u0004 בלבד, היינו אומרים: \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003שתי דפנות מעלייתא\u0004 \u0005[מעולות,\u0006 גמורות\u0005],\u0006 שהרי שתיים מדפנותיו הן דפנות גמורות כהלכתן. \u0003אבל גבי פסי ביראות דליכא\u0004 \u0005[שאין]\u0006 באופן זה \u0003שתי דפנות מעלייתא\u0004 \u0005[מעולות]\u0006 ורובו פרוץ \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא.\u0004","ולהיפך; \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 את ההלכה הזאת רק ב\u0003פסי ביראות,\u0004 הייתי אומר \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003שם ארבע דפנות,\u0004 ואף שאינן שלימות, מכל מקום על ידי הזויות נוצרות כביכול ארבע דפנות, \u0003אבל סיכך על גבי מבוי, דליכא\u0004 \u0005[שאין]\u0006 \u0003שם ארבע דפנות אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא.\u0004","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005את שתי אלה]\u0006 ללמדנו שמחיצה הכשרה לענין שבת, כשרה גם לדין סוכה, היינו אומרים \u0003מחמירתא\u0004 \u0005[\u0006מדין \u0005חמור]\u0006 של שבת \u0003לקילתא\u0004 \u0005[ל\u0006דין \u0005קל]\u0006 של סוכה מובן שהדבר מועיל, \u0003אבל מקילתא\u0004 \u0005[מ\u0006דין \u0005קל],\u0006 דין סוכה \u0003לחמירתא\u0004 \u0005[ל\u0006דין \u0005חמור]\u0006 של שבת \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יועיל, על כן \u0003צריכא\u0004 \u0005[הוצרכה\u0006 לומר\u0005]\u0006 גם הלכה שלישית, שכל מחיצה הנחשבת כדופן לסוכה תיחשב כמחיצה גם לענין דיני שבת באותה שבת.","שנינו במשנה כי סוכה \u0003שחמתה מרובה מצלתה\u0004 — \u0003פסולה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חמתה\u0004 מרובה מצילתה, הכוונה שהחמה באה \u0003מחמת סיכוך, ולא מחמת\u0004 ה\u0003דפנות.\u0004 כי יתכן שתכנס רוב חמה דרך דפנות הסוכה ובכל זאת תהא הסוכה כשרה. \u0003ר' יאשיה אומר:\u0004 אם חמתה מרובה \u0003אף מחמת דפנות\u0004 — פסולה.","\u0003אמר רב יימר בר שלמיה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יאשיה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וסכת על הארן את הפרכת\"\u0004 (שמות מ, ג), \u0003פרכת\u0004 הלא \u0003מחיצה\u0004 בלבד היא ולא כיסוי עליון, \u0003וקא קרייה רחמנא\u0004 \u0005[וקראה לה התורה]\u0006 בלשון \u0003\"סככה\"\u0004 (\"וסכות\"), \u0003אלמא\u0004 \u0005[מכאן]\u0006 כי ייעודה של \u0003מחיצה כ\u0004ייעודו של ה\u0003סכך בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה וכשם שהסכך צריך להיות אטום ברובו כך צריכה להיות אף המחיצה.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם סבורים כן, מה הוא לדעתם פירוש \"וסכות\"? \u0003ההוא\u0004 ללמד \u0003דניכוף ביה פורתא\u0004 \u0005[שנכוף אותה,\u0006 את הפרוכת, \u0005מעט]\u0006 \u0003דמחזי\u0004 \u0005[שנראית]\u0006 \u0003כסכך,\u0004 כלומר: שלא תהא הפרוכת מחיצה ישרה לגמרי, אלא תהא כפופה בראשה במקצת.","\u0003אמר אביי: רבי, ור' יאשיה, ור' יהודה, ור' שמעון, ורבן גמליאל, ובית שמאי, ור' אליעזר, ואחרים, כולהו סבירא להו\u0004 \u0005[כולם סבורים]\u0006 להחזיק בשיטה אחת לענין סוכה, והיא; כי \u0003סוכה דירת קבע בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה, שהסוכה צריכה להיות בנויה היטב וראויה למגורים כשאר דירות.","ומעתה מפרט אביי את הדעות בשיטה זו; \u0003רבי\u0004 כיצד מתבטאת שיטה זו בדבריו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005];\u0006 \u0003רבי אומר: כל סוכה שאין בה ארבע אמות על ארבע אמות פסולה\u0004 ומידה זו היא כאמור המידה הראויה לבית גמור.","\u0003ר' יאשיה — הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 והובאו דבריו לעיל, שאף הדפנות צריכות להיות אטומות כקירות בית ממש.","\u0003ר' יהודה — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003סוכה שהיא גבוהה למעלה מעשרים אמה\u0004 — \u0003פסולה, ור' יהודה מכשיר,\u0004 וכבר פירשנו שאחת מן המשמעויות המעשיות בגובה זה, שהסוכה אינה יכולה להיעשות כדירת ארעי, אלא כבנין גמור.","\u0003ור' שמעון — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מהו הכשר סוכה — כשיהיו לה \u0003שתי\u0004 דפנות שלימות \u0003כהלכתן ושלישית\u0004 די שיהא רוחבה \u0003אפילו טפח, ר' שמעון אומר: שלש\u0004 דפנות צריכות להיות שלימות \u0003כהלכתן ורביעית אפילו טפח,\u0004 הרי שלפי דעתו צריכה הסוכה להיות סגורה מכל צידיה כראוי, כעין בית.","\u0003רבן גמליאל\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003העושה סוכתו בראש העגלה או בראש הספינה, רבן גמליאל פוסל\u0004 שמאחר שהיא ניידת, אינה כדירת קבע, \u0003ור' עקיבא מכשיר.\u0004 הרי שלדעת בית שמאי צריכה הסוכה להיעשות כדירת קבע.","\u0003בית שמאי\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהיה ראשו ורובו בסוכה ושולחנו בתוך הבית, בית שמאי פוסלים,\u0004 שלדעתם, כיון שאין סוכה קטנה ראויה לשימוש, אינה כשרה למצוותה, \u0003ובית הלל מכשירים.\u0004 הרי שלדעת בית שמאי צריכה הסוכה להיות דומה לדירת קבע.","\u0003ר' אליעזר\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003העושה סוכתו כמין צריף,\u0004 כדמות אהל שאין לו גג וכולו עשוי שיפוע, \u0003או שסמכה לכותל,\u0004 שנטל קנים ארוכים וסמך את ראשם האחד לכותל בצורה בשיפוע ואת השני לרצפה, ואף לזו אין גג, \u0003ר' אליעזר פוסל לפי שאין לה גג, וחכמים מכשירין.\u0004","שיטת \u0003אחרים\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחרים אומרים: סוכה העשויה כשובך\u0004 (עגולה כולה) — \u0003פסולה, לפי שאין לה זויות\u0004 ובית גמור כהלכה צריך שיהיו לו זויות.","\u0003אמר ר' יוחנן: סוכה העשויה ככבשן,\u0004 שהיא עגולה מכל צד, \u0003אם יש בהיקפה\u0004 הפנימי מספיק מקום \u0003כדי לישב בה עשרים וארבעה בני אדם\u0004 — \u0003כשרה, ואם לאו\u0004 — \u0003פסולה.\u0004","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמר ר' יוחנן שצריך שטח הסוכה להיות כה רחב — ללא ספק כדעת \u0003רבי,\u0004 ש\u0003אמר\u0004 כי \u0003כל סוכה שאין בה ארבע אמות על ארבע אמות — פסולה,\u0004 ומתוך ששיטתו היא המפליגה ביותר בענין שטח הסוכה, ודאי שדברי ר' יוחנן כשיטתו.","אולם אף לשיטה זו עדיין יש מקום לתמיהה: \u0003מכדי\u0004 \u0005[הרי],\u0006 \u0003גברא באמתא יתיב\u0004 \u0005[אדם יושב\u0006 ותופס שיעור \u0005אמה\u0006 בישיבתו\u0005],\u0006 ואם כן מצריך ר' יוחנן שתהא בהיקפה של סוכה זו עשרים וארבע אמות, \u0003ו\u0004כלל הוא ש\u0003כל שיש בהיקפו שלשה טפחים יש בו רוחב טפח,\u0004 ואם כן \u0003בתריסר סגי\u0004 \u0005[בשנים עשר מספיק].\u0006 שהרי בהיקף שתים עשרה אמה של עיגול יש לפי חשבון זה קוטר ארבע אמות, ויש כבר בסוכה ארבע אמות על ארבע אמות, ומדוע הצריך איפוא ר' יוחנן היקף גדול כפליים?"],["\u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 שעיגול של שתים עשרה אמה יש ברוחבו ארבע אמות, הרי זה דווקא \u0003בעיגולא\u0004 \u0005[בעיגול]\u0006 המצוי בתוכו, \u0003אבל בריבועא\u0004 \u0005[בריבוע]\u0006 \u0003בעיא טפי\u0004 \u0005[צריך יותר].\u0006","ומקשים שוב: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כמה מרובע יותר על העיגול\u0004 — יודעים אנו שהוא גדול ממנו \u0003רביע,\u0004 ואם כן \u0003בשיתסר סגי\u0004 \u0005[בששה עשר די]\u0006 שהוא רבע יתר על שתים עשרה, ומדוע אמר עשרים וארבע?","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 שאמרנו\u0005]\u0006 ביתרון גודל מרובע על העיגול היינו \u0005[הרי הוא]\u0006 \u0003בעיגול דנפיק מגו ריבועא\u0004 \u0005[היוצא,\u0006 הנתון \u0005מתוך ריבוע]\u0006 \u0003אבל ריבועא דנפיק מגו עיגולא\u0004 \u0005[ריבוע היוצא,\u0006 הנתון \u0005מתוך עיגול]\u0006 \u0003בעיא טפי\u0004 \u0005[צריך יותר],\u0006 \u0003משום מורשא דקרנתא\u0004 \u0005[בליטת הזוויות]\u0006 של הריבוע, וכדי שיכנס מרובע שהיקפו שתים עשרה אמה לתוך עיגול, צריך שיהיה היקף העיגול גדול בהרבה.","ומוסיפים להקשות: הבה נחשב כמה היקף נוסף בשל בליטה זו, \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כל אמתא בריבועא אמתא ותרי חומשא באלכסונא\u0004 \u0005[כל אמה בריבוע\u0006 יש בה \u0005אמה ושתי חמישיות באלכסון],\u0006 והלא רוחב העיגול בכל צידיו כמידת הרוחב שבין זוית המרובע האחת לחבירתה האלכסונית לה וצריך להוסיף איפוא לחשבון עוד שתי חמישיות לכל אמה, ואם כן אף לפי חשבון זה \u0003בשיבסר נכי חומשי סגיא\u0004 \u0005[בשבעה עשר חסר חומש די],\u0006 לפי חשבון שתים עשרה אמות בתוספת שתי חמישיות לכל אמה. ומשיבים: ר' יוחנן \u0003לא דק\u0004 \u0005[דייק]\u0006 והגדיל במעט את המידה.","ותוהים: \u0003אימור דאמרינן לא דק פורתא\u0004 \u0005[אמור שאנו אומרים\u0006 כי \u0005לא דייק,\u0006 הרי זה \u0005במעט],\u0006 אולם \u0003טובא מי אמרינן לא דק\u0004 \u0005[הרבה האם אומרים אנו\u0006 כי \u0005לא דייק]?\u0006 וכאן עדיין יש הבדל של שמונה אמות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי: מי סברת גברא באמתא יתיב\u0004 \u0005[האם סבור אתה כי אדם בתוך אמה הוא יושב]\u0006 ומקום מושב עשרים וארבעה אנשים הריהו עשרים וארבע אמות, אינו כן אלא \u0003תלתא גברי בתרתי אמתא יתבי\u0004 \u0005[שלושה בני אדם בשתי אמות הם יושבים]\u0006 וההיקף הנדרש הוא איפוא קטן יותר. ושואלים: \u0003כמה הוו להו\u0004 \u0005[כמה הם]\u0006 הנדרשות אם כן לישיבת עשרים וארבעה בני אדם — \u0003שיתסר\u0004 \u0005[שש עשרה]\u0006 אמות, \u0003אנן שיבסר נכי חומשא בעינן\u0004 \u0005[אנחנו שבע עשרה פחות חומש צריכים אנו]\u0006 כפי שחשבנו קודם! ומשיבים: \u0003לא דק\u0004 \u0005[דייק]\u0006 ואכן יש להוסיף ארבע חמישיות אמה.","ודוחים: \u0003אימור דאמרינן לא דק לחומרא\u0004 \u0005[אמור שאנו אומרים שלא דייק להחמיר],\u0006 שהחכם קובע שיעור בלתי מדוייק כאשר המספר שנקב יש בו כדי להחמיר, אולם \u0003לקולא מי אמרינן לא דק\u0004 \u0005[להקל האם אומרים אנו\u0006 ש\u0005לא דייק]?\u0006 והרי מתוך חוסר הדיוק מתירים את האיסור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אסי לרב אשי: לעולם\u0004 יש לומר כי \u0003גברא באמתא יתיב\u0004 \u0005[אדם יושב\u0006 בשטח \u0005של אמה]\u0006 אולם \u0003ר' יוחנן\u0004 את \u0003מקום גברי\u0004 \u0005[האנשים]\u0006 עצמם \u0003לא קחשיב\u0004 \u0005[החשיב]\u0006 ואין לחשוב את היקף העיגול מבפנים, שהוא יהיה בן עשרים וארבע אמות, אלא מבחוץ, שכוונתו לכך שיש להושיב בהיקפו החיצוני עשרים וארבעה אנשים ומידת ההיקף האמורה הריהי מסביב להם.","ושואלים: \u0003כמה הוו להו\u0004 \u0005[יהיו להם\u0006 איפוא\u0005]\u0006 מספר האמות בהיקף הפנימי לישיבתם — \u0003תמני סרי\u0004 \u0005[שמונה עשרה],\u0006 שכן לכלל זה שרוחב עיגול שהיקפו שלוש הוא אחד, ולפי זה רוחב ההיקף של עשרים וארבעה אנשים הוא איפוא שמונה, ואם כן, לכשנמדוד את ההיקף הפנימי ללא רוחב האנשים, עלינו להחסיר מהחשבון את מידת רוחבם של שני אנשים (אחד לכל צד של הרוחב) ונותר איפוא רוחב של שש אמות בלבד והיקף עיגול שרוחבו שש אמות לכלל האמור הוא שמונה עשר אמות, והרי כבר חישבנו כי \u0003בשיבסר נכי חומשא סגיא\u0004 \u0005[בשבעה עשר חסר חומש די]!\u0006 ומשיבים: \u0003היינו דלא דק\u0004 \u0005[זהו\u0006 שאמרנו \u0005שלא דייק]\u0006 \u0003ולחומרא לא דק\u0004 \u0005[דייק],\u0006 שהוסיף קצת יותר מאמה.","\u0003רבנן\u0004 \u0005[חכמי]\u0006 המקום \u0003קיסרי ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003דייני\u0004 המקום \u0003קיסרי\u0004 הם ש\u0003אמרי\u0004 \u0005[אומרים]\u0006 שיש לפרש את דברי ר' יוחנן על בסיס שיטת חישוב אחרת; לדעתם \u0003עיגולא דנפיק מגו ריבועא\u0004 — \u0003רבעא\u0004 \u0005[העיגול היוצא מתוך הריבוע\u0006 פחות ממנו בשטחו ב\u0005רבע]\u0006"],["\u0003ריבועא דנפיק מגו עיגולא\u0004 \u0005[ריבוע היוצא מתוך העיגול]\u0006 הוא \u0003פלגא\u0004 \u0005[חצי]\u0006 מן העיגול. אך מעירים: \u0003ולא היא\u0004 \u0005[ואינו כן],\u0006 \u0003דהא קחזינן דלא הוי כולי האי\u0004 \u0005[שהרי רואים אנו שאינו\u0006 קטן ממנו \u0005עד כדי כך].\u0006","\u0003אמר ר' לוי משום\u0004 (בשם) \u0003ר' מאיר: שתי סוכות של יוצרים זו לפנים מזו\u0004 שהיו יוצרי כלי חרס עושים לעצמם שתי סוכות אחת בתוך השניה, הפנימית למגורים והחיצונית למלאכה ולמסחר — \u0003הפנימית\u0004 שבהן \u0003אינה סוכה\u0004 שהרי בה הוא דר כל השנה ואין הדבר ניכר שהוא דר בה לשם סוכה. אולם מאחר שהיא דירת קבע, הריהי \u0003חייבת במזוזה\u0004 בכל ימות השנה. \u0003והחיצונה\u0004 יכולה להיחשב כ\u0003סוכה,\u0004 שמתוך שאין דרכו לדור בה בכל ימות השנה ואינו דר בה אלא בימי הסוכות, ניכר הדבר שלשם מצות סוכה הוא עושה כן. ומתוך שאינה מיועדת למגורים בשאר ימות השנה ואינה משמשת אלא ככניסה לדירתו ולמעבר סוחרים וסחורה, לכך אינה נחשבת כדירה והריהי \u0003פטורה מן המזוזה.\u0004","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 תהא החיצונה פטורה מן המזוזה? \u0003תהוי\u0004 \u0005[תהא]\u0006 ה\u0003חיצונה\u0004 נחשבת \u0003כבית שער לפנימי, ותתחייב במזוזה!\u0004 ומשיבים: \u0003משום\u0004 ש\u0003לא קביע\u0004 \u0005[קבועה],\u0006 שהרי אף הפנימית אינה דירת קבע ממש, ואף אם חייבנו לקבוע מזוזה בפתח הפנימית — שהרי הוא דר בה בפועל, אין לחייב בשלה לקבוע מזוזה גם בפתח החיצונה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הסוכות שסימנן \u0003גנב\"ך,\u0004 והן: \u0003סוכת גוים, סוכת נשים, סוכת בהמה, סוכת כותים\u0004 (שומרונים) \u0003סוכה מכל מקום\u0004 — כל אחת מאלו \u0003כשרה\u0004 למצות סוכה, \u0003ובלבד שתהא מסוככת כהלכתה\u0004 ואינה נפסלת בשל מי שעשאה ובשל הצורך לו נעשתה.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כהלכתה\"? אמר רב חסדא: והוא שעשאה לצל סוכה,\u0004 כדי שיוכלו לחסות בצל סככה — הרי זו סוכה גם למצוה.","ושואלים: \u0003\"מכל מקום\"\u0004 שאמרנו \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005את מה],\u0006 אלו מקרים נוספים נכנסים בגדר זה? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 סוגי סוכות נוספים, השנויים בברייתא אחרת, וסימנן: \u0003סוכת רקב\"ש. דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003סוכת רקב\"ש,\u0004 והן: \u0003סוכת רועים, סוכת קייצים\u0004 (מייבשי תאנים) \u0003סוכת בורגנין\u0004 (שומרי שדות) \u0003סוכת שומרי פירות, סוכה מכל מקום\u0004 — כל אחת מאלו \u0003כשרה\u0004 למצות סוכה, \u0003ובלבד שתהא מסוככת כהלכתה.\u0004","ושאלנו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003כהלכתה, אמר רב חסדא: והוא שעשאה ל\u0004צורך \u0003צל סוכה.\u0004","ועוד שואלים: \u0003\"מכל מקום\" לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005מה],\u0006 מה מוסיפים על ידי כך? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את הסוכות שסימנן: \u0003סוכת גנב\"ך,\u0004 שכבר מנינו.","ומבארים: \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 ששנה ופירט בסוכות \u0003גנב\"ך, אלימא ליה\u0004 \u0005[חזקה לו,\u0006 ברורה בעיניו\u0005]\u0006 סוכת \u0003גנב\"ך משום דקביעי\u0004 \u0005[שהן קבועות],\u0006 אף על פי שעושיהן אינם חייבים במצות סוכה, \u0003וקא תנא\u0004 \u0005[ושנה]\u0006 \u0003\"מכל מקום\" לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 אפילו סוכות \u0003רקב\"ש\u0004 שהן \u0003לא קביעי\u0004 \u0005[קבועות],\u0006 שאינן נבנות אלא לצורך עונות מסויימות,","\u0003והאי תנא\u0004 \u0005[ותנא זה]\u0006 ששנה \u0003רקב\"ש, אלימא ליה\u0004 \u0005[חזק לו,\u0006 ברור לו\u0005]\u0006 ענין \u0003רקב\"ש דבני חיובא נינהו\u0004 \u0005[שבני חיוב\u0006 במצוות סוכה \u0005הם\u0006 העושים\u0005],\u0006 \u0003ותנא\u0004 \u0005[ושנה]\u0006 \u0003\"מכל מקום\", לאתויי\u0004 \u0005[להוסיף]\u0006 סוכות \u0003גנב\"ך,\u0004 שהרי בעליהן \u0003לאו בני חיובא נינהו\u0004 \u0005[אינם בני חיוב]\u0006 במצות סוכה, ובכל זאת כשרות הן למצות סוכה."],["\u0003סוכה ישנה\u0004 — \u0003בית שמאי פוסלין\u0004 למצות סוכה \u0003ובית הלל מכשירין. ואיזו היא סוכה ישנה, כל שעשאה\u0004 סתם \u0003קודם לחג שלשים יום\u0004 ולא פירש שהוא עושה אותה לשם מצות סוכה, ומן הסתם אכן לא לצורך החג עשאה אלא לצרכים אחרים. \u0003אבל אם עשאה\u0004 במפורש \u0003לשם\u0004 ה\u0003חג, אפילו\u0004 אם עשאה \u0003מתחלת השנה\u0004 שעברה — אף לדברי בית שמאי, הריהי \u0003כשרה.\u0004","שואלים: \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי?\u0004 ומסבירים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"חג הסכות שבעת ימים לה'\"\u0004 (ויקרא כג, לד), ומשם למדים כי \u0003סוכה העשויה\u0004 דווקא \u0003לשם חג בעינן\u0004 \u0005[צריכים אנו],\u0006 וסוכה שלא נעשתה במיוחד לשם קיום מצות החג פסולה.","ושואלים: \u0003ובית הלל\u0004 מה אומרים הם על כתוב זה? אומרים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005הוצרך לו]\u0006 \u0003ל\u0004כפי שאמר \u0003רב ששת,\u0004 ש\u0003אמר רב ששת משום\u0004 (משמו) של \u0003ר' עקיבא: מנין לעצי סוכה שאסורין כל שבעה\u0004 ימים של חג הסוכות לכל שימוש אחר, והרי הם נחשבים כמוקדשים לצורך מצוותם בלבד — \u0003תלמוד לומר: \"חג הסכות שבעת ימים לה'\"\u0004 (ויקרא כג, לד),","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 שיש בה ביאור לדרשה זו; \u0003ר' יהודה בן בתירה אומר: כשם שחל שם שמים על החגיגה, כך חל שם שמים על הסכה, שנאמר: \"חג הסכות שבעת ימים לה'\",\u0004 לומר: \u0003מה חג\u0004 (כלומר קרבן חגיגה) \u0003לה' — אף סוכה לה'.\u0004","ושואלים: \u0003ובית שמאי נמי מיבעי ליה להכי\u0004 \u0005[גם כן\u0006 הרי \u0005צריכים לו\u0006 לפסוק \u0005ל\u0006ענין \u0005זה]!\u0006 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא גם כן]\u0006 כלומר: באמת משמש פסוק זה לענין עצי סוכה,","\u0003אלא מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי\u0004 — \u0003כתיב קרא אחרינא\u0004 \u0005[נאמר כתוב אחר];\u0006 \u0003\"חג הסכת תעשה לך שבעת ימים\"\u0004 (דברים טז, יג), לומר: \u0003סוכה העשויה לשם חג בעינן\u0004 \u0005[צריכים אנו].\u0006","ושואלים: \u0003ובית הלל\u0004 מה למדים הם מפסוק זה? \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נחוץ לו]\u0006 ללמד כי \u0003עושין סוכה\u0004 אף \u0003בחולו של מועד\u0004 שאם לא הספיק אדם לעשות סוכה קודם לכן, או שנפלה סוכתו בתוך החג, חוזר ועושה אותה בחול המועד, שבכל שבעת הימים יש מצוה לעשות סוכה, גם אם לא עשאוה טרם החג.","\u0003ובית שמאי\u0004 מהיכן למדים הם דין זה — \u0003סבירא להו\u0004 \u0005[סבורים הם]\u0006 בהלכה זו \u0003כר' אליעזר,\u0004 ש\u0003אמר: אין עושין סוכה בחולו של מועד\u0004 ולכן נותר פסוק זה ללמד לענין חובת העשייה בכוונה לשם סוכה.","ובבירור עיקרי השיטות שואלים: \u0003ובית הלל לית להו\u0004 \u0005[\u0006וכי \u0005אין להם,\u0006 אינם מקבלים\u0005],\u0006 את הקביעה של \u0003רב יהודה אמר רב?\u0004 ש\u0003אמר רב יהודה אמר רב: עשאה\u0004 לציצית \u0003מן הקוצין,\u0004 שהם חוטים היוצאים מן האריג לאחר שנשתיירו מחוטים שנקרעו ממנו ונקשרו שוב ובולטים הם בבגד כקוצים, \u0003ומן הנימין\u0004 ראשי החוטים היוצאים מן התפר \u0003ומן הגרדין\u0004 ציציות חוטים שבשיפולי הארג — \u0003פסולה.\u0004 אולם אם נעשו הציציות \u0003מן הסיסין,\u0004 שהם פקעות של חוטים שלא נטוו לצורך זה — \u0003כשרה,\u0004","וסיפר רב יהודה: \u0003כי אמריתה\u0004 \u0005[כאשר אמרתי]\u0006 הלכה זו בשם רב \u0003קמיה\u0004 \u0005[לפני]\u0006 רבי האחר \u0003שמואל, אמר לי: אף מן הסיסין נמי\u0004 \u0005[גם כן]\u0006 \u0003פסולה, דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שתהא אף \u0003טויה\u0004 של החוטים \u0003לשמה.\u0004 ומתוך שרואים שעל המצוות להיעשות מתוך כוונה לשמן, \u0003הכא נמי נבעיא\u0004 \u0005[כאן גם כן נצטרך]\u0006 \u0003סוכה\u0004 שתהא \u0003עשויה לשמה!\u0004","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בציצית ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בציצית: \u0003\"גדלים תעשה לך\"\u0004 (דברים כב, יב), והמלה \"לך\" באה להדגיש ולומר; \u0003לך — לשם חובך,\u0004 שהעשייה מתחילתה צריכה להיות לשמה. ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הלא נאמר: \u0003\"חג הסכת תעשה לך\"\u0004 (דברים טז, יג), ואמור אף כאן: \u0003לך — לשם חובך!\u0004","ומשיבים: \"לך\" \u0003ההוא\u0004 שנאמר בפסוק \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 סוכה \u0003גזולה,\u0004 וכוונת הביטוי \"לך\" היא: שלך ולא של אחרים. ומקשים: \u0003התם נמי מיבעי ליה למעוטי\u0004 \u0005[שם גם כן\u0006 בציצית \u0005צריך \"\u0006לך\" \u0005למעט]\u0006 ציצית \u0003גזולה!\u0004","ומשיבים: \u0003התם כתיב קרא אחרינא\u0004 \u0005[שם\u0006 בציצית \u0005נאמר כתוב אחר];\u0006 \u0003\"ועשו להם\u0004 ציצית\u0003\"\u0004 (במדבר טו, לח), והדגשת המלה \"להם\" משמעה: \u0003משלהם\u0004 ולא משל אחרים, ולמדים מן המלה \"לך\" שהציצית צריכה להיעשות לשמה."],["\u0003העושה סוכתו תחת האילן\u0004 — \u0003כאילו עשאה בתוך הבית\u0004 ופסולה. עשה \u0003סוכה על גבי סוכה\u0004 — \u0003העליונה כשרה והתחתונה פסולה. ר' יהודה אומר: אם אין דיורין\u0004 (דיירים) הדרים \u0003ב\u0004סוכה ה\u0003עליונה\u0004 — אף \u0003התחתונה כשרה.\u0004","\u0003אמר רבא: לא שנו\u0004 הלכה זו שסוכה העשויה תחת האילן פסולה, \u0003אלא ב\u0004זו שנעשתה תחת \u0003אילן שצלתו\u0004 (צילו) \u0003מרובה מחמתו,\u0004 שהרי כל הצל בסוכה הוא מחמת האילן. \u0003אבל\u0004 אם היתה \u0003חמתו\u0004 של אותו אילן \u0003מרובה מצלתו\u0004 — \u0003כשרה,\u0004 שהרי הצל בא מחמת הסוכה.","\u0003ממאי\u0004 \u0005[ממה]\u0006 לומד הוא דבר זה — \u0003מדקתני\u0004 \u0005[ממה ששנינו]\u0006 בדברי המשנה: \u0003\"כאילו עשאה בתוך הבית\",\u0004 ויש לשאול: \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 \u0003\"כאילו עשאה בתוך הבית\"? ליתני\u0004 \u0005[שישנה]\u0006 במישרין \u0003\"פסולה\"! אלא, הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אילן\u0004 פסול \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003בית, מה בית צלתו מרובה מחמתו, אף אילן צלתו מרובה מחמתו.\u0004","על שיטת רבא מקשים: הרי \u0003וכי\u0004 אף אם האילן \u0003חמתו מרובה מצלתו, מאי הוי\u0004 \u0005[מה היה נעשה]\u0006 בכך להכשיר את הסוכה שתחתיו? \u0003הא קא\u0004 \u0005[הרי]\u0006 \u0003מצטרף סכך פסול,\u0004 שהוא ענפי האילן שלא קצצם \u0003בהדי\u0004 \u0005[יחד עם]\u0006 ה\u0003סכך\u0004 ה\u0003כשר\u0004 והוא פוסל את סכך הסוכה הכשר! \u0003אמר רב פפא:\u0004 מדובר \u0003ב\u0004אופן \u0003שחבטן,\u0004 שהוריד את ענפי האילן למטה ועירב בתוכם את הסכך הכשר, שאין ענפי האילן ניכרים בפני עצמם כלל, וכיון שהרוב הוא סכך כשר — הרי זה כשר.","ושואלים \u0003אי בשחבטן\u0004 \u0005[אם]\u0006 \u0003מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר],\u0006 מה החידוש בכך, הלא הוא מובן מאליו! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003ניגזור היכא\u0004 (במקום) ש\u0003חבטן אטו היכא\u0004 \u0005[משום מקום]\u0006 ש\u0003לא חבטן, קא משמע לן דלא גזרינן\u0004 \u0005[השמיע לנו שאין אנו גוזרים]\u0006 במקרה זה.","ומקשים: \u0003הא נמי תנינא\u0004 \u0005[דבר זה גם כן שנינו\u0006 במשנה\u0005]\u0006 מפורשת: \u0003הדלה\u0004 (העלה ענפי צמחים מטפסים) \u0003עליה\u0004 על הסוכה, כגון: \u0003את הגפן ואת הדלעת ואת הקיסוס, וסיכך על גבן — פסולה\u0004 שהרי סכך המחובר לאדמה פסול, \u0003ואם היה סיכוך הרבה מהן או שקצצן\u0004 לאותם ענפים מודלים — \u0003כשרה.\u0004","ומעתה נברר באותה משנה \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה]\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר באופן \u0003שלא חבטן, הא קא\u0004 \u0005[הרי]\u0006 \u0003מצטרף\u0004 על ידי כך \u0003סכך פסול עם סכך כשר,\u0004 ובאופן כזה ודאי שהסוכה פסולה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר שם \u0003כשחבטן, ושמע מינה דלא גזרינן\u0004 \u0005[ולמד מכאן שאין אנו גוזרים]?\u0006 ואם כן מפורש הדבר כבר לפני רבא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בדיעבד,\u0004 כלומר: אם כבר עשה כך — אינה פסולה, \u0003אבל לכתחילה לא\u0004 יעשה כן, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבא שסוכה כזו כשירה אפילו לכתחילה.","שנינו במשנה כי אם עשה \u0003סוכה על גבי סוכה\u0004 — הסוכה העליונה כשרה והתחתונה פסולה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא; נאמר: \u0003\"בסכת תשבו\"\u0004 (ויקרא כג, מב), ללמד: \u0003ולא בסוכה שתחת הסוכה, ולא בסוכה שתחת האילן, ולא בסוכה שבתוך הבית.\u0004","ומקשים: מה לימוד הוא זה, \u0003אדרבה, \"בסכת\" תרתי\u0004 \u0005[שתים]\u0006 \u0003משמע,\u0004 והיינו צריכים לומר להיפך; שאדרבא, בסוכה על גבי סוכה מתקיים הפסוק כצורתו! \u0003אמר רב נחמן בר יצחק: \"בסכת\"\u0004 חסר \u0003כתיב\u0004 \u0005[נאמר],\u0006 ולפי משמעות הכתיב מדובר בסוכה אחת דווקא.","\u0003אמר ר' ירמיה: פעמים ששתיהן,\u0004 שתי הסוכות שנעשו האחת מעל השניה \u0003כשירות, פעמים ששתיהן פסולות, פעמים ש\u0004ה\u0003תחתונה כשרה והעליונה פסולה, פעמים ש\u0004ה\u0003תחתונה פסולה, והעליונה כשרה.\u0004","ומפרטים: \u0003פעמים ששתיהן כשירות היכי דמי\u0004 \u0005[כיצד הוא]?\u0006 \u0003כגון ש\u0004הסוכה ה\u0003תחתונה חמתה מרובה מצלתה\u0004 ואם כן אינה כשרה לסוכה, \u0003והעליונה צלתה מרובה מחמתה\u0004 ויש לה הכשר סוכה, \u0003וקיימא\u0004 \u0005[ועומדת]\u0006 הסוכה ה\u0003עליונה בתוך עשרים\u0004 אמה מעל הקרקע, ונמצא שסכך הסוכה העליונה מועיל גם לעצמה וגם לסוכה התחתונה.","\u0003פעמים ששתיהן פסולות היכי דמי\u0004 \u0005[כיצד הוא]?\u0006 \u0003כגון דתרוייהו\u0004 \u0005[ששתיהן]\u0006 \u0003צלתן מרובה מחמתן וקיימא\u0004 \u0005[ועומדת]\u0006 \u0003העליונה למעלה מעשרים אמה\u0004 ובשל כך הריהי פסולה, ומתוך שהסכך שלה שהוא סכך פסול, מאפיל על הסוכה התחתונה, לכך אף היא נפסלת.","\u0003פעמים ש\u0004ה\u0003תחתונה כשרה והעליונה פסולה\u0004"],["\u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]?\u0006 \u0003כגון ש\u0004הסוכה \u0003התחתונה צלתה מרובה מחמתה\u0004 ובשל כך סוכה כשרה היא, \u0003ו\u0004ה\u0003עליונה חמתה מרובה מצלתה\u0004 ולכן אינה נחשבת וכאילו אינה, \u0003וקיימי תרוייהו\u0004 \u0005[מצויות שתיהן]\u0006 גם העליונה \u0003בתוך עשרים\u0004 אמה לארץ.","\u0003ופעמים שהעליונה כשרה ו\u0004ה\u0003תחתונה פסולה היכי דמי\u0004 \u0005[כיצד הוא]?\u0006 \u0003כגון דתרוייהו\u0004 \u0005[ששתיהן]\u0006 \u0003צלתן מרובה מחמתן, וקיימא\u0004 \u0005[ומצויה]\u0006 הסוכה ה\u0003עליונה בתוך עשרים.\u0004 שאז הסוכה העליונה היא סוכה כשרה לכל דבר, והתחתונה הריהי סוכה מתחת לסוכה ופסולה.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי לא נתחדש לנו דבר על ידי פרטים אלה! ומשיבים: המקרה שבו ה\u0003תחתונה כשרה ו\u0004ה\u0003עליונה פסולה איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, כי יש בו חידוש. \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]:\u0006 \u0003נגזר דלמא\u0004 \u0005[נגזור שמא]\u0006 \u0003מצטרף סכך פסול\u0004 של סוכה עליונה \u0003בהדי\u0004 \u0005[ביחד]\u0006 עם \u0003סכך כשר\u0004 של סוכה תחתונה ויפסול גם אותה, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו מצטרף ואינו פוסל.","לעיקר ההלכה הזו מבררים: \u0003כמה\u0004 רווח \u0003יהא בין סוכה לסוכה,\u0004 כלומר: בין סכך לסכך \u0003ותהא\u0004 הסוכה ה\u0003תחתונה\u0004 נחשבת כסוכה בפני עצמה ובשל כך תהא \u0003פסולה\u0004 משום סוכה תחת סוכה?","\u0003אמר רב הונא:\u0004 כדי רווח \u0003טפח, שכן מצינו באהלי טומאה טפח,\u0004 שחלל טפח מחשיב מקום להיות אהל לענין דיני טומאת המת. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 חלל פנוי של \u0003טפח על טפח ברום טפח,\u0004 הריהו \u0003מביא את הטומאה\u0004 שאם היתה בו טומאה (כגון אבר מן המת), הרי היא מתפשטת בכל המקומות הפתוחים לחלל זה. ואף \u0003חוצץ בפני הטומאה,\u0004 שאם היתה טומאת מת בתוך חלל סגור שמידתו טפח על טפח ברום טפח, אין הטומאה בוקעת החוצה. \u0003אבל פחות מרום טפח לא מביא\u0004 את הטומאה למקומות הפתוחים לחלל זה ואין מה שבתוכם נטמא, \u0003ולא חוצץ,\u0004 בחלל קטן כזה אינה מתפשטת תחת כולו, אלא בוקעת ועולה כאילו לא היה המקום סתום.","\u0003ורב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[אומרים]:\u0006 כדי שתחשב סוכה מעל סוכה צריך שיהא החלל ביניהן \u0003ארבעה\u0004 טפחים, \u0003שלא מצינו מקום חשוב\u0004 שיהא \u0003פחות מארבעה\u0004 טפחים, כגון לרשויות שבת.","\u0003ושמואל אמר:\u0004 החלל שבין הסוכות צריך להיות בן \u0003עשרה\u0004 טפחים. ומסבירים \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003שמואל\u0004 — \u0003כהכשרה כך פסולה; מה הכשרה\u0004 שתחשב סוכה צריכה להיות לפחות \u0003בעשרה\u0004 טפחים, \u0003אף פסולה בעשרה.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: אם אין דיורין\u0004 (דיירים) \u0003ב\u0004סוכה ה\u0003עליונה\u0004 — \u0003התחתונה כשרה.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין דיורין? אילימא\u0004 \u0005[אם נאמר]\u0006 שהכוונה היא \u0003דיורין ממש,\u0004 הרי יש לשאול: \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003דיורין קא גרמי\u0004 \u0005[גורמים]?\u0006 שאם סוכה היא זו העליונה, אין הבדל אם יש או אין שם דיירים! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003אין דיורין — כל שאינה ראויה לדירה, והיכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 ש\u0003לא גבוה עשרה,\u0004 שהרי אמרנו שבפחות מזו אינו ראוי לדירה. וכיון שר' יהודה הוא המחלק בין גבוהה עשרה לשאינה גבוהה עשרה, \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי \u0003אף על פי שאינה ראויה לדירה\u0004 בכל זאת \u0003פסולה,\u0004 וקשה איפוא לשמואל משיטת תנא קמא.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 ומפרשים כך את דברי המשנה: \u0003אם אין\u0004 הסוכה \u0003התחתונה\u0004 חזקה דיה כדי שתהא \u0003יכולה לקבל\u0004 (להחזיק) על גבי הסכך \u0003כרים וכסתות של\u0004 ה\u0003עליונה\u0004 הרי \u0003התחתונה כשרה,\u0004 שהרי העליונה אינה ראויה לדירה כשלעצמה. ואם כן אין כאן כל פסיקה ביחס לגודל החלל, אלא לטיב הסכך.","ומעירים: \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי \u0003אף על פי שאינה ראויה לקבל פסולה?\u0004 והרי אין הסוכה העליונה ראויה כלל לדירה!","ומשיבים: גם תנא קמא סבר כן, אלא \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 במקרה ש\u0003יכולה\u0004 הסוכה התחתונה \u0003לקבל\u0004 על גבי סככה את הכרים והכסתות של העליונה \u0003על ידי הדחק,\u0004 ואולם רק בדוחק, שיש לחשוש שמא תתמוטט התחתונה מחמת הכרים והכסתות, שלשיטת תנא קמא כיון שיכולה לקבל בדוחק יש בכך כדי להחשיב את העליונה כסוכה כשרה ובכך לפסול את התחתונה. ולשיטת ר' יהודה, כיון שאינה יכולה לקבל אלא על ידי הדחק, אין בכך כדי להחשיב את העליונה כסוכה כשרה ולכן התחתונה כשרה.","\u0003פירס עליה\u0004 על סכך הסוכה \u0003סדין מפני החמה\u0004 שלא יהא חם כל כך בסוכה, ויוכלו לשהות בתוכה. \u0003או\u0004 שפירס את הסדין \u0003תחתיה\u0004 (תחת הסכך) \u0003מפני הנשר\u0004 (העלים הנושרים מן הסכך), שלא יפריעו ליושבים בסוכה, \u0003או שפירס\u0004 סדין \u0003על גבי הקינוף\u0004 (מערכת מוטות בולטים העולים מארבעת פינות המיטה) שישן בה, ועשה כמין כילה — \u0003פסולה.\u0004 שסדין הוא דבר המקבל טומאה ופוסל את הסוכה. \u0003אבל פורס הוא על גבי נקליטי המטה\u0004 שהנקליטים הם רק שניים וקבועים באמצע המיטה, האחד לראשה והשני למראשותיה, ומשפורסים סדין על גביהם נוצרת בכך כילה משופעת כדמות אהל שאין לו גג מלמעלה, ואינו נחשב כבנין חשוב.","\u0003אמר רב חסדא: לא שנו\u0004 שפסולה \u0003אלא\u0004 כאשר פרס את הסדין כסכך להגן על יושבי הסוכה \u0003מפני הנשר. אבל\u0004 אם פרס סדין בסוכה וכל מטרתו היתה רק \u0003לנאותה\u0004 (ליפותה) — אין שם סכך עליו, ו\u0003כשרה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו, הלא \u0003מפני הנשר תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הוא הדין\u0004 ש\u0003אפילו\u0004 אם הניחם כדי \u0003לנאותה\u0004 פסולה היא, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003מפני הנשר — אורחא דמילתא קתני\u0004 \u0005[דרך הדברים,\u0006 דוגמה רגילה, \u0005שנה]\u0006 שכרגיל פורסים סדין לצורך זה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהמשנה מדוייקת בלשונה, ואם הניח לנוי אינו פוסל.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 מה ששנינו בברייתא בענין הסוכה: \u0003סיככה כהלכתה ועיטרה בקרמין\u0004 (אריגים המצויירים תוך כדי אריגתם) או \u0003בסדינין המצוירין\u0004 (אריגים רקומים), \u0003ותלה בה\u0004 לנוי \u0003אגוזין שקדים אפרסקין ורמונים, פרכילי\u0004 (ענפי) \u0003ענבים ועטרות של שבולין, יינות\u0004 ו\u0003שמנים\u0004 הנתונים בתוך בקבוקי זכוכית \u0003וסלתות\u0004 — כל אלה \u0003אסור להסתפק\u0004 (ליהנות ולהשתמש) \u0003מהן.\u0004"],["\u0003עד מוצאי יום טוב האחרון של חג\u0004 לפי שהוקצו למצות סוכה בלבד. \u0003ואם התנה עליהם\u0004 שכוונתו להשתמש בהם גם בתוך ימי החג לצורכו — \u0003הכל לפי תנאו.\u0004 הרי שלצורך נוי הסוכה פורסים בסוכה סדינים! ודוחים: משם אין ראיה, \u0003דלמא\u0004 \u0005[שמא]\u0006 כוונת הברייתא שפרס את האריגים \u0003מן הצד,\u0004 אבל אם פרוסים תחת הסכך — הרי הם פוסלים את הסוכה.","לענין נוי סוכה, \u0003אתמר\u0004 \u0005[נאמר]\u0006 שאמרו חכמים: \u0003נויי סוכה אין ממעטין בסוכה,\u0004 שחפצים התלויים בה לנוי ולקישוט אינם נחשבים כחלק מבניינה שיהיו משיעורה של הסוכה, ואם גבוהה הסוכה מעשרים אמה ימעטו הם מגובהה ויכשירוה. \u0003אמר רב אשי:\u0004 ואם פרוסים הם \u0003מן הצד\u0004 — בניגוד לענין גובה הסוכה — הרי אלה \u0003ממעטין\u0004 משטחה, ואם בשלהם מתמעטת הסוכה משיעור שבעה טפחים — הריהי פסולה.","מסופר: \u0003מנימין עבדיה\u0004 \u0005[עבדו]\u0006 של \u0003רב אשי איטמישא ליה כתונתא במיא ואשטחתא אמטללתא\u0004 \u0005[נרטבה לו כתונת במים ושטחה על הסוכה]\u0006 כדי שתתייבש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: דלייה\u0004 \u0005[הורד אותה],\u0006 כדי ש\u0003לא לימרו\u0004 \u0005[יאמרו]\u0006 אנשים \u0003קא מסככי\u0004 \u0005[הם מסככים]\u0006 \u0003בדבר המקבל טומאה\u0004 ככתונת. אמר לו העבד: \u0003והא קא חזו ליה דרטיבא\u0004 \u0005[הרי רואים אותה ש\u0006היא \u0005רטובה]\u0006 ומבינים שרק להתייבש נתנוה שם! ענה לו: \u0003לכי יבשה קא אמינא לך\u0004 \u0005[לכאשר תתייבש אמרתי לך]\u0006 שתורידנה, שאז עלולים לחשוב שהיא חלק מן הסכך.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה של \u0003נויי סוכה,\u0004 כגון סדינים הפרושים תחת הסכך לנוי, \u0003המופלגין\u0004 (הרחוקים) \u0003ממנה\u0004 (מן הסכך) \u0003ארבעה\u0004 טפחים, האם נחשבים הם כחציצה מתחת לסכך. \u0003רב נחמן אמר:\u0004 סוכה כזו \u0003כשרה, רב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003פסולה.\u0004","מסופר: \u0003רב חסדא ורבה בר רב הונא איקלעו לבי ריש גלותא\u0004 \u0005[הזדמנו לבית ראש הגולה]\u0006 \u0003אגנינהו\u0004 \u0005[השכיבם\u0006 ללון\u0005]\u0006 \u0003רב נחמן\u0004 שהיה הממונה בבית ראש הגולה \u0003בסוכה שנוייה מופלגין ממנה ארבעה טפחים, אשתיקו\u0004 \u0005[שתקו]\u0006 חכמים אלה \u0003ולא אמרו ליה ולא מידי\u0004 \u0005[אמרו לו דבר]\u0006 אף שלדעתם סוכה כזו פסולה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הדור בהו רבנן משמעתייהו\u0004 \u0005[\u0006האם \u0005חזרו בהם חכמים מהלכתם]?\u0006 כלומר: האם יש לי ללמוד משתיקתכם כי חזרתם בכם מדבריכם? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003שלוחי מצוה אנן\u0004 \u0005[אנו]\u0006 ולכן \u0003פטורין\u0004 אנו \u0003מן הסוכה,\u0004 ומותר לנו איפוא לישון בסוכה זו אף שאינה כשרה, שכן שלוחי מצוה פטורים בכלל ממצות סוכה, אבל לעצם ההלכה אכן לא חזרנו בנו.","\u0003אמר רב יהודה אמר שמואל: מותר לישון בכילה בסוכה אף על פי שיש לה\u0004 לכילה \u0003גג, והוא שאינה גבוהה עשרה\u0004 טפחים מן המיטה, שבפחות מעשרה אינה נחשבת כאהל לעצמו.","ומציעים: \u0003תא שמע\u0004 \u0005[בא שמע]:\u0006 \u0003הישן בכילה בסוכה\u0004 — \u0003לא יצא ידי חובתו,\u0004 היפך דברי רב יהודה בשם שמואל! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003כש\u0004הכילה \u0003גבוהה עשרה\u0004 טפחים ונחשבת כאהל.","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 הרי שנינו במשנה: \u0003הישן תחת המטה בסוכה לא יצא ידי חובתו!\u0004 והלא גובהה של מיטה רגילה בדרך כלל אינו מגיע לעשרה טפחים, הרי שאף בפחות מעשרה טפחים הרי זה פוסל! ומשיבים: \u0003הא תרגמה\u0004 \u0005[הרי הסביר אותה]\u0006 \u0003שמואל\u0004 שמדובר \u0003במטה\u0004 שהיתה \u0003גבוהה עשרה\u0004 טפחים, ולכן דינה כאהל בתוך הסוכה, ולכך הישן בה לא יצא ידי חובת סוכה.","\u0003תא שמע\u0004 \u0005[בא שמע]\u0006 ממה ששנינו: \u0003או שפירס על גבי קינופות\u0004 — \u0003פסולה,\u0004 משמע שבכילה מסוג מסויים פסולה הסוכה! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר \u0003דגביהי\u0004 \u0005[שגבוהים]\u0006 המוטות \u0003עשרה\u0004 טפחים.","ומקשים: \u0003והא לא קתני הכי\u0004 \u0005[והרי לא שנינו כך]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נקליטין שנים, וקינופות ארבעה. פירס על גבי קינופות — פסולה, על גבי נקליטין — כשרה, ובלבד שלא יהיו\u0004 ה\u0003נקליטין גבוהין מן המטה עשרה.\u0004 ונדייק: \u0003מכלל\u0004 הדברים אתה למד ש\u0003קינופות\u0004 אסורים \u0003אף על פי שאין גבוהין עשרה!\u0004","ומשיבים: \u0003שאני\u0004 \u0005[שונים]\u0006 ה\u0003קינופות דקביעי\u0004 \u0005[שהם קבועים]\u0006 ודבר קבוע, אפילו אין גובהו עשרה, הריהו יוצר מקום בפני עצמו. אבל מוטות וכילה שאינה קבועה עד גובה עשרה אינם פוסלים בסוכה. ומקשים: \u0003והרי סוכה על גבי סוכה דקביעא\u0004 \u0005[שהיא קבועה],\u0006 \u0003ואמר שמואל: כהכשרה כך פסולה,\u0004 צריך שיהא בה חלל עשרה! \u0003אמרי\u0004 \u0005[אומרים,\u0006 מסבירים\u0005]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בסוכה על גבי סוכה שהוא כדי \u0003למפסל\u0004 \u0005[לפסול]\u0006 את ה\u0003סוכה\u0004 שתחתיה \u0003— בעשרה\u0004 טפחים נחשבת העליונה לעצמה כדי שתוכל לפסול, אבל בפחות לא. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003דלשויי אוהלא\u0004 \u0005[שכדי לעשותה\u0006 ולהחשיבה \u0005לאהל]\u0006 לעצמו הוא — \u0003בציר\u0004 \u0005[בפחות]\u0006 \u0003מעשרה\u0004 טפחים \u0003נמי הוי אוהלא\u0004 \u0005[גם כן הריהי\u0006 נחשבת \u0005לאהל]\u0006 אם קבוע הוא.","\u0003אמר רב תחליפא בר אבימי אמר שמואל: הישן בכילה\u0004 כשהוא \u0003ערום\u0004 וצריך לקרוא קריאת שמע — \u0003מוציא ראשו חוץ לכילה וקורא קריאת שמע,\u0004 שהכילה נחשבת כבגד על גופו, ונמצא כאילו כולו לבוש בכילה ומותר לו לקרות קריאת שמע, אף על פי שהוא ערום.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 והרי נאמר בברייתא: \u0003הישן בכילה ערום\u0004 — \u0003לא יוציא ראשו חוץ לכילה ויקרא קריאת שמע!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 שאמרנו שאין הכילה מועילה לזה \u0005במה אנו עוסקים]\u0006 — \u0003כשגבוהה\u0004 אותה כילה \u0003עשרה\u0004 טפחים וכיון שכן הרי היא נחשבת כאהל ולא כלבוש.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 בהבנת הדברים, \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה בסופה]\u0006 של אותה ברייתא: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למה זה דומה — לעומד בבית ערום, שלא יוציא ראשו חוץ לחלון ויקרא קריאת שמע,\u0004 שודאי אין זה מועיל. ומשמע שמדובר בכילה הדומה לבית. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא."],["\u0003ובית נמי\u0004 \u0005[גם כן]\u0006 לענין קריאת שמע \u0003אף על פי שאין\u0004 הוא \u0003גבוה עשרה\u0004 טפחים, \u0003כיון דקביע\u0004 \u0005[ש\u0006הוא \u0005קבוע] —\u0006 \u0003אוהלא\u0004 \u0005[אהל]\u0006 \u0003הוא דלא גרע\u0004 \u0005[שאינו גרוע]\u0006 \u0003מקינופות,\u0004 שאף קינופות קבועים, אפילו בפחות מעשרה, מהווים אהל.","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[לשון אחרת אומרים אותה]\u0006 את ההלכה ש\u0003אמר רב יהודה אמר שמואל: מותר לישן בכילת חתנים בסוכה לפי שאין לה גג,\u0004 אלא היא משופעת מכל צידיה, \u0003אף על פי\u0004 שהיא \u0003גבוהה עשרה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003הישן בכילה בסוכה\u0004 — \u0003לא יצא ידי חובתו!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשיש לה\u0004 לכילה זו \u0003גג\u0004 ואינה עשויה ככילת חתנים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה אחרת, ממה ששנינו: \u0003נקליטין שנים\u0004 הן, \u0003וקינופות ארבעה, פירס\u0004 סדין \u0003על גבי קינופות\u0004 המיטה שבסוכה — \u0003פסולה\u0004 שהרי בכך הוא עושה גג ממש החוצץ בינו לבין הסכך, ואם פרס \u0003על גבי נקליטין,\u0004 כיון שהם רק שנים והסדין הפרוס על גביהם משופע לשני צידיו ואין לו גג — \u0003כשרה, ובלבד שלא יהו\u0004 ה\u0003נקליטין גבוהין מן המטה עשרה טפחים.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003גבוהין מן המטה עשרה\u0004 הריהי \u0003פסולה, אף על פי שאין לה גג,\u0004 היפך דברי שמואל!","ומשיבים: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003נקליטין דקביעי\u0004 \u0005[ש\u0006הם \u0005קבועים]\u0006 במיטה, וכיון שהם קבועים במיטה הרי הם יוצרים אהל אף על פי שאין לו גג. ומקשים: \u0003אי קביעי, להוי\u0004 \u0005[אם קבועים\u0006 הם, \u0005שיהיו\u0006 שייחשבו\u0005]\u0006 \u0003כקינופות,\u0004 ואף בפחות מעשרה יפסלו! ומשיבים: בהשואה \u0003לגבי קינופות לא קביעי\u0004 \u0005[אינם\u0006 נחשבים כ\u0005קבועים],\u0006 ולכן אינם פוסלים בפחות מעשרה, אבל \u0003לגבי כילה קביעי\u0004 \u0005[\u0006נחשבים הם כ\u0005קבועים]\u0006 ופוסלים אפילו בפחות מעשרה, אף על פי שבכגון זה אין הכילה פוסלת.","\u0003דרש רבה בר רב הונא: מותר לישן בכילה אף על פי שיש לה גג,\u0004 ו\u0003אף על פי שגבוהה עשרה. כמאן\u0004 \u0005[כמי],\u0006 כשיטת מי אמר זאת — \u0003כר' יהודה,\u0004 ש\u0003אמר:\u0004 בכלל \u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003אהל ארעי ומבטל אהל קבע,\u0004 והכל הולך לפי הבנין הקבוע. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005];\u0006 \u0003אמר ר' יהודה: נוהגין היינו לישן תחת המטה בפני הזקנים,\u0004 שכיון שהמיטה נחשבת כאהל ארעי לגבי סוכה, אין היא מבטלת את האהל הקבוע, שהוא הסוכה עצמה.","ושואלים: אם דעת רבה בר רב הונא ממש כדברי ר' יהודה, \u0003לימא\u0004 \u0005[שיאמר]\u0006 איפוא רק כי \u0003הלכה כ\u0004שיטת \u0003ר' יהודה!\u0004","ומשיבים: \u0003אי אמר\u0004 \u0005[אם\u0006 היה \u0005אומר]\u0006 \u0003הלכה כר' יהודה הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים לענין \u0003מטה,\u0004 שלצורך \u0003גבה\u0004 היא \u0003עשויה,\u0004 שאפשר לומר שאין המיטה נחשבת כאהל מטעם אחר, משום שעשייתה היא כדי לשכב על גבה ולא כדי להשתמש במקום שמתחתיה, \u0003אבל כילה\u0004 שלצורך \u0003תוכה\u0004 היא \u0003עשויה אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נפקע ממנה שם אהל ואף על פי שאינה אלא אהל ארעי, על כל פנים תפסול, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003טעמא\u0004 \u0005[טעם]\u0006 של \u0003ר' יהודה\u0004 הוא בעיקר משום שסבור הוא ש\u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003אהל ארעי ומבטל אהל קבע,\u0004 ולכן \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היתה זו \u0003מטה ולא שנא\u0004 \u0005[שונה]\u0006 אם היתה זו \u0003כילה.\u0004","\u0003הדלה עליה\u0004 (על הסוכה) \u0003את הגפן ואת הדלעת ואת הקיסוס\u0004 שהם מטפסים וענפיהם מתפשטים הרבה \u0003וסיכך\u0004 על ידי כך \u0003על גבה\u0004 בעודם מחוברים לקרקע — \u0003פסולה. ואם היה סיכוך\u0004 הכשר \u0003הרבה מהן\u0004 מענפיהם של צמחים אלו, \u0003או שקצצן\u0004 את הענפים ושוב אינם מחוברים לקרקע — \u0003כשרה.\u0004","ונוסף לפסול זה של סכוך בדברים המחוברים לקרקע, \u0003זה הכלל\u0004 בסכך: \u0003כל\u0004 דבר \u0003שהוא מקבל טומאה\u0004 (כגון כלים) או דבר \u0003שאין גידולו מן הארץ\u0004 (כגון עורות) — \u0003אין מסככין בו. וכל דבר שאינו מקבל טומאה וגידולו\u0004 בעיקרו \u0003מן הארץ — מסככין בו.\u0004","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא ויתיב וקאמר\u0004 \u0005[וישב ואמר]\u0006 מה ששנינו במשנתנו; \u0003\"או שקצצן\u0004 — \u0003כשרה\", ואמר רב:\u0004 אין די בקציצה בלבד אלא עדיין \u0003צריך לנענע\u0004 את הענפים הללו, כדי לעשות בהם מעשה שיכשירם לשמש כסכך כשר. ואם לא עשה כן הריהו פסול מטעם \"תעשה\" ולא מן העשוי. שהרי לא סיכך בהם לאחר שנקצצו, אלא לפני כן, ומשקצצם הרי הסוכה כמסוככת מאליה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא\u0004 לר' יוסף: \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 \u0003שמואל אמרה. אהדרינהו\u0004 \u0005[החזירם]\u0006 \u0003רב יוסף לאפיה\u0004 \u0005[את פניו]\u0006 ברוגז \u0003ואמר ליה\u0004 \u0005[לו]\u0006 לרב הונא: \u0003אטו מי קאמינא לך\u0004 \u0005[וכי אמרתי לך]\u0006 ש\u0003לא אמרה שמואל? אמרה רב, ואמרה\u0004 גם \u0003שמואל\u0004 ומדוע איפוא מעיר אתה לי על כך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא: הכי קאמינא לך\u0004 \u0005[כך אני אומר לך]\u0006 ש\u0003שמואל\u0004 בלבד \u0003אמרה ולא רב,\u0004 ואכן רב אינו סבור כן, ש\u0003רב אכשורי מכשר\u0004 \u0005[מכשיר]\u0006 ולדעתו די בקציצה לחוד ואין כל צורך בנענוע נוסף. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 של \u0003רב עמרם חסידא\u0004 \u0005[החסיד],\u0006 \u0003רמא תכלתא לפרזומא דאינשי ביתיה\u0004 \u0005[תלה ציציות לבגד של אנשי ביתו]\u0006 \u0003תלאן\u0004 לציציות הללו בבגד וקשרן, אבל \u0003לא פסק\u0004 (חתך) את \u0003ראשי חוטין שלהן,\u0004 שלא היו כל החוטים מופרדים זה מזה, ונסתפק אם יהיו הציציות כשרות לאחר שיחתוך את החוטים, אף שלא עשה כן בשעתו.","\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חייא בר אשי\u0004 לשאול אותו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: מפסקן\u0004 (חותכן) כדי להפרידן \u0003והן כשרין\u0004 ואין צורך לתלותן מלכתחילה כראוי. \u0003אלמא\u0004 \u0005[מכאן]\u0006 אתה למד כי \u0003פסיקתן זו היא עשייתן,\u0004 שלדעת רב מרגע שחתך אותן נעשו ציציות כדינן, ואין צריכות עשיה לשמה מתחילה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בסוכה, לפי אותה שיטה, \u0003קציצתן זו היא עשייתן\u0004 ואין צורך לשיטה זו במעשה נוסף כדי להכשירן.","ושואלים: \u0003ו\u0004כי \u0003סבר שמואל\u0004 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003פסיקתן זו היא עשייתן? והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003שמואל משום\u0004 \u0005[משמו]\u0006 של \u0003ר' חייא: הטיל\u0004 ציציות \u0003לשני קרנות\u0004 לשתי זויות של הטלית \u0003בבת אחת\u0004 שהכניס בנקבים אותו חוט וחזר והכניסו, \u0003ואחר כך פסק ראשי חוטין שלהן\u0004 ונמצאו שם שתי ציציות גמורות — \u0003כשרין. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003שקושר\u0004 תחילה את הציציות בקרנות כהלכתן \u0003ואחר כך פוסק\u0004 את החוטים! ומשיבים: \u0003לא,\u0004 הכוונה היא \u0003שפוסק\u0004 את החוטין תחילה \u0003ואחר כך קושר.\u0004","ותוהים: \u0003פוסק ואחר כך קושר מאי למימרא\u0004 \u0005[מה יש לומר]\u0006 שאם כך עשה מה החידוש בדבר, שהרי כל מצות ציצית אינה אלא בקשירה, והרי לפי הסבר זה עשה את הקשירה כשהיו הציציות מופרדות כהלכה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006"],["\u0003בעינן\u0004 \u0005[צריכים]\u0006 שיהא \u0003כנף\u0004 אחד \u0003בשעת פתיל,\u0004 כלומר: בשעה שפותל את הפתילים \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהלא פותל הוא לשני כנפות גם יחד, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לזה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא: \u0003תלאן\u0004 את חוטי הציציות כשהם מחוברים \u0003ולא פסק ראשי חוטין שלהן — פסולין. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שהם \u0003פסולין לעולם, ותיובתא\u0004 \u0005[ו\u0006הרי זו \u0005קושיא\u0006 חמורה\u0005]\u0006 על דעת \u0003רב!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך רב: מאי\u0004 \u0005[מה פירוש]\u0006 \u0003פסולין\u0004 ששנינו — \u0003פסולין עד שיפסקו,\u0004 אבל לא לעולם. \u0003ושמואל אמר:\u0004 הכוונה היא \u0003פסולין לעולם. וכן אמר לוי: פסולין לעולם. וכן אמר רב מתנה אמר שמואל: פסולין לעולם.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שכך \u0003אמר רב מתנה: בדידי הוה עובדא\u0004 \u0005[בי היה מעשה]\u0006 בציציות כגון אלה, \u0003ואתאי לקמיה\u0004 \u0005[ובאתי לפני]\u0006 \u0003מר שמואל\u0004 לשאול, \u0003ואמר לי: פסולין לעולם.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד לרב ממה ששנינו בברייתא אחרת: \u0003תלאן ואחר כך פסק ראשי חוטין שלהן — פסולין. ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003גבי סוכה;\u0004 נאמר: \"חג הסוכות \u0003תעשה\u0004 לך\" (דברים טז, יג), ולמדו חכמים מלשון הכתוב כלל זה: \"תעשה\" — \u0003ולא מן העשוי. מכאן אמרו\u0004 חכמים: \u0003הדלה עליה\u0004 על הסוכה \u0003את הגפן ואת הדלעת ואת הקיסוס וסיכך על גבן — פסולה.\u0004","ותחילה נברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן \u0003בשלא קצצן\u0004 כלל, אם כן \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע נותן את הטעם \u0003משום\u0004 הכלל של \u0003\"תעשה ולא מן העשוי\"? תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו מטעם פשוט ש\u0003מחוברין נינהו\u0004 \u0005[הם]\u0006 עדיין לקרקע, ואין זה קרוי סכך! \u0003אלא\u0004 ודאי מדובר \u0003בשקצצן, וקתני\u0004 \u0005[ושנויה]\u0006 \u0003פסולה, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 \u0003דלא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 כי \u0003קציצתן זו היא עשייתן, ותיובתא\u0004 \u0005[ו\u0006הרי זו \u0005קושיא\u0006 חמורה\u0005]\u0006 על דעת \u0003רב!\u0004","\u0003אמר לך רב\u0004 \u0005[יכול היה רב לומר לך]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003דשלפינהו שלופי\u0004 \u0005[ש\u0006רק \u0005שלף אותם],\u0006 כלומר: שלא קצץ את הענפים כרגיל, אלא משך אותם עד שניתקו ממקום חיבורם, \u0003דלא מינכרא עשיה דידהו\u0004 \u0005[שאין ניכרת העשייה שלהם]\u0006 וכיון שלא עשה בהם מעשה הניכר לעין, אין בכך כדי להכשירם. ושואלים: \u0003מכל מקום\u0004 ממה ששנינו בענין ציציות אשר \u0003תלאן ואחר כך פסק, קשיא\u0004 \u0005[קשה]\u0006 לדברי \u0003רב!\u0004 ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שמחלוקת \u0005תנאים]\u0006 בדבר. כי הדס שהיו בו פירות שחורים מרובים מעליו — פסול מלשמש למצות ארבעה מינים, ואם מיעט את פירותיו — כשר. אבל ביום טוב אסור לעשות כן. ואם \u0003עבר וליקטן\u0004 את פירות ההדס ביום טוב עצמו — הריהו \u0003פסול,\u0004 אלו \u0003דברי ר' שמעון בן יהוצדק. וחכמים מכשירין.\u0004","ומעתה מסבירים את הבסיס להצעת הדברים, \u0003סברוה\u0004 \u0005[סבורים היו]\u0006 בני הישיבה כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לולב צריך אגד,\u0004 שחובה מן התורה היא לאגוד את שלושת המינים יחד, ושייך איפוא שתהא בכך עשייה. וכן סברו כי \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 להלכה דין \u0003לולב\u0004 מדין \u0003סוכה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003גבי סוכה\u0004 לשון \u0003\"תעשה\"\u0004 ולמדו מכך חכמים: \u0003ולא מן העשוי.\u0004","ולפי הנחות מוקדמות אלה \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא\u0006 בדבר \u0005זה נחלקו]\u0006 \u0003דמאן דמכשיר\u0004 \u0005[שמי שמכשיר,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003גבי סוכה\u0004 שסיככוה מן המחובר לקרקע ש\u0003קציצתן\u0004 של הענפים המחוברים \u0003זו היא עשייתן. וגבי לולב נמי אמרינן\u0004 \u0005[גם כן אומרים אנו]\u0006 כי \u0003לקיטתן\u0004 של הפירות מתוך ההדס \u0003זו היא עשייתן\u0004 ואין צורך במעשה נוסף כדי להכשירן. \u0003ומאן דפסיל\u0004 \u0005[ומי שפוסל]\u0006 \u0003סבר\u0004 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003לגבי סוכה קציצתן זו היא עשייתן\u0004 וצריך לעשות בנוסף לקציצה מעשה מיוחד לצורך זה, \u0003וגבי לולב נמי לא אמרינן\u0004 \u0005[גם כן אין אנו אומרים]\u0006 כי \u0003לקיטתן זו היא עשייתן\u0004 ולכן, כיון שלא היה ההדס ראוי למצוה זו קודם החג, וכבר נעשה בו מעשה של אגידה, הרי הלקיטה בלבד לא תכשירנו למצוותו, שכן הוא נחשב כבר כעשוי!","את ההסברה הזאת דוחים: \u0003לא, דכולי עלמא לא אמרינן\u0004 \u0005[לדעת הכל אין אומרים]\u0006 \u0003לגבי סוכה קציצתן זו היא עשייתן,\u0004 אולם \u0003והכא\u0004 \u0005[וכאן]\u0006 בהדס נחלקו בענין אחר \u0003במילף\u0004 \u0005[ב\u0006שאלה \u0005האם ללמוד]\u0006 \u0003לולב מסוכה קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 וכך יש להבין את המחלוקת: \u0003מאן דמכשר\u0004 \u0005[מי שמכשיר]\u0006 \u0003סבר\u0004 כי \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003לולב מסוכה,\u0004 ולכן לולב ומיניו, אין צריך שתהא בהם עשייה לשמה. \u0003ומאן דפסיל\u0004 \u0005[ומי שפוסל]\u0006 \u0003סבר\u0004 כי \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003לולב מסוכה.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאפשר לתת הסבר שונה על בסיס אחר למחלוקת. \u0003אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 ומקבלים את ההנחה ש\u0003לולב צריך אגד, כולי עלמא לא פליגי דילפינן\u0004 \u0005[הכל אינם חלוקים שלמדים אנו]\u0006 \u0003לולב מסוכה\u0004 וצריכים עשיה לשמה ושלא יהיה מן העשוי. \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בדבר זה נחלקו]\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' שמעון בן יהוצדק\u0005]\u0006 \u0003סבר\u0004 שלולב \u0003צריך אגד,\u0004 ולכן הוא פסול, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 כי לולב \u0003אין צריך אגד\u0004 ולשיטה זו, כיון שאין מעשה של ממש בהכנת ההדס למצוה, בכל עת שיוכשר למצוה — הריהו ראוי וכשר למצוותו. \u0003ובפלוגתא דהני תנאי\u0004 \u0005[במחלוקתם של תנאים אלה]\u0006 שדנו בכך במפורש, תהא מחלוקת זו תלויה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לולב, בין אגוד\u0004 (כלומר: שכל המינים אגודים זה בזה), \u0003בין שאינו אגוד\u0004 — \u0003כשר. ר' יהודה אומר: אגוד — כשר, שאינו אגוד — פסול.\u0004","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה,\u0004 מניין למד מצוה זו שאינה כתובה בתורה? ומסבירים: \u0003יליף\u0004 \u0005[למד]\u0006 זאת בגזירה שווה \u0003\"לקיחה\" \"לקיחה\" מאגודת אזוב. כתיב התם\u0004 \u0005[נאמר שם]\u0006 בפסח מצרים: \u0003\"ולקחתם אגדת אזוב\"\u0004 (שמות יב, כב) \u0003וכתיב הכא\u0004 \u0005[ונאמר כאן]\u0006 בסוכות: \u0003\"ולקחתם לכם ביום הראשון\u0004 פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל\u0003\"\u0004 (ויקרא כג, מ), \u0003מה להלן\u0004 בפסח, מדובר על לקיחה \u0003באגודה, אף כאן\u0004 בסוכות \u0003נמי\u0004 \u0005[גם כן]\u0006 לקיחה זו דווקא \u0003באגודה\u0004 היא. \u0003ורבנן\u0004 \u0005[חכמים]\u0006 סבורים כי \u0003\"לקיחה\" מ\"לקיחה\"\u0004 בגזירה שוה \u0003לא ילפינן\u0004 \u0005[אין אנו למדים].\u0006","ושואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת אותה\u0006 ברייתא \u0005ששנויה]:\u0006 \u0003לולב מצוה לאוגדו, ואם לא אגדו — כשר.\u0004 שהרי \u0003אי\u0004 \u0005[אם\u0006 תאמר\u0005]\u0006 שכשיטת \u0003ר' יהודה היא, כי\u0004 \u0005[כאשר]\u0006 \u0003לא אגדו אמאי\u0004 \u0005[מדוע]\u0006 יהיה \u0003כשר? ואי רבנן\u0004 \u0005[ואם\u0006 כשיטת \u0005חכמים]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מצוה\u0004 לאוגדו? ומשיבים: \u0003לעולם\u0004 עליך לפרש כי ברייתא זו כשיטת \u0003רבנן היא\u0004, ומדוע אוגדים אותו — \u0003משום שנאמר: \"זה אלי ואנוהו\"\u0004 (שמות טו, ב), ודרשוהו: \u0003התנאה לפניו במצות.\u0004 ואף חכמים מודים שנוי הוא למצות לולב כשכל המינים אגודים יחד, אף כי אין הדבר מעכב בעצם המצוה.","שנינו במשנה: \u0003זה הכלל כל דבר שמקבל טומאה\u0004 ושאין גידולו מן הארץ — פסול לסכך בו. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 בדבר מהות הסכך? \u0003אמר ריש לקיש; אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואד יעלה מן הארץ\u0004 והשקה את כל פני האדמה\u0003\"\u0004 (בראשית ב, ו), \u0003מה אד\u0004 (ענן) הוא \u0003דבר שאינו מקבל טומאה, וגידולו\u0004 (כלומר: יציאתו) \u0003מן הארץ, אף\u0004 סכך \u0003סוכה\u0004 צריך להיות \u0003דבר שאין מקבל טומאה וגידולו מן הארץ.\u0004 ומתוך שמצות סוכה היא זכר לענני כבוד שהקיפו את ישראל במדבר, לכך עליה להיות במהותה כעננים הללו.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שאותן סוכות האמורות במקרא (\"כי בסוכות הושבתי את בני ישראל\". ויקרא כג, מג) \u0003ענני כבוד היו,\u0004 אכן ראוי לנו ללמוד הלכות סוכה מעננים, ועל סכך הסוכה להיות כמו הענן. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003סוכות ממש עשו להם\u0004 בני ישראל במדבר, וכזכר להן עושים סוכות, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלא אין כל קשר בין הדברים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו תנאים בפירוש הכתוב. נאמר: \u0003\"כי בסכות הושבתי את בני ישראל\"\u0004 (ויקרא כג, מג), וסוכות אלו שנאמרו, \u0003ענני כבוד היו,\u0004 אלו \u0003דברי ר' אליעזר. ר' עקיבא אומר: סוכות ממש עשו להם.\u0004 אם כן \u0003הניחא\u0004 \u0005[זה\u0006 הפסוק שאמר ריש לקיש כהוכחה \u0005נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' אליעזר, אלא לר' עקיבא מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"חג הסכת תעשה לך\"\u0004 (דברים טז, יג), הביטוי \"חג הסוכות\" \u0003מקיש\u0004 (משוה) \u0003סוכה ל\u0004קרבן החג הקרוי \u0003חגיגה, מה\u0004 קרבן \u0003חגיגה דבר שאינו מקבל טומאה\u0004 (שהרי חי הוא) \u0003וגידולו מן הארץ\u0004 (שעיקר חיותן של הבהמות מאכילת הדברים הגדלים בקרקע) \u0003— אף סוכה דבר שאינו מקבל טומאה, וגידולו מן הארץ.\u0004"],["\u0003אי\u0004 \u0005[או\u0006 נאמר\u0005]\u0006 \u0003מה\u0004 קרבן \u0003חגיגה\u0004 הוא \u0003מבעלי חיים, אף סוכה\u0004 (הסכך) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003בעלי חיים!\u0004 ואין לנו איפוא ראיה מכאן לענין מהות הסכך.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004חג הסוכות תעשה לך שבעת ימים \u0003באספך מגרנך ומיקבך\"\u0004 (דברים טז, יג), ופירשו חכמים כי \u0003בפסולת גורן ויקב הכתוב מדבר,\u0004 שמסככים בקשי השבלים ובענפי הגפנים, ומהם למדו דיני סכך בכללם.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שיעשו את הסכך מ\u0003גורן עצמו ויקב עצמו,\u0004 כלומר: שיסכך בשבלים עם התבואה ובענפי הגפן עם הענבים שעליהם ולא בפסולתם, והלא תבואה וענבים מקבלים טומאה כשאר אוכל! \u0003אמר ר' זירא:\u0004 הלא לא נאמרו ענבים, אלא \u0003\"יקב\"\u0004 שהוא היין \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003כאן, ואי אפשר לסכך בו.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' ירמיה:\u0004 מדוע לא נעשה סכך מיין? \u0003ואימא\u0004 \u0005[ואמור]\u0006 שנעשה סכך מ\u0003יין קרוש הבא משניר\u0004 (מן החרמון) \u0003שהוא דומה לעיגולי דבילה,\u0004 וכיוון שיש בנמצא יין קרוש שאפשר לסכך בו, אין איפוא כל הוכחה מן הפסוק! ואכן \u0003אמר ר' זירא: הא מלתא הוה בידן\u0004 \u0005[דבר זה היה בידינו]\u0006 שדומה היה לנו שיש לנו ראייה מן המקרא, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' ירמיה ושדא ביה נרגא\u0004 \u0005[והטיל בו גרזן,\u0006 קצץ אותו\u0005],\u0006 בכך שהזכיר את היין הבא משניר ובכך הפריך את ההוכחה שנראתה חזקה כל כך.","\u0003רב אשי אמר:\u0004 בכל זאת אפשר לדייק מלשון הכתובים, בדרך זו: \u0003\"מגרנך\",\u0004 כלומר: דבר הבא מן הגורן \u0003ולא גורן עצמו, \"מיקבך\" — ולא יקב עצמו,\u0004 משמע שבפסולת גורן ויקב מדבר הכתוב.","\u0003רב חסדא אמר: מהכא\u0004 \u0005[מכאן]\u0006 מכתוב זה יש להביא הוכחה; שנאמר: \u0003\"צאו ההר והביאו עלי זית ועלי עץ שמן ועלי הדס ועלי תמרים ועלי עץ עבת\u0004 לעשות סוכות ככתוב\u0003\"\u0004 (נחמיה ח, טו) ומכאן אפשר ללמוד ממה נעשית סוכה.","כיוון שהובא כתוב זה שואלים: \u0003היינו\u0004 \u0005[\u0006הרי \u0005זהו]\u0006 \u0003\"הדס\", היינו\u0004 \u0005[\u0006הרי \u0005זהו]\u0006 \u0003\"עץ עבות\",\u0004 שהרי אנו מזהים עץ עבות עם הדס, ולשם מה הכפילות! \u0003אמר רב חסדא:\u0004 כך יש לפרש; ענפי \u0003הדס שוטה,\u0004 שהוא הדס שאיננו ראוי למצות ארבעת המינים, מהם נוטלים \u0003לסוכה\u0004 כדי שישמש כסכך, וענפי \u0003עץ עבות\u0004 שהוא הדס מיוחד שעליו רוכבים זה על זה כעבותות (חבלים) ושרשראות, מהם נוטלים \u0003ללולב.\u0004","\u0003חבילי קש\u0004 הקשורים בחבל, \u0003ו\u0004כן \u0003חבילי עצים\u0004 או \u0003חבילי זרדין\u0004 (ענפים דקים) — \u0003אין מסככין בהן\u0004 כאשר הם צרורים, כאשר יבואר. \u0003וכולן שהתירן,\u0004 אם התיר את הקשר — \u0003כשרות\u0004 לסיכוך. שאין הפגם בחומרים, אלא בכך שהם קשורים כאחד. \u0003וכולן\u0004 אף בהיותם חבילות \u0003כשרות לדפנות\u0004 לסוכה.","\u0003אמר ר' יעקב: שמעית מיניה\u0004 \u0005[שמעתי ממנו]\u0006 מ\u0003ר' יוחנן תרתי\u0004 \u0005[שתיים],\u0006 שתי הלכות בנושאים דומים בדיני סוכה; \u0003חדא\u0004 \u0005[האחת]\u0006 — \u0003הא\u0004 \u0005[זו]\u0006 בענין משנתנו, מדוע אין לסכך בחבילות, \u0003ואידך\u0004 \u0005[והאחרת]\u0006 בפירוש המשנה שנאמר בה: \u0003החוטט\u0004 העושה חלל בתוך \u0003גדיש\u0004 של תבואה \u0003לעשות לו\u0004 על ידי כך \u0003סוכה,\u0004 שמוציא חלק מן העומרים העומדים בתחתית הגדיש ובכך נוצר חלל המוקף ומכוסה בכל צידיו בתבואה ונראה כסוכה עם דפנות וסכך — \u0003אינה סוכה.\u0004 ושמעתי מפי ר' יוחנן טעם לאיסורים הללו.","\u0003חדא\u0004 \u0005[\u0006לגבי משנה \u0005אחת]\u0006 היה הטעם: \u0003משום גזרת אוצר,\u0004 שאף שסוכה כזו כשרה בעצם, בכל זאת גזרו חכמים שלא ישתמש בה, שמא יבוא להשתמש במחסן (אוצר) שיש לו כסוכה, ולא יעשה סוכה כראוי וכדינה. \u0003וחדא\u0004 \u0005[ו\u0006לגבי משנה \u0005אחת]\u0006 היה הטעם \u0003משום\u0004 שאמרה תורה: \u0003\"תעשה\"\u0004 ומשמעו: \u0003ולא מן העשוי\u0004 ומוכן כבר, שלא נעשה מעשה של הכנה ועשייה בסוכה זו. אולם \u0003ולא ידענא\u0004 \u0005[ואינני יודע]\u0006 כעת \u0003הי מינייהו\u0004 \u0005[איזו מהן]\u0006 אמר שטעמה \u0003משום אוצר והי מינייהו\u0004 \u0005[ואיזו מהן]\u0006 \u0003משום תעשה ולא מן העשוי.\u0004","\u0003אמר ר' ירמיה: ניחזי אנן\u0004 \u0005[נראה אנחנו],\u0006 כלומר: נעיין אנו בעצמנו ונמצא למה נתכוון ר' יוחנן. ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מפני מה אמרו\u0004 חכמים כי \u0003חבילי קש וחבילי עצים וחבילי זרדין אין מסככין בהן — פעמים שאדם בא מן השדה בערב וחבילתו\u0004 של עצים וקש \u0003על כתפו ומעלה\u0004 את החבילה \u0003ומניחה על גבי סוכתו\u0004 המשמשת כמחסן וכיוצא בזה \u0003כדי ליבשה, ונמלך עליה\u0004 בהגיע חג הסוכות \u0003לסיכוך,\u0004 להשתמש בסוכה זו ובחבילה שעליה למצות סוכה, \u0003והתורה אמרה \"תעשה\" — ולא מן העשוי.\u0004 ומלשון ר' יוחנן מובן כי האיסור לסכך בחבילות מקורו בגזירה שמא ישתמש בחבילות שלא נעשו מעיקרן לשם מצות סוכה, ואין בו איסור מהותי. \u0003ומדהא\u0004 \u0005[ומכיוון ש\u0006משנה \u0005זו]\u0006 טעמה \u0003משום גזרת אוצר,\u0004 אם כן \u0003הא\u0004 \u0005[זו]\u0006 המשנה האחרת בדין החוטט בגדיש אסורה \u0003משום \"תעשה ולא מן העשוי\".\u0004","ושואלים: \u0003ור' יעקב\u0004 עצמו משום מה לא יכול היה לפתור את בעייתו בדרך זו? ומסבירים: משום ש\u0003הך\u0004 \u0005[אותה]\u0006 שמועה שנמסרה בשם \u0003ר' חייא בר אבא לא שמיע ליה\u0004 \u0005[שמע אותה]\u0006 וכיוון שלא ידע עליה לא יכול להכריע מדעת עצמו.","\u0003אמר רב אשי:\u0004 עצם דבריו של ר' יוחנן תמוהים, שהוא מחלק בין שני טעמים אלה. \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003חבילי קש וחבילי עצים משום גזרת אוצר איכא\u0004 \u0005[יש]\u0006 מקום לגזור, \u0003ומשום \"תעשה ולא מן העשוי\" ליכא\u0004 \u0005[אין]\u0006 מקום לגזור? והלא זהו הטעם הבסיסי לגזירת אוצר! ולהיפך: \u0003והחוטט בגדיש, משום תעשה ולא מן העשוי איכא\u0004 \u0005[יש]\u0006 מקום לאסור, \u0003ומשום גזרת אוצר ליכא\u0004 \u0005[אין]\u0006 מקום לגזור? אלא ודאי אין לחלק בין המשניות, ובשתיהן קיים אותו טעם עצמו.","ומעירים: \u0003ור' יוחנן אמר\u0004 \u0005[היה יכול לומר]\u0006 \u0003לך\u0004 על קושיית רב אשי, שאין הדבר כן, לפי שיש שינוי סגנון בלשון המשנה; \u0003הכא דקתני\u0004 \u0005[כאן\u0006 במשנתנו בחבילי קש \u0005ששנה]\u0006 \u0003\"אין מסככין בהן\",\u0004 משמע כי \u0003לכתחלה הוא\u0004"],["\u0003דאין מסככין משום גזרת אוצר\u0004 שגזרו חכמים, \u0003הא דאורייתא שפיר דמי\u0004 \u0005[הרי מן התורה יפה,\u0006 טוב, \u0005הדבר]\u0006 ומותר לסכך. ואילו \u0003התם דקתני\u0004 \u0005[שם\u0006 במשנת החוטט בגדיש \u0005ששנה]\u0006 \u0003\"אינה סוכה\",\u0004 הרי זו לשון הדגשה, לומר: \u0003אפילו דיעבד, מדאורייתא נמי\u0004 \u0005[לאחר מעשה, מן התורה גם כן]\u0006 \u0003אינה סוכה\u0004 כלל, ולא רק משום גזירת חכמים.","\u0003אמר רב יהודה אמר רב: סככה\u0004 את הסוכה \u0003בחיצין זכרים\u0004 חיצים העשויים מעץ ומותקנים בדרך שהם עצמם בולטים ונכנסים לבית מושב מיוחד של ראש החץ העשוי מתכת — הרי זו \u0003כשרה,\u0004 שכן חיצים אלה, ללא חלק המתכת שלהם, הם פשוטי כלי עץ ואינם מקבלים טומאה וכשרים. אולם אם סיככה בחיצים \u0003נקבות,\u0004 שיש בתוכם בית קיבול קטן כדי להכניס את מקום מושב ראש החץ העשוי מתכת — \u0003פסולה,\u0004 שחיצים אלה הם מקבלי כלי עץ שהרי יש להם בית קיבול כלשהו, ומקבלים בשל כך טומאה ופסולים מלסכך בהם.","ושואלים: מה שאמר כי בחיצים \u0003זכרים כשרה, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי אינם אלא כקנים ישרים וחלקים! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003ניגזור\u0004 איסור על חיצים \u0003זכרים אטו\u0004 \u0005[משום]\u0006 חיצים \u0003נקבות,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים, והם כשרים.","ומוסיפים לשאול על מה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 כי כשסיככה בחיצים \u0003בנקבות\u0004 הריהי \u0003פסולה,\u0004 ויש לתמוה: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הלא הם כלי קיבול של עץ וטמאים! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003בית קבול\u0004 כזה \u0003העשוי למלאות,\u0004 שהרי עשוי להכניס בו את קצה החץ באופן קבוע, ואז לא ישמש עוד כבית קיבול העשוי להכניס ולהוציא מתוכו, ולכך \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 כבית \u0003קבול,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת הריהו נחשב כבית קיבול, ואסור.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: סככה\u0004 לסוכתו \u0003באניצי פשתן,\u0004 שהם צרורות פשתן סרוק — הריהי \u0003פסולה,\u0004 שפשתן זה נעשה כבר חומר גולמי לעשיית חוטים ומקבל טומאה. אם סככה \u0003בהוצני פשתן\u0004 בגבעולי הפשתן כמו שהם גדלים, בלא כל עיבוד — הרי הסוכה \u0003כשרה,\u0004 שכל עוד לא הוכשרו למלאכתם, דינם כעץ ממש. \u0003והושני פשתן,\u0004 שהם שלב ביניים בהכנת הפשתן, \u0003איני יודע מהו\u0004 דינם, אם כשרים הם לסיכוך או פסולים.","והוסיף רבה בר בר חנה: \u0003והושני עצמן איני יודע\u0004 מה משמעם, שאיני יודע לאיזו דרגה של עיבוד קרא ר' יוחנן הושני. \u0003מה נפשך\u0004 \u0005[מה יכול אתה לומר];\u0006 \u0003אי דייק ולא נפיץ הושני קרי ליה\u0004 \u0005[אם\u0006 הפשתן \u0005שנידוך\u0006 במכתשת \u0005ולא נופץ עדיין קרוי הושני]\u0006 \u0003אבל תרי ולא דייק הוצני קרי ליה\u0004 \u0005[\u0006פשתן \u0005השרוי\u0006 במים \u0005ולא נידוך\u0006 עדיין כלל, \u0005הוצני קורא לו],\u0006 לפי שלא נעשתה מלאכה בגופו, \u0003או דלמא\u0004 אף \u0003תרי ולא דייק נמי הושני קרי ליה\u0004 \u0005[שמא שרוי ולא נדוך גם כן הושני קוראים לו]\u0006 ואין קוראים הוצני אלא לפשתן שלא נעשה בו כל עיבוד.","\u0003אמר רב יהודה: הני\u0004 \u0005[אותם]\u0006 \u0003שושי ושווצרי\u0004 שהם עלים רחבים של מיני ירקות — \u0003מסככין בהו\u0004 \u0005[בהם],\u0006 כי אינם נחשבים למאכל אדם, ודינם כשאר צמחים. \u0003אביי אמר: בשושי מסככין, בשווצרי לא מסככין.\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005],\u0006 \u0003כיון\u0004"],["\u0003דסרי ריחייהו\u0004 \u0005[כיון שמבאיש ריחם]\u0006 לאחר זמן \u0003שביק להו ונפיק\u0004 \u0005[מניח אותם ויוצא\u0006 מן הסוכה\u0005]\u0006 ואין לעשות סוכה שאי אפשר לשבת בה.","וכעין זה \u0003אמר רב חנן בר רבא: הני\u0004 \u0005[אותם]\u0006 \u0003היזמי והיגי\u0004 שהם מיני קוצים \u0003מסככין בהו\u0004 \u0005[בהם].\u0006 ואילו \u0003אביי אמר: בהיזמי מסככינן\u0004 \u0005[מסככים אנו]\u0006 \u0003בהיגי לא מסככינן\u0004 \u0005[אין אנו מסככים]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005]\u0006 — \u0003כיון דנתרי טרפייהו\u0004 \u0005[שנושרים עליהם]\u0006 במשך הזמן ועשויים ליפול לתוך דברי מאכל ולהפריע ליושבי הסוכה, לכך \u0003שביק לה ונפיק\u0004 \u0005[עוזב אותה\u0006 את הסוכה \u0005ויוצא].\u0006","\u0003אמר רב גידל אמר רב: האי אפקותא דדיקלא\u0004 \u0005[\u0006ענפי \u0005הדקל היוצאים\u0006 מתחילת הגזע\u0005]\u0006 \u0003מסככין בהו\u0004 כמות שהם יחד. ו\u0003אף על גב דאגידי\u0004 \u0005[אף על פי שהם אגודים],\u0006 מכל מקום \u0003אגד\u0004 שנעשה \u0003בידי שמים\u0004 שבדרך הטבע הדברים מחוברים יחד \u0003לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003אגד\u0004 וכשר. יתר על כן, \u0003אף על גב דהדר אגיד להו\u0004 \u0005[אף על פי שהוא חוזר וקושר אותם]\u0006 מן הצד השני שבו הענפים מפורדים, מכל מקום כשר הוא, כי דבר האגוד כבר מצד עצמו אם הוסיף ו\u0003איגד\u0004 וקשר רק \u0003בחד\u0004 \u0005[באחד],\u0006 כלומר: הוסיף לאוגדו בפני עצמו בלא להוסיף לאגודה זו דבר אחר, \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו קרוי\u0005]\u0006 \u0003אגד\u0004 ולכך אינו פסול לסיכוך.","וכן \u0003אמר רב חסדא אמר רבינא בר שילא: הני דוקרי דקני\u0004 \u0005[אותם קנים\u0006 היוצאים יחד ממקום אחד\u0005]\u0006 \u0003מסככין בהו\u0004 \u0005[בהם]\u0006 כמות שהם. ו\u0003אף על גב דאגידי נינהו\u0004 \u0005[אף על פי שאגודים הם]\u0006 — \u0003אגד בידי שמים לא שמיה\u0004 \u0005[אין שמו,\u0006 איננו נחשב\u0005]\u0006 \u0003אגד.\u0004 ויתר על כן; \u0003אף על גב דהדר אגיד להו\u0004 \u0005[אף על פי שהוא חוזר ואוגד אותם\u0006 בצד האחר\u0005]\u0006 — \u0003איגד בחד לא שמיה\u0004 \u0005[קשר בצד אחד אין שמו,\u0006 איננו נחשב\u0005]\u0006 \u0003אגד.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003קנים ודוקרנין מסככין בהן.\u0004 ויש לתהות: \u0003קנים פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 שמסככין בהן, שהרי קיימים בהם כל המידות שמנו חכמים בסכך כשר! אלא \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003קנים של דוקרנין\u0004 אף שהם צומחים אגודים יחד (דוקרני דקני), בכל זאת \u0003מסככין בהן.\u0004","אגב דברים אלה, מביאים דבר אחר שמסר רב חסדא בשם אותו חכם. \u0003אמר רב חסדא אמר רבינא בר שילא: הני מרריתא דאגמא\u0004 \u0005[אותו מרור,\u0006 חזרת \u0005של אגם]\u0006 \u0003אדם יוצא בהן ידי חובתו בפסח\u0004 בקיום מצות מרור.","על כך \u0003מיתיביה\u0004 \u0005[מקשים עליו]:\u0006 הלא שנינו כי בכל מצוה שלשם קיומה דרוש אזוב, יש ליטול לשם כך \u0003אזוב\u0004 סתם דווקא, ולא כל מין אחר אף המינים הקרובים, \u0003לא אזוב יון ולא אזוב כוחלי, ולא אזוב מדברי, ולא אזוב רומי ולא\u0004 כל \u0003אזוב\u0004 אחר \u0003שיש לו שם לווי.\u0004 ומכאן נלמד שכל מין שיש לו שם לווי איננו המין הכתוב בתורה, ואף מרור האגם כיון שיש לו שם לווי אינו מרור האמור בתורה!","על כך \u0003אמר אביי:\u0004 יש לחלק בין הדברים, \u0003כל שנשתנה שמו קודם מתן התורה,\u0004 כלומר: שהחלוקה בין המינים השונים קדומה, והיתה קיימת עוד לפני מתן תורה, \u0003ובאתה תורה והקפידה עליה\u0004 \u0005[עליו]\u0006 לקרוא לו בשם מסויים אחד — \u0003בידוע שיש לו\u0004 מינים קרובים שלהם \u0003שם לווי,\u0004 וכל דבר שיש לו שם לווי פסול, חוץ ממין זה שאמרה התורה במפורש. \u0003והני\u0004 \u0005[אלו]\u0006 \u0003לא נשתנה שמייהו\u0004 \u0005[שמם]\u0006 \u0003קודם מתן תורה כלל,\u0004 שמרור האגם לא היה לו שם מיוחד לפני מתן תורה, ולפי התורה הכל מין מרור ולא הקפידה התורה בפרטיו.","\u0003רבא אמר\u0004 הסבר אחר: \u0003הני\u0004 \u0005[אלו\u0006 המינים\u0005]\u0006 — \u0003\"מרריתא\" סתמא שמייהו\u0004 \u0005[\"מרור\" סתם שמם],\u0006 שאינם כלל מין בפני עצמו \u0003והאי דקרי להו \"מרריתא דאגמא\"\u0004 \u0005[וזה שקורים להם \"מרור האגם\"]\u0006 — \u0003משום דמשתכח באגמא\u0004 \u0005[ש\u0006הוא \u0005נמצא באגם]\u0006 ואין זה שם מין לעצמו, ואין מקום לאוסרו.","\u0003אמר רב חסדא איגד בחד\u0004 \u0005[באחד],\u0006 כלומר: דבר אחד בפני עצמו, גם אם עשה בו קשר — \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו קרוי\u0005]\u0006 \u0003אגד\u0004 (קשר). אגד של \u0003שלש\u0004 יחידות יחד — לכל הדעות \u0003שמיה\u0004 \u0005[שמו\u0006 קרוי\u0005]\u0006 \u0003אגד.\u0004 קשר ב\u0003שנים\u0004 — הרי זו \u0003מחלוקת ר' יוסי ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 כל דין שנאמרה בו בין השאר \u0003מצות אזוב,\u0004 הכוונה היא ל\u0003שלשה קלחים\u0004 (צמחים עם שורש) \u0003ובהן\u0004 בכל אחד מהן \u0003שלשה גבעולין. ר' יוסי אומר: מצות אזוב\u0004 מעיקרה צריכה שתהיה ב\u0003שלשה גבעולין. ושיריו\u0004 — אם אירע שנפגמה האגודה — אפילו \u0003שנים, וגרדומיו\u0004 אם נשברו הענפים תוך כדי הזייה כשרים \u0003כל שהוא.\u0004","\u0003קא סלקא דעתין\u0004 \u0005[עלה בדעתנו\u0006 לומר\u0005]\u0006 כיון שאומר ר' יוסי ש\u0003שיריו\u0004 של אגד האזוב \u0003שנים, תחילתו נמי\u0004 \u0005[גם כן]\u0006 יספיקו לו בדיעבד \u0003שנים, והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003שלשה\u0004 אינו אלא \u0003למצוה\u0004 מן המובחר מלכתחילה. \u0003ומ\u0004כיון שלדברי \u0003ר' יוסי\u0004 מה שאמר \u0003שלשה\u0004 הוא דווקא \u0003למצוה,\u0004 מזה נלמד כי \u0003לרבנן שלשה\u0004 שאמרו הוא \u0003לעכב.\u0004 ולפי זה חלוקים ר' יוסי וחכמים אם אגודה היא שלושה דווקא, אם לאו.","על הסבר זה של המשנה מקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בפירוש לא כן, \u0003ר' יוסי אומר: אזוב\u0004 אם \u0003תחילתו שנים ושיריו אחד — פסול, ואינו כשר עד שיהא תחילתו שלשה ושיריו שנים!\u0004 אלא \u0003איפוך\u0004 \u0005[הפוך]\u0006 את הסבר הדברים במשנה ראשונה ופרש אותה כך: \u0003לר' יוסי שלשה לעכב,\u0004 ואילו \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003שלשה\u0004 הם רק \u0003למצוה.\u0004","וראיה לדבר; \u0003והתניא\u0004 \u0005[והרי\u0006 כן \u0005שנינו\u0006 בברייתא מפורשת\u0005]:\u0006 \u0003אזוב\u0004 אם \u0003תחילתו שנים ושיריו אחד — כשר, ואינו פסול עד שיהא תחילתו ושיריו אחד\u0004 ושיטה זו ודאי שיטת חכמים היא.","על עצם לשונה של ברייתא אחרונה זו תוהים: \u0003שיריו אחד פסול? הא אמרת\u0004 \u0005[הרי אמרת]\u0006 בחלקה הראשון של הברייתא ש\u0003שיריו אחד כשר!\u0004"],["\u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הנוסח כך: \u0003עד שתהא תחילתו כשיריו אחד\u0004 ואז ודאי פסול הוא.","\u0003דרש מרימר: הני איסורייתא\u0004 \u0005[אותן חבילות קנים]\u0006 שעושים ב\u0003סורא\u0004 כדי למוכרן, ונמכרות לפי מספר הקנים שבהן — \u0003מסככין בהו\u0004 \u0005[בהן]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אגדן\u0004 יחד. וטעם הדבר \u0005— כי\u0006 \u0003למנינא בעלמא\u0004 \u0005[למנין בלבד]\u0006 \u0003הוא\u0004 ש\u0003אגדן\u0004 ואינן עשויות להשאירן כחבילה.","\u0003אמר ר' אבא: הני צריפי דאורבני\u0004 \u0005[אותן סככות של ערבות]\u0006 \u0003כיון שהותרה ראשי מעדנים שלהן\u0004 שהוא הקשר העליון הקושר אותן — \u0003כשרין\u0004 לסכך בהן. ומקשים: \u0003והא אגידי מתתאי\u0004 \u0005[והרי אגודים הם עדיין מלמטה]!\u0006 \u0003אמר רב פפא: דשרי להו\u0004 \u0005[שמתיר אותם]\u0006 גם מלמטה.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003דלא שרי להו\u0004 \u0005[ושאינו מתיר אותם],\u0006 אלא טעמו של דבר \u0003כל אגד שאינו עשוי לטלטלו\u0004 שמאחר והתיר את הקשר, אם יטלטלוהו יתפרק כולו — \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו קרוי\u0005]\u0006 \u0003אגד.\u0004","\u0003אמר ר' אבא אמר שמואל:\u0004 אותם \u0003ירקות שאמרו חכמים\u0004 כי \u0003אדם יוצא בהן ידי חובתו בפסח\u0004 לשם מרור, \u0003מביאין את הטומאה.\u0004 שטומאת מת המצויה תחתיהן מתפשטת הלאה, כמו כל טומאה מכוסה, אבל בכל זאת גזרו חכמים ש\u0003אין\u0004 הם \u0003חוצצין בפני הטומאה.\u0004 וכן \u0003פוסלין\u0004 ירקות אלה \u0003בסוכה,\u0004 אם סיכך בהם, \u0003משום אויר,\u0004 שנחשבים כאילו לא היו שם כלל. ולכן כמו באויר, אף הם פוסלים את הסוכה בשלושה טפחים. \u0003מאי טעמא\u0004 \u0005[מה טעמה]\u0006 של הלכה זו — \u0003כיון דלכי יבשי פרכי ונפלי\u0004 \u0005[שכאשר הם מתייבשים, הרי הם נפרכים ונופלים],\u0006 \u0003כמאן דליתנהו דמי\u0004 \u0005[כמי שאינם נחשבים\u0006 הם\u0005],\u0006 אפילו בהיותם עדיין לחים ושלימים.","כיון שהבאנו מדברי הלכה של ר' אבא, מביאים הלכה נוספת שמסר; \u0003ואמר ר' אבא אמר רב הונא: הבוצר\u0004 אשכולות ענבים \u0003לגת\u0004 לעשות מהם יין — \u0003אין לו ידות.\u0004 שאותם הגבעולים להם מחוברים הענבים באשכולות, אינם נחשבים להלכה כידיות לאשכול, שהרי אינם דרושים לתעשיית היין ואינם אלא כפסולת, ולכן אם נגעה טומאה בגבעולים הללו, אין בכך כדי לטמא את הענבים עצמם, אפילו בעודם מחוברים.","\u0003ורב מנשיא בר גדא אמר רב הונא: הקוצר לסכך אין לו ידות,\u0004 שאין הקש נחשב כידות לשבלים שכן לצורך סיכוך אינו מעוניין בשבלים (שהן פסולות כשלעצמן לסכך בהן) אלא בקש, והקש אינו נחשב איפוא כמכשיר לטלטול השבלים.","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 כי \u0003קוצר\u0004 אין לו ידות — \u0003כל שכן\u0004 שהוא סבור שאין ידות ב\u0003בוצר,\u0004 ש\u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 כלל במציאותם של אותם גבעולים באשכול, ש\u0003לא נימצייה לחמריה\u0004 \u0005[יתמצה יינו],\u0006 כי חלק יתר זה סופג לתוכו מן היין והרי סופו להזרק. אולם \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 \u0003בוצר אין לו ידות, אבל קוצר — יש לו ידות, דניחא ליה דליסכך בהו\u0004 \u0005[שנוח לו לסכך בהם]\u0006 עם השבלים, \u0003כי היכי דלא ליבדרן\u0004 \u0005[כדי שלא יתפזרו]\u0006 קני הקש זה מזה. ולכן אפשר לומר שכיון שרוצה בהן הריהם נחשבים.","ומציעים: \u0003נימא\u0004 \u0005[האם נאמר]\u0006 כי דבריו של \u0003רב מנשיא בר גדא תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא]\u0006 \u0003היא\u0004 בדבר? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סוכי\u0004 (ענפי) \u0003תאנים ובהן תאנים, פרכילין\u0004 (זמורות) \u0003ובהן ענבים, קשין ובהן שבלים, מכבדות\u0004 (ענפים) \u0003ובהן תמרים\u0004 — \u0003כולן, אם פסולת מרובה על האוכלין — כשרה\u0004 לסכך, \u0003ואם לאו — פסולה. אחרים אומרים: עד שיהו קשין מרובין\u0004 בכמותם \u0003על הידות\u0004 (הטפח הסמוך לאוכל וצריך הוא לו, ולכן אף מקבל טומאה ויש לבטלו) \u0003ועל האוכלין\u0004 יחד.","ונדייק: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003בהא קא מיפלגי\u0004 \u0005[ב\u0006רעיון \u0005זה נחלקו]\u0006 \u0003דמר\u0004 \u0005[שחכם זה],\u0006 הסבור שצריך קשים מרובים על הידות, \u0003סבר\u0004 כי \u0003יש להן ידות, ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר\u0004 כי \u0003אין להן ידות!\u0004","ומעירים: \u0003ל\u0004שיטתו של \u0003רב אבא\u0004 שלבוצר אין ידות ולקוצר יש — \u0003ודאי תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 שהרי בבירור אומר הוא כאחרים שהקוצר לסכך יש לו ידות. אבל \u0003ל\u0004שיטת \u0003רב מנשיא בר גדא\u0004 שהקוצר לסכך אין לו ידות \u0003מי לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בכך והוא עצמו סובר כשיטת התנא קמא? \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב מנשיא: דכולי עלמא סברי\u0004 \u0005[הכל סבורים]\u0006 כי \u0003הקוצר לסכך אין לו ידות. והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים],\u0006 במקרה מיוחד — \u0003כגון שקוצצן\u0004 מתחלה \u0003לאכילה ונמלך\u0004 (והחליט) \u0003עליהן\u0004 אחר כך לשנות את יעודן המקורי שישמשו \u0003לסיכוך,\u0004 ולכן מתחילה כבר היו להן ידות.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003קוצצן לאכילה — מאי טעמייהו דרבנן\u0004 \u0005[מהו\u0006 איפוא \u0005טעמם של חכמים]\u0006 הסוברים שאין להם ידות? הרי הלכה היא שלסתם שבלים יש ידות! \u0003וכי תימא קסברי רבנן\u0004 \u0005[ואם תאמר\u0006 ש\u0005סבורים חכמים]\u0006 \u0003כיון\u0004 ש\u0003נמלך עליהן לסיכוך, בטלה לו מחשבתו\u0004 הראשונה שחשב עליהן לאכילה, והפכו להיות כשאר סכך שאינו עשוי לאכילה, וממילא גם בטל דין ידות מקצות השבלים. אולם, \u0003ומי בטלה ליה מחשבה\u0004 \u0005[והאם בטלה לו]\u0006 \u0003בהכי\u0004 \u0005[בכך],\u0006 שהחלטה ראשונה שהחליט בדבר יעודם של השבלים תתבטל על ידי החלטה אחרת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הכלים\u0004"]]};
